window.SOHOG_SQ={"c10":{"1":[{"n":"b1","q":"0.454545… কে সাধারণ ভগ্নাংশে প্রকাশ কর।","a":"x = 0.4545… হলে 100x = 45.4545…\n99x = 45 ⇒ x = 45/99 = 5/11","lv":"মধ্যম"},{"n":"b2","q":"1.2345345… (345 আবৃত্ত) কে সাধারণ ভগ্নাংশে প্রকাশ কর।","a":"= (12345 − 12)/9990 = 12333/9990 = 4111/3330","lv":"কঠিন"},{"n":"b3","q":"3.070707… কে সাধারণ ভগ্নাংশে প্রকাশ কর।","a":"= 3 + 7/99 = 304/99","lv":"মধ্যম"},{"n":"b4","q":"0.2666… কে সাধারণ ভগ্নাংশে প্রকাশ কর।","a":"= (26 − 2)/90 = 24/90 = 4/15","lv":"মধ্যম"},{"n":"b5","q":"প্রমাণ কর যে, √3 একটি অমূলদ সংখ্যা।","a":"ধরি √3 = p/q (p, q সহমৌলিক, q ≠ 0)।\n⇒ p² = 3q², তাই p², ফলে p, 3 দ্বারা বিভাজ্য। p = 3k ধরলে 9k² = 3q² ⇒ q² = 3k², তাই q-ও 3 দ্বারা বিভাজ্য।\np, q উভয়ের সাধারণ উৎপাদক 3 — যা সহমৌলিক ধারণার বিরোধী। ∴ √3 অমূলদ।","lv":"কঠিন"},{"n":"b6","q":"প্রমাণ কর যে, 2 + √3 একটি অমূলদ সংখ্যা।","a":"ধরি 2 + √3 = r মূলদ। তাহলে √3 = r − 2, যা মূলদ (মূলদ − মূলদ = মূলদ)।\nকিন্তু √3 অমূলদ — বিরোধ। ∴ 2 + √3 অমূলদ।","lv":"মধ্যম"},{"n":"b7","q":"প্রমাণ কর যে, √2 + √5 একটি অমূলদ সংখ্যা।","a":"ধরি √2 + √5 = r মূলদ। বর্গ করে r² = 7 + 2√10 ⇒ √10 = (r² − 7)/2, যা মূলদ।\nকিন্তু √10 অমূলদ — বিরোধ। ∴ √2 + √5 অমূলদ।","lv":"কঠিন"},{"n":"b8","q":"0.31 ও 0.32 এর মধ্যে দুইটি অমূলদ সংখ্যা নির্ণয় কর।","a":"যেমন: 0.3101001000100001… এবং 0.3120120012000120…\n(দশমিকের পরের অঙ্কগুলো অসীম ও অনাবৃত্ত, তাই এরা অমূলদ)","lv":"মধ্যম"},{"n":"b9","q":"0.333… + 0.454545… এর যোগফল আবৃত্ত দশমিকে প্রকাশ কর।","a":"= 1/3 + 5/11 = 26/33 = 0.787878…","lv":"কঠিন"},{"n":"b10","q":"2.555… × 0.333… এর মান সাধারণ ভগ্নাংশে নির্ণয় কর।","a":"2.555… = 23/9, 0.333… = 1/3\nগুণফল = 23/27","lv":"কঠিন"},{"n":"b11","q":"5/7 কে দশমিক ভগ্নাংশে প্রকাশ কর এবং আবৃত্ত অংশ চিহ্নিত কর।","a":"5/7 = 0.714285714285…\nআবৃত্ত অংশ: 714285 (ছয় অঙ্ক)","lv":"মধ্যম"},{"n":"b12","q":"1/13 কে দশমিকে প্রকাশ করলে আবৃত্ত অংশে কয়টি অঙ্ক থাকবে? দেখাও।","a":"1/13 = 0.076923076923…\nআবৃত্ত অংশ 076923, অর্থাৎ 6টি অঙ্ক।","lv":"মধ্যম"},{"n":"b13","q":"3.14159265 সংখ্যাটির চার দশমিক স্থান পর্যন্ত আসন্ন মান এবং তিন অঙ্ক পর্যন্ত তাৎপর্যপূর্ণ মান নির্ণয় কর।","a":"চার দশমিক স্থান পর্যন্ত: 3.1416\nতিন তাৎপর্যপূর্ণ অঙ্ক পর্যন্ত: 3.14","lv":"মধ্যম"},{"n":"b14","q":"√7 এর মান তিন দশমিক স্থান পর্যন্ত নির্ণয় কর।","a":"√7 = 2.64575… ≈ 2.646","lv":"মধ্যম"},{"n":"b15","q":"√3, 1.7373… এবং 1.732 সংখ্যাগুলোকে মানের ঊর্ধ্বক্রমে সাজাও।","a":"√3 = 1.7320508…\n∴ 1.732 < √3 < 1.7373…","lv":"কঠিন"},{"n":"b16","q":"0.0909… কে সাধারণ ভগ্নাংশে প্রকাশ কর।","a":"x = 0.0909… ⇒ 100x = 9.0909…\n99x = 9 ⇒ x = 1/11","lv":"মধ্যম"},{"n":"b17","q":"x = 0.333… হলে 3x + 1/x এর মান নির্ণয় কর।","a":"x = 1/3\n3x + 1/x = 1 + 3 = 4","lv":"মধ্যম"},{"n":"b18","q":"a = √2 + 1 হলে a + 1/a এর মান নির্ণয় কর এবং এটি মূলদ না অমূলদ বল।","a":"1/a = 1/(√2 + 1) = √2 − 1\na + 1/a = 2√2, যা অমূলদ।","lv":"কঠিন"},{"n":"b19","q":"(√5 + √3)(√5 − √3) মূলদ না অমূলদ? দেখাও।","a":"= (√5)² − (√3)² = 5 − 3 = 2, যা মূলদ।","lv":"মধ্যম"},{"n":"b20","q":"(√3 + 1)² মূলদ না অমূলদ? দেখাও।","a":"= 3 + 2√3 + 1 = 4 + 2√3\n2√3 অমূলদ, তাই 4 + 2√3 অমূলদ।","lv":"মধ্যম"},{"n":"b21","q":"0.1222… + 0.343434… এর মান সাধারণ ভগ্নাংশে নির্ণয় কর।","a":"0.1222… = 11/90, 0.3434… = 34/99\nযোগফল = (121 + 340)/990 = 461/990","lv":"কঠিন"},{"n":"b22","q":"1.222… − 0.454545… এর মান আবৃত্ত দশমিকে প্রকাশ কর।","a":"= 11/9 − 5/11 = (121 − 45)/99 = 76/99 = 0.767676…","lv":"কঠিন"},{"n":"b23","q":"0.333… × 0.666… এর মান আবৃত্ত দশমিকে প্রকাশ কর।","a":"= 1/3 × 2/3 = 2/9 = 0.222…","lv":"মধ্যম"},{"n":"b24","q":"প্রমাণ কর যে, যেকোনো দুইটি ক্রমিক স্বাভাবিক সংখ্যার গুণফল জোড়।","a":"ক্রমিক সংখ্যা n ও n + 1 এর একটি অবশ্যই জোড়।\n∴ n(n + 1) জোড়।","lv":"মধ্যম"},{"n":"b25","q":"প্রমাণ কর যে, দুইটি বিজোড় সংখ্যার বর্গের সমষ্টি জোড় সংখ্যা।","a":"(2m + 1)² + (2n + 1)² = 4m² + 4m + 4n² + 4n + 2\n= 2(2m² + 2m + 2n² + 2n + 1), যা জোড়।","lv":"মধ্যম"},{"n":"b26","q":"প্রমাণ কর যে, যেকোনো বিজোড় সংখ্যার বর্গ থেকে 1 বিয়োগ করলে বিয়োগফল 8 দ্বারা বিভাজ্য।","a":"(2n + 1)² − 1 = 4n² + 4n = 4n(n + 1)\nn(n + 1) জোড়, তাই 4n(n + 1), 8 দ্বারা বিভাজ্য।","lv":"কঠিন"},{"n":"b27","q":"47 মৌলিক সংখ্যা কি না যাচাই কর।","a":"√47 < 7, তাই 7 এর ছোট মৌলিক 2, 3, 5 দিয়ে যাচাই করি।\n47 এদের কোনোটি দিয়ে বিভাজ্য নয়। ∴ 47 মৌলিক।","lv":"মধ্যম"},{"n":"b28","q":"1/7 কে দশমিকে প্রকাশ করলে দশমিক বিন্দুর পরের 100তম অঙ্কটি কত?","a":"1/7 = 0.142857142857…, আবৃত্ত অংশে 6টি অঙ্ক।\n100 = 6 × 16 + 4, তাই 100তম অঙ্ক = আবৃত্ত অংশের 4র্থ অঙ্ক = 8","lv":"কঠিন"},{"n":"b29","q":"0.555… এবং 0.5 এর অন্তর সাধারণ ভগ্নাংশে নির্ণয় কর।","a":"= 5/9 − 1/2 = 1/18 = 0.0555…","lv":"মধ্যম"},{"n":"b30","q":"0.142857142857… কে সাধারণ ভগ্নাংশে প্রকাশ কর।","a":"x = 0.142857… ⇒ 1000000x − x = 142857\nx = 142857/999999 = 1/7","lv":"কঠিন"}],"10":[{"n":"b1","q":"একটি টাওয়ারের উচ্চতা 30 মিটার। মাটির একটি বিন্দু থেকে টাওয়ারের শীর্ষের উন্নতি কোণ 60° হলে বিন্দুটি থেকে টাওয়ারের পাদদেশের দূরত্ব নির্ণয় কর।","a":"tan60° = 30/d ⇒ d = 30/√3 = 10√3 ≈ 17.32 মিটার","lv":"মধ্যম"},{"n":"b2","q":"10 মিটার লম্বা একটি মই দেয়ালে হেলান দিয়ে রাখায় মাটির সাথে 60° কোণ উৎপন্ন করে। মইটি দেয়ালের কত উচ্চতায় পৌঁছায়?","a":"উচ্চতা = 10 sin60° = 5√3 ≈ 8.66 মিটার","lv":"মধ্যম"},{"n":"b3","q":"একটি খুঁটির ছায়ার দৈর্ঘ্য খুঁটির উচ্চতার √3 গুণ। সূর্যের উন্নতি কোণ নির্ণয় কর।","a":"tanθ = h/(√3h) = 1/√3 ⇒ θ = 30°","lv":"মধ্যম"},{"n":"b4","q":"একটি ঘুড়ির সুতার দৈর্ঘ্য 100 মিটার এবং সুতা ভূমির সাথে 30° কোণ উৎপন্ন করে। ঘুড়িটির উচ্চতা নির্ণয় কর।","a":"উচ্চতা = 100 sin30° = 50 মিটার","lv":"মধ্যম"},{"n":"b5","q":"50 মিটার উঁচু একটি দালানের ছাদ থেকে মাটিতে একটি গাড়ির অবনতি কোণ 30°। দালান থেকে গাড়িটির দূরত্ব নির্ণয় কর।","a":"tan30° = 50/d ⇒ d = 50√3 ≈ 86.6 মিটার","lv":"মধ্যম"},{"n":"b6","q":"একটি টাওয়ারের পাদদেশের সাথে একই সরলরেখায় একই পাশে অবস্থিত দুইটি বিন্দু থেকে শীর্ষের উন্নতি কোণ 30° ও 60° এবং বিন্দুদ্বয়ের দূরত্ব 20 মিটার। টাওয়ারের উচ্চতা নির্ণয় কর।","a":"h = x tan60° = (x + 20)tan30° ⇒ 3x = x + 20 ⇒ x = 10\nh = 10√3 ≈ 17.32 মিটার","lv":"কঠিন"},{"n":"b7","q":"ঝড়ে একটি গাছ ভেঙে গিয়ে এর অগ্রভাগ গোড়া থেকে 10 মিটার দূরে মাটির সাথে 30° কোণ উৎপন্ন করে। গাছটির পূর্ণ উচ্চতা নির্ণয় কর।","a":"দাঁড়ানো অংশ = 10 tan30° = 10/√3, ভাঙা অংশ = 10/cos30° = 20/√3\nউচ্চতা = 30/√3 = 10√3 ≈ 17.32 মিটার","lv":"কঠিন"},{"n":"b8","q":"সূর্যের উন্নতি কোণ 45° হলে একটি খুঁটির ছায়ার দৈর্ঘ্য ও উচ্চতার মধ্যে সম্পর্ক কী?","a":"tan45° = h/ছায়া = 1 ⇒ ছায়ার দৈর্ঘ্য = খুঁটির উচ্চতা","lv":"মধ্যম"},{"n":"b9","q":"6 মিটার উঁচু খুঁটির ছায়ার দৈর্ঘ্য 2√3 মিটার। সূর্যের উন্নতি কোণ নির্ণয় কর।","a":"tanθ = 6/(2√3) = √3 ⇒ θ = 60°","lv":"মধ্যম"},{"n":"b10","q":"একটি গাছের পাদদেশ থেকে 50 মিটার দূরের একটি বিন্দু থেকে গাছের শীর্ষের উন্নতি কোণ 45°। গাছের উচ্চতা কত?","a":"h = 50 tan45° = 50 মিটার","lv":"মধ্যম"},{"n":"b11","q":"80 মিটার চওড়া রাস্তার দুই পাশে সমান উচ্চতার দুইটি খুঁটি আছে। রাস্তার মাঝের একটি বিন্দু থেকে খুঁটিদ্বয়ের শীর্ষের উন্নতি কোণ 60° ও 30°। খুঁটির উচ্চতা নির্ণয় কর।","a":"h = x√3 = (80 − x)/√3 ⇒ 3x = 80 − x ⇒ x = 20\nh = 20√3 ≈ 34.64 মিটার","lv":"কঠিন"},{"n":"b12","q":"1.5 মিটার লম্বা একজন ব্যক্তি একটি টাওয়ার থেকে 20 মিটার দূরে দাঁড়িয়ে টাওয়ারের শীর্ষ 60° উন্নতি কোণে দেখেন। টাওয়ারের উচ্চতা নির্ণয় কর।","a":"চোখের উচ্চতা থেকে টাওয়ার = 20 tan60° = 20√3\nউচ্চতা = 1.5 + 20√3 ≈ 36.14 মিটার","lv":"কঠিন"},{"n":"b13","q":"100 মিটার উচ্চতায় একটি বেলুন থেকে বিপরীত পাশে অবস্থিত দুইটি বিন্দুর অবনতি কোণ 30° ও 45°। বিন্দুদ্বয়ের দূরত্ব নির্ণয় কর।","a":"দূরত্ব = 100/tan30° + 100/tan45° = 100√3 + 100 ≈ 273.2 মিটার","lv":"কঠিন"},{"n":"b14","q":"সূর্যের উন্নতি কোণ 60° থেকে 30° হলে একটি স্তম্ভের ছায়ার দৈর্ঘ্য 20 মিটার বেড়ে যায়। স্তম্ভের উচ্চতা নির্ণয় কর।","a":"h√3 − h/√3 = 20 ⇒ h × 2/√3 = 20 ⇒ h = 10√3 ≈ 17.32 মিটার","lv":"কঠিন"},{"n":"b15","q":"একটি জানালা 12 মিটার উঁচুতে। একটি মই মাটির সাথে 60° কোণ করে জানালায় পৌঁছায়। মইয়ের দৈর্ঘ্য নির্ণয় কর।","a":"মই = 12/sin60° = 24/√3 = 8√3 ≈ 13.86 মিটার","lv":"মধ্যম"},{"n":"b16","q":"একটি মইয়ের পাদদেশ দেয়াল থেকে 5 মিটার দূরে এবং মই ভূমির সাথে 60° কোণ উৎপন্ন করে। মইয়ের দৈর্ঘ্য ও দেয়ালে পৌঁছানো উচ্চতা নির্ণয় কর।","a":"মই = 5/cos60° = 10 মিটার\nউচ্চতা = 5 tan60° = 5√3 ≈ 8.66 মিটার","lv":"কঠিন"},{"n":"b17","q":"নদীর তীর থেকে অপর তীরের একটি গাছের শীর্ষের উন্নতি কোণ 60°। তীর থেকে 40 মিটার পিছিয়ে গেলে উন্নতি কোণ 30° হয়। নদীর প্রস্থ ও গাছের উচ্চতা নির্ণয় কর।","a":"h = x√3 = (x + 40)/√3 ⇒ 3x = x + 40 ⇒ x = 20\nপ্রস্থ 20 মিটার, উচ্চতা 20√3 ≈ 34.64 মিটার","lv":"কঠিন"},{"n":"b18","q":"10 মিটার উঁচু একটি বাড়ির ছাদ থেকে একটি টাওয়ারের শীর্ষের উন্নতি কোণ 60° এবং পাদদেশের অবনতি কোণ 30°। টাওয়ারের উচ্চতা নির্ণয় কর।","a":"দূরত্ব = 10/tan30° = 10√3\nছাদের উপরের অংশ = 10√3 × tan60° = 30 ⇒ উচ্চতা = 40 মিটার","lv":"কঠিন"},{"n":"b19","q":"একটি খুঁটির শীর্ষের উন্নতি কোণ একটি বিন্দু থেকে 30°। খুঁটির দিকে 10 মিটার এগিয়ে গেলে উন্নতি কোণ 60° হয়। খুঁটির উচ্চতা নির্ণয় কর।","a":"h = x√3 = (x + 10)/√3 ⇒ x = 5\nh = 5√3 ≈ 8.66 মিটার","lv":"কঠিন"},{"n":"b20","q":"60 মিটার উঁচুতে উড়ন্ত একটি ঘুড়ির সুতা ভূমির সাথে 60° কোণ উৎপন্ন করে। সুতার দৈর্ঘ্য নির্ণয় কর।","a":"সুতা = 60/sin60° = 120/√3 = 40√3 ≈ 69.28 মিটার","lv":"মধ্যম"},{"n":"b21","q":"একটি ঢালু পথের দৈর্ঘ্য 8 মিটার এবং ভূমির সাথে 30° কোণ উৎপন্ন করে। পথটি কত উচ্চতায় ওঠে?","a":"উচ্চতা = 8 sin30° = 4 মিটার","lv":"মধ্যম"},{"n":"b22","q":"3000 মিটার উচ্চতায় উড়ন্ত একটি বিমানের উন্নতি কোণ 15 সেকেন্ডে 60° থেকে 30° হয়। বিমানের গতিবেগ নির্ণয় কর।","a":"অতিক্রান্ত দূরত্ব = 3000√3 − 3000/√3 = 2000√3 ≈ 3464 মিটার\nবেগ ≈ 3464/15 ≈ 230.9 মিটার/সেকেন্ড","lv":"কঠিন"},{"n":"b23","q":"75 মিটার উঁচু একটি পাহাড়ের চূড়া থেকে সমুদ্রে একটি নৌকার অবনতি কোণ 45°। নৌকাটি পাহাড়ের পাদদেশ থেকে কত দূরে?","a":"দূরত্ব = 75/tan45° = 75 মিটার","lv":"মধ্যম"},{"n":"b24","q":"1.6 মিটার লম্বা একজন শিক্ষার্থী একটি পতাকাদণ্ড থেকে 10 মিটার দূরে দাঁড়িয়ে দণ্ডের শীর্ষ 45° উন্নতি কোণে দেখে। দণ্ডের উচ্চতা কত?","a":"উচ্চতা = 1.6 + 10 tan45° = 11.6 মিটার","lv":"কঠিন"},{"n":"b25","q":"সূর্যের উন্নতি কোণ 60° হলে 15 মিটার উঁচু একটি টাওয়ারের ছায়ার দৈর্ঘ্য নির্ণয় কর।","a":"ছায়া = 15/tan60° = 5√3 ≈ 8.66 মিটার","lv":"মধ্যম"},{"n":"b26","q":"20 মিটার উঁচু একটি খুঁটির ছায়ার দৈর্ঘ্য 20√3 মিটার। সূর্যের উন্নতি কোণ নির্ণয় কর।","a":"tanθ = 20/(20√3) = 1/√3 ⇒ θ = 30°","lv":"মধ্যম"},{"n":"b27","q":"20 মিটার ও 50 মিটার উঁচু দুইটি দালানের অনুভূমিক দূরত্ব 30 মিটার। ছোট দালানের ছাদ থেকে বড় দালানের ছাদের উন্নতি কোণ নির্ণয় কর।","a":"উচ্চতার পার্থক্য = 30 মিটার ⇒ tanθ = 30/30 = 1 ⇒ θ = 45°","lv":"কঠিন"},{"n":"b28","q":"100 মিটার উঁচু একটি বাতিঘর থেকে একই পাশে একই সরলরেখায় অবস্থিত দুইটি জাহাজের অবনতি কোণ 45° ও 30°। জাহাজ দুইটির দূরত্ব নির্ণয় কর।","a":"দূরত্ব = 100√3 − 100 ≈ 73.2 মিটার","lv":"কঠিন"},{"n":"b29","q":"20 মিটার উঁচু টাওয়ার থেকে একটি গাড়ির অবনতি কোণ 30° থেকে 60° হলো। গাড়িটি কত দূরত্ব অতিক্রম করল?","a":"দূরত্ব = 20√3 − 20/√3 = 40/√3 ≈ 23.09 মিটার","lv":"কঠিন"},{"n":"b30","q":"উন্নতি কোণ ও অবনতি কোণ বলতে কী বোঝায়? উদাহরণ দাও।","a":"অনুভূমিক রেখা থেকে উপরের বস্তুর দিকে দৃষ্টিরেখার কোণ উন্নতি কোণ; নিচের বস্তুর দিকে কোণ অবনতি কোণ।\nযেমন: মাটি থেকে গাছের শীর্ষ দেখা উন্নতি কোণ, ছাদ থেকে মাটির গাড়ি দেখা অবনতি কোণ।","lv":"মধ্যম"}],"11":[{"n":"b1","q":"a : b = 3 : 4 এবং b : c = 6 : 7 হলে a : b : c নির্ণয় কর।","a":"b এর মান সমান করে: a : b = 9 : 12, b : c = 12 : 14\n∴ a : b : c = 9 : 12 : 14","lv":"মধ্যম","ex":"11.1"},{"n":"b2","q":"4 ও 9 এর মধ্যসমানুপাতী নির্ণয় কর।","a":"মধ্যসমানুপাতী = √(4 × 9) = 6","lv":"মধ্যম","ex":"11.1"},{"n":"b3","q":"3, 5 ও 12 এর চতুর্থ সমানুপাতী নির্ণয় কর।","a":"3 : 5 = 12 : x ⇒ x = 60/3 = 20","lv":"মধ্যম","ex":"11.1"},{"n":"b4","q":"4 ও 6 এর তৃতীয় সমানুপাতী নির্ণয় কর।","a":"4 : 6 = 6 : x ⇒ x = 36/4 = 9","lv":"মধ্যম","ex":"11.1"},{"n":"b5","q":"a/b = c/d হলে প্রমাণ কর যে, (a + b)/(a − b) = (c + d)/(c − d)","a":"যোজন: (a + b)/b = (c + d)/d; বিয়োজন: (a − b)/b = (c − d)/d\nভাগ করে (a + b)/(a − b) = (c + d)/(c − d)","lv":"কঠিন","ex":"11.1"},{"n":"b6","q":"x : y = 2 : 3 হলে (2x + 3y)/(3x + 2y) এর মান নির্ণয় কর।","a":"x = 2k, y = 3k ⇒ (4k + 9k)/(6k + 6k) = 13/12","lv":"মধ্যম","ex":"11.1"},{"n":"b7","q":"a : b = 5 : 3 হলে (a² − b²) : (a² + b²) নির্ণয় কর।","a":"= (25 − 9) : (25 + 9) = 16 : 34 = 8 : 17","lv":"মধ্যম","ex":"11.1"},{"n":"b8","q":"a, b, c ক্রমিক সমানুপাতী হলে প্রমাণ কর যে, (a² + b²)/(b² + c²) = a/c","a":"a/b = b/c = k ⇒ b = ck, a = ck²\nবামপক্ষ = (c²k⁴ + c²k²)/(c²k² + c²) = k² = a/c","lv":"কঠিন","ex":"11.1"},{"n":"b9","q":"(a + b)/(a − b) = 7/3 হলে a : b নির্ণয় কর।","a":"যোজন-বিয়োজন করে a/b = (7 + 3)/(7 − 3) = 10/4 = 5/2\n∴ a : b = 5 : 2","lv":"কঠিন","ex":"11.1"},{"n":"b10","q":"যোজন-বিয়োজন প্রয়োগে সমাধান কর: (x + 3)/(x − 3) = 5/3","a":"x/3 = (5 + 3)/(5 − 3) = 4 ⇒ x = 12","lv":"কঠিন","ex":"11.1"},{"n":"b11","q":"1200 টাকা 2 : 3 : 5 অনুপাতে ভাগ কর।","a":"মোট অংশ 10 ⇒ 240, 360 ও 600 টাকা","lv":"মধ্যম","ex":"11.1"},{"n":"b12","q":"দুইজনের বয়সের অনুপাত 5 : 7। 6 বছর পর অনুপাত হবে 3 : 4। তাদের বর্তমান বয়স নির্ণয় কর।","a":"(5k + 6)/(7k + 6) = 3/4 ⇒ 20k + 24 = 21k + 18 ⇒ k = 6\nবয়স 30 ও 42 বছর","lv":"কঠিন","ex":"11.1"},{"n":"b13","q":"15, 19, 35 ও 47 এর প্রত্যেকটি থেকে কোন সংখ্যা বিয়োগ করলে বিয়োগফলগুলো সমানুপাতী হবে?","a":"(15 − x)(47 − x) = (19 − x)(35 − x) ⇒ 705 − 62x = 665 − 54x ⇒ x = 5","lv":"কঠিন","ex":"11.1"},{"n":"b14","q":"x : y = 3 : 4 হলে (x² + y²)/(xy) এর মান নির্ণয় কর।","a":"= (9 + 16)/12 = 25/12","lv":"মধ্যম","ex":"11.1"},{"n":"b15","q":"a, b, c ক্রমিক সমানুপাতী এবং a = 4, c = 25 হলে b নির্ণয় কর।","a":"b² = ac = 100 ⇒ b = 10","lv":"মধ্যম","ex":"11.1"},{"n":"b16","q":"2 : 3 অনুপাতের ব্যস্ত অনুপাত, দ্বিগুণ অনুপাত ও ত্রিগুণ অনুপাত লেখ।","a":"ব্যস্ত অনুপাত 3 : 2, দ্বিগুণ (বর্গ) অনুপাত 4 : 9, ত্রিগুণ (ঘন) অনুপাত 8 : 27","lv":"মধ্যম","ex":"11.1"},{"n":"b17","q":"a : b = 2 : 3, b : c = 4 : 5 এবং c : d = 6 : 7 হলে a : d নির্ণয় কর।","a":"a/d = (a/b)(b/c)(c/d) = (2/3)(4/5)(6/7) = 48/105 = 16/35","lv":"কঠিন","ex":"11.1"},{"n":"b18","q":"200 কে 5 : 4 অনুপাতে বৃদ্ধি করলে কত হবে?","a":"= 200 × 5/4 = 250","lv":"মধ্যম","ex":"11.1"},{"n":"b19","q":"চালের দাম 4 : 5 অনুপাতে বাড়ায় নতুন দাম প্রতি কেজি 50 টাকা হলো। পূর্বের দাম কত ছিল?","a":"পূর্বের দাম = 50 × 4/5 = 40 টাকা","lv":"মধ্যম","ex":"11.1"},{"n":"b20","q":"দুইটি সংখ্যার অনুপাত 3 : 5 এবং যোগফল 64। সংখ্যা দুইটি নির্ণয় কর।","a":"8k = 64 ⇒ k = 8 ⇒ 24 ও 40","lv":"মধ্যম","ex":"11.1"},{"n":"b21","q":"দুইটি সংখ্যার অনুপাত 2 : 3। প্রত্যেকটির সাথে 5 যোগ করলে অনুপাত 3 : 4 হয়। সংখ্যা দুইটি নির্ণয় কর।","a":"(2k + 5)/(3k + 5) = 3/4 ⇒ 8k + 20 = 9k + 15 ⇒ k = 5\nসংখ্যা দুইটি 10 ও 15","lv":"কঠিন","ex":"11.1"},{"n":"b22","q":"x = {√(a + 1) + √(a − 1)}/{√(a + 1) − √(a − 1)} হলে প্রমাণ কর যে, x² − 2ax + 1 = 0","a":"যোজন-বিয়োজন: (x + 1)/(x − 1) = √(a + 1)/√(a − 1)\nবর্গ করে আবার যোজন-বিয়োজন: (x² + 1)/(2x) = a ⇒ x² − 2ax + 1 = 0","lv":"কঠিন","ex":"11.1"},{"n":"b23","q":"a/b = c/d হলে প্রমাণ কর যে, (a² + c²)/(b² + d²) = ac/bd","a":"a = bk, c = dk ⇒ বামপক্ষ = k²(b² + d²)/(b² + d²) = k²\nডানপক্ষ = bk · dk/(bd) = k² ∴ সমান।","lv":"কঠিন","ex":"11.1"},{"n":"b24","q":"একটি মানচিত্রের স্কেল 1 : 50000। মানচিত্রে 4 সেমি দূরত্ব প্রকৃতপক্ষে কত কিলোমিটার?","a":"প্রকৃত দূরত্ব = 4 × 50000 = 200000 সেমি = 2 কিমি","lv":"মধ্যম","ex":"11.1"},{"n":"b25","q":"সমাধান কর: {x + √(x² − 1)}/{x − √(x² − 1)} = 9","a":"যোজন-বিয়োজন: x/√(x² − 1) = 10/8 = 5/4 ⇒ 16x² = 25x² − 25 ⇒ x² = 25/9\nx = 5/3 (শুদ্ধি পরীক্ষায় গ্রহণযোগ্য)","lv":"কঠিন","ex":"11.1"},{"n":"b26","q":"a : b = b : c হলে প্রমাণ কর যে, a : c = a² : b²","a":"b² = ac ⇒ a²/b² = a²/(ac) = a/c","lv":"কঠিন","ex":"11.1"},{"n":"b27","q":"দুইটি গাড়ির বেগের অনুপাত 3 : 4। একই দূরত্ব অতিক্রম করতে তাদের সময়ের অনুপাত কত?","a":"সময় বেগের ব্যস্তানুপাতিক ⇒ 4 : 3","lv":"মধ্যম","ex":"11.1"},{"n":"b28","q":"একটি শ্রেণিতে ছাত্র ও ছাত্রীর অনুপাত 4 : 5। আরও 8 জন ছাত্র ভর্তি হলে অনুপাত 1 : 1 হয়। ছাত্র ও ছাত্রী কতজন ছিল?","a":"4k + 8 = 5k ⇒ k = 8\nছাত্র 32 জন, ছাত্রী 40 জন","lv":"কঠিন","ex":"11.1"},{"n":"b29","q":"(a + b) : (b + c) : (c + a) = 6 : 7 : 8 এবং a + b + c = 21 হলে a, b ও c নির্ণয় কর।","a":"যোগ করে 2(a + b + c) = 21 অংশ = 42 ⇒ 1 অংশ = 2\na + b = 12, b + c = 14, c + a = 16 ⇒ a = 7, b = 5, c = 9","lv":"কঠিন","ex":"11.1"},{"n":"b30","q":"x/y = 3/4 হলে (5x − 2y)/(3x + y) এর মান নির্ণয় কর।","a":"x = 3k, y = 4k ⇒ (15k − 8k)/(9k + 4k) = 7/13","lv":"মধ্যম","ex":"11.1"},{"n":"b31","q":"a : b = 7 : 3 এবং b : c = 1 : 5 হলে a : b : c নির্ণয় কর।","a":"b সমান করে: a : b = 7 : 3, b : c = 3 : 15\n∴ a : b : c = 7 : 3 : 15","lv":"মধ্যম","ex":"11.2"},{"n":"b32","q":"ক 4000 টাকা ও খ 6000 টাকা দিয়ে ব্যবসা শুরু করে 2000 টাকা লাভ করল। কে কত লাভ পাবে?","a":"অনুপাত 2 : 3 ⇒ ক 800 টাকা, খ 1200 টাকা","lv":"মধ্যম","ex":"11.2"},{"n":"b33","q":"x : y : z = 6 : 4 : 1 এবং x + y + z = 66 হলে y এর মান নির্ণয় কর।","a":"11k = 66 ⇒ k = 6 ⇒ y = 24","lv":"মধ্যম","ex":"11.2"},{"n":"b34","q":"ক, খ ও গ যথাক্রমে 5000, 6000 ও 9000 টাকা 12, 10 ও 8 মাসের জন্য বিনিয়োগ করে 3200 টাকা লাভ করল। কে কত পাবে?","a":"মূলধন × সময়: 60000 : 60000 : 72000 = 5 : 5 : 6\nক 1000, খ 1000, গ 1200 টাকা","lv":"কঠিন","ex":"11.2"},{"n":"b35","q":"a : b : c = 2 : 3 : 4 এবং a + b + c = 27 হলে a, b, c নির্ণয় কর।","a":"9k = 27 ⇒ k = 3 ⇒ a = 6, b = 9, c = 12","lv":"মধ্যম","ex":"11.2"},{"n":"b36","q":"700 টাকা ক, খ ও গ এর মধ্যে এমনভাবে ভাগ কর যেন ক : খ = 2 : 3 এবং খ : গ = 4 : 5 হয়।","a":"ক : খ : গ = 8 : 12 : 15, মোট 35 অংশ\nক 160, খ 240, গ 300 টাকা","lv":"কঠিন","ex":"11.2"},{"n":"b37","q":"একটি ত্রিভুজের কোণগুলোর অনুপাত 3 : 4 : 5। কোণগুলো নির্ণয় কর।","a":"12k = 180° ⇒ k = 15° ⇒ 45°, 60°, 75°","lv":"মধ্যম","ex":"11.2"},{"n":"b38","q":"a, b, c ক্রমিক সমানুপাতী হলে প্রমাণ কর যে, (a + b + c)(a − b + c) = a² + b² + c²","a":"b² = ac\nবামপক্ষ = (a + c)² − b² = a² + 2ac + c² − b² = a² + 2b² + c² − b² = a² + b² + c²","lv":"কঠিন","ex":"11.2"},{"n":"b39","q":"তিনটি সংখ্যার অনুপাত 2 : 3 : 5 এবং এদের বর্গের সমষ্টি 152। সংখ্যাগুলো নির্ণয় কর।","a":"4k² + 9k² + 25k² = 38k² = 152 ⇒ k = 2\nসংখ্যাগুলো 4, 6, 10","lv":"কঠিন","ex":"11.2"},{"n":"b40","q":"ক ও খ এর আয়ের অনুপাত 5 : 4 এবং ব্যয়ের অনুপাত 3 : 2। প্রত্যেকে 1600 টাকা সঞ্চয় করলে তাদের আয় নির্ণয় কর।","a":"5x − 3y = 1600, 4x − 2y = 1600 ⇒ y = 2x − 800\n5x − 6x + 2400 = 1600 ⇒ x = 800\nআয় 4000 ও 3200 টাকা","lv":"কঠিন","ex":"11.2"},{"n":"b41","q":"40 লিটার মিশ্রণে দুধ ও পানির অনুপাত 5 : 3। এতে 10 লিটার পানি মেশালে নতুন অনুপাত কত হবে?","a":"দুধ 25 লি, পানি 15 + 10 = 25 লি ⇒ অনুপাত 1 : 1","lv":"মধ্যম","ex":"11.2"},{"n":"b42","q":"a : b : c = 3 : 4 : 5 হলে (a + b + c)/b এর মান নির্ণয় কর।","a":"= (3 + 4 + 5)/4 = 3","lv":"মধ্যম","ex":"11.2"},{"n":"b43","q":"a : b = 3 : 2 এবং b : c = 3 : 2 হলে a : c নির্ণয় কর।","a":"a/c = (3/2)(3/2) = 9/4 ⇒ a : c = 9 : 4","lv":"মধ্যম","ex":"11.2"},{"n":"b44","q":"ক 3000 টাকা নিয়ে ব্যবসা শুরু করার 4 মাস পর খ 4500 টাকা নিয়ে যোগ দেয়। বছর শেষে 3500 টাকা লাভ হলে কে কত পাবে?","a":"ক: 3000 × 12 = 36000, খ: 4500 × 8 = 36000 ⇒ 1 : 1\nপ্রত্যেকে 1750 টাকা","lv":"কঠিন","ex":"11.2"},{"n":"b45","q":"x/2 = y/3 = z/4 হলে (x + y + z)/x এর মান নির্ণয় কর।","a":"x = 2k, y = 3k, z = 4k ⇒ 9k/2k = 9/2","lv":"মধ্যম","ex":"11.2"},{"n":"b46","q":"x/2 = y/3 = z/4 হলে দেখাও যে, (x² + y² + z²)/(xy + yz + zx) = 29/26","a":"x = 2k, y = 3k, z = 4k\n= (4 + 9 + 16)k²/(6 + 12 + 8)k² = 29/26","lv":"কঠিন","ex":"11.2"},{"n":"b47","q":"2 : 3, 4 : 5 এবং 5 : 6 এর যৌগিক অনুপাত নির্ণয় কর।","a":"= (2 × 4 × 5) : (3 × 5 × 6) = 40 : 90 = 4 : 9","lv":"মধ্যম","ex":"11.2"},{"n":"b48","q":"দুইটি বর্গের বাহুর অনুপাত 3 : 5 হলে ক্ষেত্রফলের অনুপাত কত?","a":"= 3² : 5² = 9 : 25","lv":"মধ্যম","ex":"11.2"},{"n":"b49","q":"দুইটি বৃত্তের ব্যাসার্ধের অনুপাত 2 : 3 হলে ক্ষেত্রফল ও পরিধির অনুপাত নির্ণয় কর।","a":"ক্ষেত্রফল 4 : 9, পরিধি 2 : 3","lv":"মধ্যম","ex":"11.2"},{"n":"b50","q":"1800 টাকা ক, খ ও গ এর মধ্যে 2 : 3 : 4 অনুপাতে ভাগ কর।","a":"9 অংশ = 1800 ⇒ 1 অংশ = 200\nক 400, খ 600, গ 800 টাকা","lv":"মধ্যম","ex":"11.2"},{"n":"b51","q":"একটি থলিতে 1 টাকা, 2 টাকা ও 5 টাকার মুদ্রার সংখ্যার অনুপাত 3 : 2 : 1 এবং মোট 120 টাকা আছে। প্রত্যেক প্রকার মুদ্রা কয়টি?","a":"মূল্যের অনুপাত 3 : 4 : 5 ⇒ 12k = 120 ⇒ k = 10\n1 টাকার 30টি, 2 টাকার 20টি, 5 টাকার 10টি","lv":"কঠিন","ex":"11.2"},{"n":"b52","q":"দুইটি সংখ্যার অনুপাত 5 : 7 এবং অন্তর 18। সংখ্যা দুইটি নির্ণয় কর।","a":"2k = 18 ⇒ k = 9 ⇒ 45 ও 63","lv":"মধ্যম","ex":"11.2"},{"n":"b53","q":"দুইজনের আয়ের অনুপাত 9 : 7 এবং ব্যয়ের অনুপাত 4 : 3। প্রত্যেকে 2000 টাকা সঞ্চয় করলে তাদের আয় নির্ণয় কর।","a":"9x − 4y = 2000, 7x − 3y = 2000 ⇒ x = 2000\nআয় 18000 ও 14000 টাকা","lv":"কঠিন","ex":"11.2"},{"n":"b54","q":"a/b = c/d = e/f হলে প্রমাণ কর যে, (a + c + e)/(b + d + f) = a/b","a":"a = bk, c = dk, e = fk ⇒ (a + c + e)/(b + d + f) = k(b + d + f)/(b + d + f) = k = a/b","lv":"কঠিন","ex":"11.2"},{"n":"b55","q":"a = 2b এবং b = 3c হলে a : b : c নির্ণয় কর।","a":"c = 1 ধরলে b = 3, a = 6 ⇒ a : b : c = 6 : 3 : 1","lv":"মধ্যম","ex":"11.2"},{"n":"b56","q":"x : y = 4 : 5 এবং y : z = 6 : 7 হলে x : y : z নির্ণয় কর।","a":"y সমান করে: x : y = 24 : 30, y : z = 30 : 35\n∴ 24 : 30 : 35","lv":"মধ্যম","ex":"11.2"},{"n":"b57","q":"তিনজন অংশীদারের মূলধনের অনুপাত 2 : 3 : 4 এবং বিনিয়োগের সময়ের অনুপাত 4 : 3 : 2। মোট লাভ 2500 টাকা হলে কে কত পাবে?","a":"লাভের অনুপাত 8 : 9 : 8, মোট 25 অংশ\n800, 900 ও 800 টাকা","lv":"কঠিন","ex":"11.2"},{"n":"b58","q":"বাসভাড়া 10 : 13 অনুপাতে বৃদ্ধি পেয়ে 26 টাকা হলো। পূর্বের ভাড়া কত ছিল?","a":"পূর্বের ভাড়া = 26 × 10/13 = 20 টাকা","lv":"মধ্যম","ex":"11.2"},{"n":"b59","q":"a, b, c, d ক্রমিক সমানুপাতী হলে প্রমাণ কর যে, a : d = a³ : b³","a":"a/b = b/c = c/d = k ⇒ a/d = (a/b)(b/c)(c/d) = k³ = (a/b)³","lv":"কঠিন","ex":"11.2"},{"n":"b60","q":"দুইটি গ্রামের জনসংখ্যার অনুপাত 5 : 3। প্রথম গ্রাম থেকে 200 জন দ্বিতীয় গ্রামে গেলে জনসংখ্যা সমান হয়। জনসংখ্যা নির্ণয় কর।","a":"5k − 200 = 3k + 200 ⇒ k = 200\nজনসংখ্যা 1000 ও 600","lv":"কঠিন","ex":"11.2"}],"2":[{"n":"b1","ex":"2.1","q":"A = {x : x ∈ ℕ এবং x² < 30} সেটটিকে তালিকা পদ্ধতিতে প্রকাশ কর।","a":"x = 1, 2, 3, 4, 5 এর জন্য x² < 30 (6² = 36 > 30)।\nA = {1, 2, 3, 4, 5}","lv":"সহজ"},{"n":"b2","ex":"2.1","q":"B = {3, 6, 9, 12, 15} সেটটিকে সেট গঠন পদ্ধতিতে প্রকাশ কর।","a":"উপাদানগুলো 3 এর প্রথম পাঁচটি গুণিতক।\nB = {x : x = 3n, n ∈ ℕ এবং n ≤ 5}","lv":"সহজ"},{"n":"b3","ex":"2.1","q":"C = {x : x ∈ ℤ এবং −2 < x ≤ 3} সেটটিকে তালিকা পদ্ধতিতে প্রকাশ কর।","a":"−2 এর চেয়ে বড় এবং 3 এর সমান বা ছোট পূর্ণসংখ্যা।\nC = {−1, 0, 1, 2, 3}","lv":"সহজ"},{"n":"b4","ex":"2.1","q":"D = {x : x, 12 এর গুণনীয়ক} সেটটিকে তালিকা পদ্ধতিতে প্রকাশ কর।","a":"12 = 1 × 12 = 2 × 6 = 3 × 4\nD = {1, 2, 3, 4, 6, 12}","lv":"সহজ"},{"n":"b5","ex":"2.1","q":"A = {a, b, c} হলে P(A) নির্ণয় কর।","a":"P(A) = {∅, {a}, {b}, {c}, {a, b}, {a, c}, {b, c}, {a, b, c}}\nউপাদান সংখ্যা 2³ = 8","lv":"মধ্যম"},{"n":"b6","ex":"2.1","q":"কোনো সেটের উপাদান সংখ্যা 5 হলে তার উপসেট ও প্রকৃত উপসেটের সংখ্যা নির্ণয় কর।","a":"উপসেট সংখ্যা = 2⁵ = 32\nপ্রকৃত উপসেট সংখ্যা = 32 − 1 = 31","lv":"মধ্যম"},{"n":"b7","ex":"2.1","q":"কোনো সেট A এর শক্তি সেট P(A) এর উপাদান সংখ্যা 64 হলে n(A) কত?","a":"2ⁿ = 64 = 2⁶\n∴ n(A) = 6","lv":"মধ্যম"},{"n":"b8","ex":"2.1","q":"A = {2, 4, 6, 8} এবং B = {4, 8, 12} হলে A ∪ B ও A ∩ B নির্ণয় কর।","a":"A ∪ B = {2, 4, 6, 8, 12}\nA ∩ B = {4, 8}","lv":"মধ্যম"},{"n":"b9","ex":"2.1","q":"A = {1, 2, 3, 4, 5} এবং B = {2, 4, 6} হলে A ∖ B ও B ∖ A নির্ণয় কর।","a":"A ∖ B = {1, 3, 5}\nB ∖ A = {6}","lv":"মধ্যম"},{"n":"b10","ex":"2.1","q":"U = {1, 2, 3, 4, 5, 6, 7, 8} এবং A = {2, 3, 5, 7} হলে A′ নির্ণয় কর।","a":"A′ = U ∖ A = {1, 4, 6, 8}","lv":"সহজ"},{"n":"b11","ex":"2.1","q":"U = {1, 2, 3, 4, 5, 6}, A = {1, 2, 3} এবং B = {2, 4, 6} হলে দেখাও যে, (A ∪ B)′ = A′ ∩ B′","a":"A ∪ B = {1, 2, 3, 4, 6}, ∴ (A ∪ B)′ = {5}\nA′ = {4, 5, 6}, B′ = {1, 3, 5}, ∴ A′ ∩ B′ = {5}\n∴ (A ∪ B)′ = A′ ∩ B′","lv":"মধ্যম"},{"n":"b12","ex":"2.1","q":"A = {1, 2} এবং B = {a, b} হলে A × B নির্ণয় কর।","a":"A × B = {(1, a), (1, b), (2, a), (2, b)}","lv":"সহজ"},{"n":"b13","ex":"2.1","q":"(x + 2, 5) = (7, y − 1) হলে x ও y এর মান নির্ণয় কর।","a":"ক্রমজোড় সমান হলে প্রথম ও দ্বিতীয় পদ আলাদাভাবে সমান।\nx + 2 = 7 ⇒ x = 5\ny − 1 = 5 ⇒ y = 6","lv":"মধ্যম"},{"n":"b14","ex":"2.1","q":"(2x − y, x + y) = (4, 5) হলে x ও y এর মান নির্ণয় কর।","a":"2x − y = 4 এবং x + y = 5\nযোগ করে 3x = 9 ⇒ x = 3\n∴ y = 5 − 3 = 2","lv":"মধ্যম"},{"n":"b15","ex":"2.1","q":"A = {x ∈ ℕ : 2 < x < 7} এবং B = {x ∈ ℕ : x জোড় এবং x ≤ 8} হলে A ∩ B নির্ণয় কর।","a":"A = {3, 4, 5, 6}, B = {2, 4, 6, 8}\nA ∩ B = {4, 6}","lv":"মধ্যম"},{"n":"b16","ex":"2.1","q":"n(A) = 20, n(B) = 15 এবং n(A ∩ B) = 6 হলে n(A ∪ B) নির্ণয় কর।","a":"n(A ∪ B) = n(A) + n(B) − n(A ∩ B)\n= 20 + 15 − 6 = 29","lv":"মধ্যম"},{"n":"b17","ex":"2.1","q":"একটি শ্রেণির 40 জন শিক্ষার্থীর মধ্যে 25 জন গণিত এবং 20 জন বিজ্ঞান পছন্দ করে। প্রত্যেকে অন্তত একটি বিষয় পছন্দ করলে কতজন উভয় বিষয় পছন্দ করে?","a":"n(G ∪ S) = n(G) + n(S) − n(G ∩ S)\n40 = 25 + 20 − n(G ∩ S)\n∴ n(G ∩ S) = 5 জন","lv":"মধ্যম"},{"n":"b18","ex":"2.1","q":"A = {x ∈ ℝ : x² + 1 = 0} কোন ধরনের সেট? কারণসহ লেখ।","a":"যেকোনো বাস্তব সংখ্যা x এর জন্য x² ≥ 0, তাই x² + 1 ≥ 1 > 0।\nসমীকরণটির কোনো বাস্তব সমাধান নেই, ∴ A = ∅ (ফাঁকা সেট)।","lv":"মধ্যম"},{"n":"b19","ex":"2.1","q":"A = {1, 2, 3}, B = {2, 3, 4} এবং C = {3, 4, 5} হলে A ∩ (B ∪ C) নির্ণয় কর।","a":"B ∪ C = {2, 3, 4, 5}\nA ∩ (B ∪ C) = {2, 3}","lv":"মধ্যম"},{"n":"b20","ex":"2.1","q":"A = {1, 2}, B = {2, 3} এবং C = {3} হলে (A × B) ∩ (A × C) নির্ণয় কর।","a":"A × B = {(1, 2), (1, 3), (2, 2), (2, 3)}\nA × C = {(1, 3), (2, 3)}\n(A × B) ∩ (A × C) = {(1, 3), (2, 3)}","lv":"মধ্যম"},{"n":"b41","q":"A = {x ∈ ℕ : x² − 5x + 6 = 0} হলে A ও P(A) নির্ণয় কর।","a":"x² − 5x + 6 = (x − 2)(x − 3) = 0 ⇒ x = 2, 3\nA = {2, 3}, P(A) = {∅, {2}, {3}, {2, 3}}","lv":"মধ্যম","ex":"2.1"},{"n":"b42","q":"A = {x ∈ ℤ : x² ≤ 4} হলে A কে তালিকা পদ্ধতিতে প্রকাশ কর এবং n(P(A)) নির্ণয় কর।","a":"A = {−2, −1, 0, 1, 2}, n(A) = 5\nn(P(A)) = 2⁵ = 32","lv":"মধ্যম","ex":"2.1"},{"n":"b43","q":"B = {x ∈ ℕ : x, 36 এর বিজোড় গুণনীয়ক} কে তালিকা পদ্ধতিতে প্রকাশ কর।","a":"36 এর গুণনীয়ক: 1, 2, 3, 4, 6, 9, 12, 18, 36\nবিজোড়গুলো: B = {1, 3, 9}","lv":"মধ্যম","ex":"2.1"},{"n":"b44","q":"C = {x : x মৌলিক সংখ্যা এবং x² < 50} কে তালিকা পদ্ধতিতে প্রকাশ কর।","a":"7² = 49 < 50 কিন্তু 11² > 50\nC = {2, 3, 5, 7}","lv":"মধ্যম","ex":"2.1"},{"n":"b45","q":"U = {1, 2, …, 10}, A = {x ∈ U : x জোড়} এবং B = {x ∈ U : x, 3 এর গুণিতক} হলে (A ∪ B)′ নির্ণয় কর।","a":"A = {2, 4, 6, 8, 10}, B = {3, 6, 9}\nA ∪ B = {2, 3, 4, 6, 8, 9, 10}\n(A ∪ B)′ = {1, 5, 7}","lv":"কঠিন","ex":"2.1"},{"n":"b46","q":"U = {1, 2, …, 10}, A = {x ∈ U : x জোড়} এবং B = {x ∈ U : x, 3 এর গুণিতক} হলে A′ ∩ B নির্ণয় কর।","a":"A′ = {1, 3, 5, 7, 9}, B = {3, 6, 9}\nA′ ∩ B = {3, 9}","lv":"মধ্যম","ex":"2.1"},{"n":"b47","q":"A = {1, 2, 3}, B = {3, 4} এবং C = {4, 5} হলে A × (B ∩ C) নির্ণয় কর।","a":"B ∩ C = {4}\nA × (B ∩ C) = {(1, 4), (2, 4), (3, 4)}","lv":"মধ্যম","ex":"2.1"},{"n":"b48","q":"A = {a, b} এবং B = {1, 2, 3} হলে n(A × B) ও n(P(A × B)) নির্ণয় কর।","a":"n(A × B) = 2 × 3 = 6\nn(P(A × B)) = 2⁶ = 64","lv":"কঠিন","ex":"2.1"},{"n":"b49","q":"(x/2 + y/3, x − y) = (5, 0) হলে x ও y এর মান নির্ণয় কর।","a":"x − y = 0 ⇒ x = y\nx/2 + x/3 = 5 ⇒ 5x/6 = 5 ⇒ x = 6, ∴ y = 6","lv":"কঠিন","ex":"2.1"},{"n":"b50","q":"(x + y, 2) = (5, x − y) হলে x ও y এর মান নির্ণয় কর।","a":"x + y = 5, x − y = 2\nযোগ করে 2x = 7 ⇒ x = 7/2, y = 3/2","lv":"মধ্যম","ex":"2.1"},{"n":"b51","q":"n(U) = 50, n(A) = 28, n(B) = 22 এবং n(A ∩ B) = 10 হলে n((A ∪ B)′) নির্ণয় কর।","a":"n(A ∪ B) = 28 + 22 − 10 = 40\nn((A ∪ B)′) = 50 − 40 = 10","lv":"মধ্যম","ex":"2.1"},{"n":"b52","q":"100 জন লোকের মধ্যে 65 জন চা, 45 জন কফি পছন্দ করে এবং 10 জন কোনোটিই পছন্দ করে না। কতজন উভয়টি পছন্দ করে?","a":"অন্তত একটি পছন্দ করে = 100 − 10 = 90\nউভয় = 65 + 45 − 90 = 20 জন","lv":"কঠিন","ex":"2.1"},{"n":"b53","q":"60 জন শিক্ষার্থীর মধ্যে 35 জন ফুটবল, 30 জন ক্রিকেট এবং 12 জন উভয় খেলা খেলে। কতজন কোনো খেলাই খেলে না এবং কতজন শুধু ফুটবল খেলে?","a":"অন্তত একটি = 35 + 30 − 12 = 53\nকোনোটিই না = 60 − 53 = 7 জন\nশুধু ফুটবল = 35 − 12 = 23 জন","lv":"কঠিন","ex":"2.1"},{"n":"b54","q":"A = {x ∈ ℕ : x ≤ 12 এবং x, 2 এর গুণিতক} এবং B = {x ∈ ℕ : x ≤ 12 এবং x, 3 এর গুণিতক} হলে A ∖ B নির্ণয় কর।","a":"A = {2, 4, 6, 8, 10, 12}, B = {3, 6, 9, 12}\nA ∖ B = {2, 4, 8, 10}","lv":"মধ্যম","ex":"2.1"},{"n":"b55","q":"A = {x ∈ ℝ : x² − 1 = 0} এবং B = {x ∈ ℝ : x² + x − 2 = 0} হলে A ∪ B ও A ∩ B নির্ণয় কর।","a":"A = {−1, 1}; x² + x − 2 = (x + 2)(x − 1) ⇒ B = {−2, 1}\nA ∪ B = {−2, −1, 1}, A ∩ B = {1}","lv":"কঠিন","ex":"2.1"},{"n":"b56","q":"A = {1, 2}, B = {2, 3} এবং C = {3, 4} হলে দেখাও যে, A ∪ (B ∩ C) = (A ∪ B) ∩ (A ∪ C)","a":"B ∩ C = {3} ⇒ A ∪ (B ∩ C) = {1, 2, 3}\nA ∪ B = {1, 2, 3}, A ∪ C = {1, 2, 3, 4}\n(A ∪ B) ∩ (A ∪ C) = {1, 2, 3} ∴ উভয় পক্ষ সমান।","lv":"কঠিন","ex":"2.1"},{"n":"b57","q":"U = {1, 2, 3, 4, 5, 6}, A = {1, 2, 4} এবং B = {2, 4, 5} হলে দেখাও যে, (A ∩ B)′ = A′ ∪ B′","a":"A ∩ B = {2, 4} ⇒ (A ∩ B)′ = {1, 3, 5, 6}\nA′ = {3, 5, 6}, B′ = {1, 3, 6} ⇒ A′ ∪ B′ = {1, 3, 5, 6}\n∴ (A ∩ B)′ = A′ ∪ B′","lv":"কঠিন","ex":"2.1"},{"n":"b58","q":"A = {2, 4} এবং B = {1, 2, 3, 4} হলে A ∪ B ও A ∩ B নির্ণয় কর। ফলাফল থেকে কী সিদ্ধান্তে আসা যায়?","a":"A ∪ B = {1, 2, 3, 4} = B, A ∩ B = {2, 4} = A\nসিদ্ধান্ত: A ⊂ B হলে A ∪ B = B এবং A ∩ B = A","lv":"মধ্যম","ex":"2.1"},{"n":"b59","q":"n(A) = 3 হলে n(P(P(A))) নির্ণয় কর।","a":"n(P(A)) = 2³ = 8\nn(P(P(A))) = 2⁸ = 256","lv":"কঠিন","ex":"2.1"},{"n":"b60","q":"A = {x ∈ ℕ : 4 < 2x − 1 < 13} কে তালিকা পদ্ধতিতে প্রকাশ কর।","a":"4 < 2x − 1 < 13 ⇒ 5 < 2x < 14 ⇒ 2.5 < x < 7\nA = {3, 4, 5, 6}","lv":"কঠিন","ex":"2.1"},{"n":"b61","q":"{1, 4, 9, 16, 25} সেটটিকে সেট গঠন পদ্ধতিতে প্রকাশ কর।","a":"উপাদানগুলো প্রথম পাঁচটি স্বাভাবিক সংখ্যার বর্গ।\n{x : x = n², n ∈ ℕ এবং n ≤ 5}","lv":"মধ্যম","ex":"2.1"},{"n":"b62","q":"{−3, −2, −1, 0, 1, 2, 3} সেটটিকে সেট গঠন পদ্ধতিতে প্রকাশ কর।","a":"{x ∈ ℤ : x² ≤ 9}\n(অথবা {x ∈ ℤ : −3 ≤ x ≤ 3})","lv":"মধ্যম","ex":"2.1"},{"n":"b63","q":"A = {1}, B = {2} এবং C = {3} হলে দেখাও যে, A × (B ∪ C) = (A × B) ∪ (A × C)","a":"B ∪ C = {2, 3} ⇒ A × (B ∪ C) = {(1, 2), (1, 3)}\nA × B = {(1, 2)}, A × C = {(1, 3)} ⇒ সংযোগ = {(1, 2), (1, 3)}\n∴ উভয় পক্ষ সমান।","lv":"মধ্যম","ex":"2.1"},{"n":"b64","q":"A = {2, 3} এবং B = {3, 4} হলে (A × B) ∩ (B × A) নির্ণয় কর।","a":"A × B = {(2, 3), (2, 4), (3, 3), (3, 4)}\nB × A = {(3, 2), (3, 3), (4, 2), (4, 3)}\nছেদ = {(3, 3)}","lv":"কঠিন","ex":"2.1"},{"n":"b65","q":"A = {x ∈ ℕ : x < 6} সেটের প্রকৃত উপসেটের সংখ্যা নির্ণয় কর।","a":"A = {1, 2, 3, 4, 5}, n(A) = 5\nপ্রকৃত উপসেট = 2⁵ − 1 = 31টি","lv":"মধ্যম","ex":"2.1"},{"n":"b66","q":"A সেটের উপাদান সংখ্যা B সেটের চেয়ে 2 বেশি এবং P(A) এর উপাদান সংখ্যা P(B) এর চেয়ে 48 বেশি। n(A) ও n(B) নির্ণয় কর।","a":"n(B) = n ধরি। 2ⁿ⁺² − 2ⁿ = 48 ⇒ 3 · 2ⁿ = 48 ⇒ 2ⁿ = 16 ⇒ n = 4\n∴ n(B) = 4, n(A) = 6","lv":"কঠিন","ex":"2.1"},{"n":"b67","q":"A = {x : x, 6 এর গুণিতক এবং x ≤ 30} এবং B = {x : x, 4 এর গুণিতক এবং x ≤ 30} হলে A ∩ B নির্ণয় কর।","a":"A = {6, 12, 18, 24, 30}, B = {4, 8, 12, 16, 20, 24, 28}\nA ∩ B = {12, 24}","lv":"মধ্যম","ex":"2.1"},{"n":"b68","q":"সার্বিক সেট U = ℕ এবং A = সকল জোড় স্বাভাবিক সংখ্যার সেট হলে A′ নির্ণয় কর। A′ সসীম না অসীম?","a":"A′ = {1, 3, 5, 7, …} = সকল বিজোড় স্বাভাবিক সংখ্যার সেট\nএটি অসীম সেট।","lv":"মধ্যম","ex":"2.1"},{"n":"b69","q":"A = {a, b, c, d} এর কয়টি উপসেটে a উপাদানটি আছে? যুক্তি দাও।","a":"a কে বাদ দিলে বাকি {b, c, d} এর প্রতিটি উপসেটের সাথে a যোগ করলেই a-যুক্ত উপসেট পাওয়া যায়।\nসংখ্যা = 2³ = 8টি","lv":"কঠিন","ex":"2.1"},{"n":"b70","q":"n(A ∪ B) = 50, n(A) = 30 এবং n(B) = 35 হলে n(A ∩ B) ও n(A ∖ B) নির্ণয় কর।","a":"n(A ∩ B) = 30 + 35 − 50 = 15\nn(A ∖ B) = 30 − 15 = 15","lv":"মধ্যম","ex":"2.1"},{"n":"b21","ex":"2.2","q":"f(x) = x² − 3x + 2 হলে f(3) ও f(−1) নির্ণয় কর।","a":"f(3) = 9 − 9 + 2 = 2\nf(−1) = 1 + 3 + 2 = 6","lv":"সহজ"},{"n":"b22","ex":"2.2","q":"f(x) = 3x − 5 এবং f(x) = 7 হলে x এর মান নির্ণয় কর।","a":"3x − 5 = 7 ⇒ 3x = 12 ⇒ x = 4","lv":"সহজ"},{"n":"b23","ex":"2.2","q":"f(x) = x² + 1 হলে f(2) + f(−2) এর মান নির্ণয় কর।","a":"f(2) = 5, f(−2) = 5\n∴ f(2) + f(−2) = 10","lv":"সহজ"},{"n":"b24","ex":"2.2","q":"R = {(1, 2), (2, 3), (3, 4), (4, 5)} অন্বয়ের ডোমেন ও রেঞ্জ নির্ণয় কর।","a":"ডোম R = {1, 2, 3, 4}\nরেঞ্জ R = {2, 3, 4, 5}","lv":"মধ্যম"},{"n":"b25","ex":"2.2","q":"A = {1, 2, 3} এবং R = {(x, y) : x ∈ A, y ∈ A এবং y = x + 1} হলে R কে তালিকা পদ্ধতিতে প্রকাশ কর।","a":"x = 1 ⇒ y = 2 ∈ A; x = 2 ⇒ y = 3 ∈ A; x = 3 ⇒ y = 4 ∉ A\nR = {(1, 2), (2, 3)}","lv":"মধ্যম"},{"n":"b26","ex":"2.2","q":"A = {1, 2, 3}, B = {2, 4, 6} এবং R = {(x, y) : x ∈ A, y ∈ B এবং y = 2x} হলে R নির্ণয় কর। R কি একটি ফাংশন?","a":"R = {(1, 2), (2, 4), (3, 6)}\nপ্রতিটি x এর একটিমাত্র প্রতিচ্ছবি আছে, তাই R একটি ফাংশন।","lv":"মধ্যম"},{"n":"b27","ex":"2.2","q":"S = {(1, 3), (2, 5), (1, 4)} অন্বয়টি ফাংশন কি না যুক্তিসহ লেখ।","a":"(1, 3) ও (1, 4) এ একই প্রথম উপাদান 1 এর দুটি ভিন্ন প্রতিচ্ছবি 3 ও 4।\nতাই S ফাংশন নয়।","lv":"মধ্যম"},{"n":"b28","ex":"2.2","q":"f(x) = (2x + 1)/(x − 3) ফাংশনের ডোমেন নির্ণয় কর।","a":"x − 3 = 0 হলে অর্থাৎ x = 3 হলে f(x) অসংজ্ঞায়িত।\nডোম f = ℝ ∖ {3}","lv":"মধ্যম"},{"n":"b29","ex":"2.2","q":"f(x) = √(x − 2) ফাংশনের ডোমেন নির্ণয় কর।","a":"বাস্তব মানের জন্য x − 2 ≥ 0 ⇒ x ≥ 2\nডোম f = {x ∈ ℝ : x ≥ 2}","lv":"মধ্যম"},{"n":"b30","ex":"2.2","q":"f(x) = x³ − 2x হলে দেখাও যে, f(−x) = −f(x)","a":"f(−x) = (−x)³ − 2(−x) = −x³ + 2x\n= −(x³ − 2x) = −f(x)","lv":"মধ্যম"},{"n":"b31","ex":"2.2","q":"f(x) = 2x + 3 হলে f(f(1)) এর মান নির্ণয় কর।","a":"f(1) = 2 + 3 = 5\nf(f(1)) = f(5) = 10 + 3 = 13","lv":"সহজ"},{"n":"b32","ex":"2.2","q":"f(x) = 1/(x + 1) হলে f(1/2) এর মান নির্ণয় কর।","a":"f(1/2) = 1/(1/2 + 1) = 1/(3/2) = 2/3","lv":"মধ্যম"},{"n":"b33","ex":"2.2","q":"f(x) = x² − 4 হলে f(x) = 0 সমীকরণের সমাধান কর।","a":"x² − 4 = 0 ⇒ x² = 4 ⇒ x = ±2","lv":"মধ্যম"},{"n":"b34","ex":"2.2","q":"A = {−1, 0, 1} এবং f : A → ℝ, f(x) = x² হলে f এর রেঞ্জ নির্ণয় কর।","a":"f(−1) = 1, f(0) = 0, f(1) = 1\nরেঞ্জ f = {0, 1}","lv":"সহজ"},{"n":"b35","ex":"2.2","q":"f(x) = 4x − 1 এবং g(x) = x² হলে f(2) · g(−3) এর মান নির্ণয় কর।","a":"f(2) = 8 − 1 = 7, g(−3) = 9\n∴ f(2) · g(−3) = 63","lv":"মধ্যম"},{"n":"b36","ex":"2.2","q":"f(x) = (x + 1)/(x − 1) হলে f(2) + f(3) এর মান নির্ণয় কর।","a":"f(2) = 3/1 = 3, f(3) = 4/2 = 2\n∴ f(2) + f(3) = 5","lv":"মধ্যম"},{"n":"b37","ex":"2.2","q":"A = {1, 2, 3, 4} এবং R = {(x, y) : x ∈ A, y ∈ A এবং x + y = 5} হলে R নির্ণয় কর।","a":"R = {(1, 4), (2, 3), (3, 2), (4, 1)}","lv":"মধ্যম"},{"n":"b38","ex":"2.2","q":"f(x) = ax + 3 এবং f(2) = 11 হলে a এর মান নির্ণয় কর।","a":"f(2) = 2a + 3 = 11 ⇒ 2a = 8 ⇒ a = 4","lv":"মধ্যম"},{"n":"b39","ex":"2.2","q":"f(x) = x² − 5x + 6 এবং f(a) = 0 হলে a এর মান নির্ণয় কর।","a":"a² − 5a + 6 = 0 ⇒ (a − 2)(a − 3) = 0\n∴ a = 2 অথবা a = 3","lv":"মধ্যম"},{"n":"b40","ex":"2.2","q":"A = {−2, −1, 0, 1, 2} এবং R = {(x, y) : x ∈ A, y ∈ A এবং y = x²} হলে R এর ডোমেন ও রেঞ্জ নির্ণয় কর।","a":"x = ±2 হলে y = 4 ∉ A\nR = {(−1, 1), (0, 0), (1, 1)}\nডোম R = {−1, 0, 1}, রেঞ্জ R = {0, 1}","lv":"মধ্যম"},{"n":"b71","q":"f(x) = x² + 2x − 3 হলে f(x) = 0 সমীকরণের সমাধান কর।","a":"x² + 2x − 3 = (x + 3)(x − 1) = 0\n∴ x = 1 অথবা x = −3","lv":"মধ্যম","ex":"2.2"},{"n":"b72","q":"f(x) = (x + 3)/(x − 3) হলে f(2) · f(−2) এর মান নির্ণয় কর।","a":"f(2) = 5/(−1) = −5, f(−2) = 1/(−5) = −1/5\nগুণফল = 1","lv":"কঠিন","ex":"2.2"},{"n":"b73","q":"f(x) = x² হলে দেখাও যে, f(a + b) − f(a − b) = 4ab","a":"(a + b)² − (a − b)² = 4ab","lv":"মধ্যম","ex":"2.2"},{"n":"b74","q":"f(x) = (1 + x)/(1 − x) হলে দেখাও যে, f(−x) = 1/f(x)","a":"f(−x) = (1 − x)/(1 + x)\n1/f(x) = (1 − x)/(1 + x) ∴ f(−x) = 1/f(x)","lv":"কঠিন","ex":"2.2"},{"n":"b75","q":"f(x) = x + 1/x হলে দেখাও যে, f(1/x) = f(x)","a":"f(1/x) = 1/x + 1/(1/x) = 1/x + x = f(x)","lv":"মধ্যম","ex":"2.2"},{"n":"b76","q":"f(x) = x³ − 3x² + 3x হলে f(1) ও f(2) নির্ণয় কর।","a":"f(1) = 1 − 3 + 3 = 1\nf(2) = 8 − 12 + 6 = 2","lv":"মধ্যম","ex":"2.2"},{"n":"b77","q":"f(x) = ax² + bx, f(1) = 5 এবং f(2) = 14 হলে a ও b এর মান নির্ণয় কর।","a":"a + b = 5 এবং 4a + 2b = 14 ⇒ 2a + b = 7\nবিয়োগ করে a = 2, b = 3","lv":"কঠিন","ex":"2.2"},{"n":"b78","q":"f(x) = 3x + 2 হলে f(2x) − f(x) = 9 সমীকরণটি সমাধান কর।","a":"f(2x) − f(x) = (6x + 2) − (3x + 2) = 3x = 9\n∴ x = 3","lv":"মধ্যম","ex":"2.2"},{"n":"b79","q":"f(x) = √(4 − x) ফাংশনের ডোমেন নির্ণয় কর।","a":"বাস্তব মানের জন্য 4 − x ≥ 0 ⇒ x ≤ 4\nডোম f = {x ∈ ℝ : x ≤ 4}","lv":"মধ্যম","ex":"2.2"},{"n":"b80","q":"f(x) = 1/(x² − 9) ফাংশনের ডোমেন নির্ণয় কর।","a":"x² − 9 = 0 ⇒ x = ±3 এ ফাংশন অসংজ্ঞায়িত।\nডোম f = ℝ ∖ {−3, 3}","lv":"মধ্যম","ex":"2.2"},{"n":"b81","q":"f(x) = √(x − 1)/(x − 3) ফাংশনের ডোমেন নির্ণয় কর।","a":"লবের জন্য x ≥ 1, হরের জন্য x ≠ 3\nডোম f = {x ∈ ℝ : x ≥ 1 এবং x ≠ 3}","lv":"কঠিন","ex":"2.2"},{"n":"b82","q":"A = {1, 2, 3, 4} এবং R = {(x, y) : x, y ∈ A এবং x < y} হলে R কে তালিকা পদ্ধতিতে প্রকাশ কর।","a":"R = {(1, 2), (1, 3), (1, 4), (2, 3), (2, 4), (3, 4)}","lv":"মধ্যম","ex":"2.2"},{"n":"b83","q":"A = {1, 2, 3, 4, 5} এবং R = {(x, y) : x, y ∈ A এবং y = 2x − 1} হলে R এর ডোমেন ও রেঞ্জ নির্ণয় কর।","a":"x = 1, 2, 3 হলে y = 1, 3, 5 ∈ A; x = 4, 5 হলে y ∉ A\nR = {(1, 1), (2, 3), (3, 5)}\nডোম R = {1, 2, 3}, রেঞ্জ R = {1, 3, 5}","lv":"কঠিন","ex":"2.2"},{"n":"b84","q":"A = {2, 3, 4, 6} এবং R = {(x, y) : x, y ∈ A এবং x দ্বারা y বিভাজ্য} হলে R নির্ণয় কর।","a":"R = {(2, 2), (2, 4), (2, 6), (3, 3), (3, 6), (4, 4), (6, 6)}","lv":"কঠিন","ex":"2.2"},{"n":"b85","q":"f(x) = x² − x এবং f(x) = 6 হলে x এর মান নির্ণয় কর।","a":"x² − x − 6 = 0 ⇒ (x − 3)(x + 2) = 0\n∴ x = 3 অথবা x = −2","lv":"মধ্যম","ex":"2.2"},{"n":"b86","q":"f(x) = 4x³ − 5x² + 7 হলে f(−1) নির্ণয় কর।","a":"f(−1) = 4(−1) − 5(1) + 7 = −2","lv":"মধ্যম","ex":"2.2"},{"n":"b87","q":"f(x) = (2x − 1)/(x + 2) এবং f(x) = 1 হলে x এর মান নির্ণয় কর।","a":"2x − 1 = x + 2 ⇒ x = 3","lv":"মধ্যম","ex":"2.2"},{"n":"b88","q":"f(x) = x² − 4x + 5 হলে দেখাও যে, f(2 + h) = f(2 − h)","a":"f(2 + h) = 4 + 4h + h² − 8 − 4h + 5 = h² + 1\nf(2 − h) = 4 − 4h + h² − 8 + 4h + 5 = h² + 1\n∴ f(2 + h) = f(2 − h)","lv":"কঠিন","ex":"2.2"},{"n":"b89","q":"y = 2x − 1 ফাংশনের লেখচিত্র আঁকার জন্য x = −1, 0, 1, 2 এর জন্য বিন্দুগুলো নির্ণয় কর।","a":"(−1, −3), (0, −1), (1, 1), (2, 3)\nবিন্দুগুলো যোগ করলে একটি সরলরেখা পাওয়া যায়।","lv":"মধ্যম","ex":"2.2"},{"n":"b90","q":"f(x) = kx + 2 এর লেখচিত্র (3, −1) বিন্দুগামী হলে k এর মান নির্ণয় কর।","a":"f(3) = 3k + 2 = −1 ⇒ k = −1","lv":"মধ্যম","ex":"2.2"},{"n":"b91","q":"A = {1, 2, 3} এবং B = {4, 5} হলে A থেকে B তে মোট কয়টি অন্বয় সম্ভব?","a":"n(A × B) = 6, A × B এর প্রতিটি উপসেটই একটি অন্বয়।\nমোট অন্বয় = 2⁶ = 64টি","lv":"কঠিন","ex":"2.2"},{"n":"b92","q":"f(x) = (x² − 1)/(x − 1) ফাংশনের ডোমেন এবং f(3) নির্ণয় কর।","a":"x = 1 এ হর শূন্য, ডোম f = ℝ ∖ {1}\nf(3) = 8/2 = 4","lv":"মধ্যম","ex":"2.2"},{"n":"b93","q":"f(x) = x² + 3x হলে দেখাও যে, f(a) − f(b) = (a − b)(a + b + 3)","a":"f(a) − f(b) = a² − b² + 3a − 3b = (a − b)(a + b) + 3(a − b) = (a − b)(a + b + 3)","lv":"কঠিন","ex":"2.2"},{"n":"b94","q":"f(x) = 1/(1 − x) হলে f(f(2)) এর মান নির্ণয় কর।","a":"f(2) = 1/(1 − 2) = −1\nf(−1) = 1/(1 + 1) = 1/2","lv":"কঠিন","ex":"2.2"},{"n":"b95","q":"A = {−1, 0, 1, 2} এবং f : A → ℝ, f(x) = x³ − x হলে f এর রেঞ্জ নির্ণয় কর।","a":"f(−1) = 0, f(0) = 0, f(1) = 0, f(2) = 6\nরেঞ্জ f = {0, 6}","lv":"মধ্যম","ex":"2.2"},{"n":"b96","q":"A = {0, 3, 4, 5} এবং R = {(x, y) : x, y ∈ A এবং x² + y² = 25} হলে R নির্ণয় কর।","a":"R = {(0, 5), (5, 0), (3, 4), (4, 3)}","lv":"কঠিন","ex":"2.2"},{"n":"b97","q":"f(x) = 2x + 1 হলে f(x − 1) এবং f(x) − f(x − 1) নির্ণয় কর।","a":"f(x − 1) = 2(x − 1) + 1 = 2x − 1\nf(x) − f(x − 1) = (2x + 1) − (2x − 1) = 2","lv":"মধ্যম","ex":"2.2"},{"n":"b98","q":"f(x) = x² + x + 1 হলে দেখাও যে, f(−1 − x) = f(x)","a":"f(−1 − x) = (1 + x)² − 1 − x + 1 = x² + 2x + 1 − x = x² + x + 1 = f(x)","lv":"কঠিন","ex":"2.2"},{"n":"b99","q":"A = {−2, −1, 0, 1, 2}, B = {0, 1, 4} এবং S = {(x, y) : x ∈ A, y ∈ B এবং y = x²}। S কি ফাংশন? ডোমেন ও রেঞ্জ লেখ।","a":"S = {(−2, 4), (−1, 1), (0, 0), (1, 1), (2, 4)}\nপ্রতিটি x এর একটিমাত্র প্রতিচ্ছবি, তাই S ফাংশন।\nডোম S = A, রেঞ্জ S = {0, 1, 4}","lv":"কঠিন","ex":"2.2"},{"n":"b100","q":"R = {(1, 2), (2, 3), (3, 2)} অন্বয়টি ফাংশন কি না যাচাই কর এবং এর রেঞ্জ লেখ।","a":"প্রতিটি প্রথম উপাদান 1, 2, 3 এর একটিমাত্র প্রতিচ্ছবি, তাই R ফাংশন।\nরেঞ্জ R = {2, 3}","lv":"মধ্যম","ex":"2.2"}],"3":[{"n":"b1","q":"a + b = 7 এবং ab = 12 হলে a² + b² এর মান নির্ণয় কর।","a":"a² + b² = (a + b)² − 2ab = 49 − 24 = 25","lv":"মধ্যম","ex":"3.1"},{"n":"b2","q":"a − b = 3 এবং ab = 10 হলে a² + b² ও (a + b)² এর মান নির্ণয় কর।","a":"a² + b² = (a − b)² + 2ab = 9 + 20 = 29\n(a + b)² = (a − b)² + 4ab = 9 + 40 = 49","lv":"মধ্যম","ex":"3.1"},{"n":"b3","q":"x + 1/x = 4 হলে x² + 1/x² ও x⁴ + 1/x⁴ এর মান নির্ণয় কর।","a":"x² + 1/x² = 4² − 2 = 14\nx⁴ + 1/x⁴ = 14² − 2 = 194","lv":"কঠিন","ex":"3.1"},{"n":"b4","q":"x − 1/x = 3 হলে x² + 1/x² ও (x + 1/x)² এর মান নির্ণয় কর।","a":"x² + 1/x² = 3² + 2 = 11\n(x + 1/x)² = 11 + 2 = 13","lv":"মধ্যম","ex":"3.1"},{"n":"b5","q":"a + b + c = 9 এবং ab + bc + ca = 26 হলে a² + b² + c² এর মান নির্ণয় কর।","a":"a² + b² + c² = (a + b + c)² − 2(ab + bc + ca) = 81 − 52 = 29","lv":"মধ্যম","ex":"3.1"},{"n":"b6","q":"a² + b² + c² = 50 এবং a + b + c = 10 হলে ab + bc + ca এর মান নির্ণয় কর।","a":"2(ab + bc + ca) = (a + b + c)² − (a² + b² + c²) = 100 − 50 = 50\n∴ ab + bc + ca = 25","lv":"মধ্যম","ex":"3.1"},{"n":"b7","q":"সূত্রের সাহায্যে (2a + 3b − c)² এর বর্গ নির্ণয় কর।","a":"= 4a² + 9b² + c² + 12ab − 6bc − 4ac","lv":"মধ্যম","ex":"3.1"},{"n":"b8","q":"সূত্রের সাহায্যে 1005 এর বর্গ নির্ণয় কর।","a":"1005² = (1000 + 5)² = 1000000 + 10000 + 25 = 1010025","lv":"মধ্যম","ex":"3.1"},{"n":"b9","q":"সূত্রের সাহায্যে 997 এর বর্গ নির্ণয় কর।","a":"997² = (1000 − 3)² = 1000000 − 6000 + 9 = 994009","lv":"মধ্যম","ex":"3.1"},{"n":"b10","q":"সূত্রের সাহায্যে 103 × 97 এর মান নির্ণয় কর।","a":"103 × 97 = (100 + 3)(100 − 3) = 10000 − 9 = 9991","lv":"মধ্যম","ex":"3.1"},{"n":"b11","q":"a + b = √7 এবং a − b = √3 হলে ab ও a² + b² এর মান নির্ণয় কর।","a":"4ab = (a + b)² − (a − b)² = 7 − 3 = 4 ⇒ ab = 1\n2(a² + b²) = 7 + 3 = 10 ⇒ a² + b² = 5","lv":"কঠিন","ex":"3.1"},{"n":"b12","q":"x = 2 + √3 হলে x + 1/x ও x² + 1/x² এর মান নির্ণয় কর।","a":"1/x = 1/(2 + √3) = 2 − √3\nx + 1/x = 4, x² + 1/x² = 16 − 2 = 14","lv":"কঠিন","ex":"3.1"},{"n":"b13","q":"x = √5 + 2 হলে x − 1/x ও x² + 1/x² এর মান নির্ণয় কর।","a":"1/x = √5 − 2 ⇒ x − 1/x = 4\nx² + 1/x² = (x − 1/x)² + 2 = 18","lv":"কঠিন","ex":"3.1"},{"n":"b14","q":"x² + 6x + 8 কে দুইটি বর্গের অন্তররূপে প্রকাশ কর।","a":"x² + 6x + 8 = (x² + 6x + 9) − 1 = (x + 3)² − 1²","lv":"মধ্যম","ex":"3.1"},{"n":"b15","q":"প্রমাণ কর যে, (a + b)² + (a − b)² = 2(a² + b²)","a":"বামপক্ষ = a² + 2ab + b² + a² − 2ab + b² = 2a² + 2b² = 2(a² + b²)","lv":"মধ্যম","ex":"3.1"},{"n":"b16","q":"a² + b² = 13 এবং ab = 6 হলে a + b ও a − b এর মান নির্ণয় কর।","a":"(a + b)² = 13 + 12 = 25 ⇒ a + b = ±5\n(a − b)² = 13 − 12 = 1 ⇒ a − b = ±1","lv":"কঠিন","ex":"3.1"},{"n":"b17","q":"সরল কর: (3x + 2y)² − (3x − 2y)²","a":"= 4 · 3x · 2y = 24xy","lv":"মধ্যম","ex":"3.1"},{"n":"b18","q":"সরল কর: (x + y)² + 2(x + y)(x − y) + (x − y)²","a":"= {(x + y) + (x − y)}² = (2x)² = 4x²","lv":"কঠিন","ex":"3.1"},{"n":"b19","q":"সরল কর: (a − b)² + 2(a − b)(b − c) + (b − c)²","a":"= {(a − b) + (b − c)}² = (a − c)²","lv":"কঠিন","ex":"3.1"},{"n":"b20","q":"m + 1/m = 3 হলে m⁴ + 1/m⁴ এর মান নির্ণয় কর।","a":"m² + 1/m² = 9 − 2 = 7\nm⁴ + 1/m⁴ = 49 − 2 = 47","lv":"কঠিন","ex":"3.1"},{"n":"b21","q":"x + y = 10 এবং xy = 21 হলে x − y ও x² − y² এর মান নির্ণয় কর।","a":"(x − y)² = 100 − 84 = 16 ⇒ x − y = ±4\nx² − y² = (x + y)(x − y) = ±40","lv":"কঠিন","ex":"3.1"},{"n":"b22","q":"a + b = 6 এবং a − b = 2 হলে সূত্র ব্যবহার করে a² + b² ও ab নির্ণয় কর।","a":"2(a² + b²) = 36 + 4 ⇒ a² + b² = 20\n4ab = 36 − 4 ⇒ ab = 8","lv":"মধ্যম","ex":"3.1"},{"n":"b23","q":"x = 3.5 হলে 4x² + 12x + 9 এর মান নির্ণয় কর।","a":"4x² + 12x + 9 = (2x + 3)² = (7 + 3)² = 100","lv":"মধ্যম","ex":"3.1"},{"n":"b24","q":"x = 1 এবং y = 2 হলে 25x² − 30xy + 9y² এর মান নির্ণয় কর।","a":"= (5x − 3y)² = (5 − 6)² = 1","lv":"মধ্যম","ex":"3.1"},{"n":"b25","q":"a² + 1/a² = 7 এবং a > 0 হলে a + 1/a ও a − 1/a এর মান নির্ণয় কর।","a":"(a + 1/a)² = 7 + 2 = 9 ⇒ a + 1/a = 3\n(a − 1/a)² = 7 − 2 = 5 ⇒ a − 1/a = ±√5","lv":"কঠিন","ex":"3.1"},{"n":"b26","q":"a + b + c = 0 হলে প্রমাণ কর যে, a² + b² + c² = −2(ab + bc + ca)","a":"(a + b + c)² = a² + b² + c² + 2(ab + bc + ca) = 0\n∴ a² + b² + c² = −2(ab + bc + ca)","lv":"মধ্যম","ex":"3.1"},{"n":"b27","q":"x² − 4x + 1 = 0 হলে x² + 1/x² এর মান নির্ণয় কর।","a":"x দিয়ে ভাগ করে x − 4 + 1/x = 0 ⇒ x + 1/x = 4\nx² + 1/x² = 16 − 2 = 14","lv":"কঠিন","ex":"3.1"},{"n":"b28","q":"(x + 5)(x − 3) কে দুইটি বর্গের অন্তররূপে প্রকাশ কর।","a":"= {(x + 5 + x − 3)/2}² − {(x + 5 − x + 3)/2}² = (x + 1)² − 4²","lv":"কঠিন","ex":"3.1"},{"n":"b29","q":"p − q = 5 এবং pq = 14 হলে p² + q² ও p + q এর মান নির্ণয় কর।","a":"p² + q² = 25 + 28 = 53\n(p + q)² = 25 + 56 = 81 ⇒ p + q = ±9","lv":"মধ্যম","ex":"3.1"},{"n":"b30","q":"a + b + c = 4 হলে a = 5, b = −3, c = 2 এর জন্য যাচাই কর যে (a + b + c)² = a² + b² + c² + 2(ab + bc + ca)","a":"বামপক্ষ = 4² = 16\nডানপক্ষ = 25 + 9 + 4 + 2(−15 − 6 + 10) = 38 − 22 = 16 ∴ সমান।","lv":"মধ্যম","ex":"3.1"},{"n":"b31","q":"a + b = 5 এবং ab = 6 হলে a³ + b³ এর মান নির্ণয় কর।","a":"a³ + b³ = (a + b)³ − 3ab(a + b) = 125 − 90 = 35","lv":"মধ্যম","ex":"3.2"},{"n":"b32","q":"a − b = 2 এবং ab = 15 হলে a³ − b³ এর মান নির্ণয় কর।","a":"a³ − b³ = (a − b)³ + 3ab(a − b) = 8 + 90 = 98","lv":"মধ্যম","ex":"3.2"},{"n":"b33","q":"x + 1/x = 3 হলে x³ + 1/x³ এর মান নির্ণয় কর।","a":"x³ + 1/x³ = (x + 1/x)³ − 3(x + 1/x) = 27 − 9 = 18","lv":"মধ্যম","ex":"3.2"},{"n":"b34","q":"x − 1/x = 2 হলে x³ − 1/x³ এর মান নির্ণয় কর।","a":"x³ − 1/x³ = (x − 1/x)³ + 3(x − 1/x) = 8 + 6 = 14","lv":"মধ্যম","ex":"3.2"},{"n":"b35","q":"সূত্রের সাহায্যে (2x − 3y)³ এর ঘন নির্ণয় কর।","a":"= 8x³ − 36x²y + 54xy² − 27y³","lv":"মধ্যম","ex":"3.2"},{"n":"b36","q":"সূত্রের সাহায্যে 103 এর ঘন নির্ণয় কর।","a":"(100 + 3)³ = 1000000 + 90000 + 2700 + 27 = 1092727","lv":"কঠিন","ex":"3.2"},{"n":"b37","q":"সূত্রের সাহায্যে 98 এর ঘন নির্ণয় কর।","a":"(100 − 2)³ = 1000000 − 60000 + 1200 − 8 = 941192","lv":"কঠিন","ex":"3.2"},{"n":"b38","q":"a = 2, b = 3, c = −5 হলে দেখাও যে, a³ + b³ + c³ = 3abc","a":"a + b + c = 0\na³ + b³ + c³ = 8 + 27 − 125 = −90; 3abc = 3 · 2 · 3 · (−5) = −90 ∴ সমান।","lv":"মধ্যম","ex":"3.2"},{"n":"b39","q":"x = 2 + √3 হলে x³ + 1/x³ এর মান নির্ণয় কর।","a":"1/x = 2 − √3 ⇒ x + 1/x = 4\nx³ + 1/x³ = 64 − 12 = 52","lv":"কঠিন","ex":"3.2"},{"n":"b40","q":"a + b = 4 এবং a² + b² = 10 হলে a³ + b³ এর মান নির্ণয় কর।","a":"2ab = 16 − 10 ⇒ ab = 3\na³ + b³ = 64 − 3 · 3 · 4 = 28","lv":"কঠিন","ex":"3.2"},{"n":"b41","q":"সরল কর: (a + b)³ − (a − b)³","a":"= 2(3a²b + b³) = 6a²b + 2b³","lv":"মধ্যম","ex":"3.2"},{"n":"b42","q":"সরল কর: (x + 2)³ − (x − 2)³","a":"= 2(3 · x² · 2 + 8) = 12x² + 16","lv":"মধ্যম","ex":"3.2"},{"n":"b43","q":"x = 3 এবং y = 1 হলে 8x³ − 12x²y + 6xy² − y³ এর মান নির্ণয় কর।","a":"= (2x − y)³ = (6 − 1)³ = 125","lv":"মধ্যম","ex":"3.2"},{"n":"b44","q":"p − q = 3 এবং p³ − q³ = 117 হলে pq এর মান নির্ণয় কর।","a":"p³ − q³ = (p − q)³ + 3pq(p − q) ⇒ 117 = 27 + 9pq ⇒ pq = 10","lv":"কঠিন","ex":"3.2"},{"n":"b45","q":"a + 1/a = √3 হলে a³ + 1/a³ এর মান নির্ণয় কর।","a":"a³ + 1/a³ = (√3)³ − 3√3 = 3√3 − 3√3 = 0","lv":"কঠিন","ex":"3.2"},{"n":"b46","q":"x² − 5x + 1 = 0 হলে x³ + 1/x³ এর মান নির্ণয় কর।","a":"x + 1/x = 5\nx³ + 1/x³ = 125 − 15 = 110","lv":"কঠিন","ex":"3.2"},{"n":"b47","q":"a = √3 + √2 হলে a³ + 1/a³ এর মান নির্ণয় কর।","a":"1/a = √3 − √2 ⇒ a + 1/a = 2√3\na³ + 1/a³ = (2√3)³ − 3 · 2√3 = 24√3 − 6√3 = 18√3","lv":"কঠিন","ex":"3.2"},{"n":"b48","q":"x + y = 2 এবং x³ + y³ = 26 হলে xy এর মান নির্ণয় কর।","a":"26 = 2³ − 3xy · 2 ⇒ 6xy = −18 ⇒ xy = −3","lv":"কঠিন","ex":"3.2"},{"n":"b49","q":"a − b = 1 এবং ab = 6 হলে a³ − b³ এর মান নির্ণয় কর।","a":"a³ − b³ = 1 + 3 · 6 · 1 = 19","lv":"মধ্যম","ex":"3.2"},{"n":"b50","q":"m + n = 6 এবং mn = 8 হলে m³ + n³ এর মান নির্ণয় কর।","a":"m³ + n³ = 216 − 3 · 8 · 6 = 72","lv":"মধ্যম","ex":"3.2"},{"n":"b51","q":"প্রমাণ কর যে, (x − y)³ + (y − z)³ + (z − x)³ = 3(x − y)(y − z)(z − x)","a":"a = x − y, b = y − z, c = z − x ধরলে a + b + c = 0\n∴ a³ + b³ + c³ = 3abc = 3(x − y)(y − z)(z − x)","lv":"কঠিন","ex":"3.2"},{"n":"b52","q":"6.2³ + 3.8³ + 3 × 6.2 × 3.8 × 10 এর মান নির্ণয় কর।","a":"a = 6.2, b = 3.8 হলে a + b = 10\nরাশি = a³ + b³ + 3ab(a + b) = (a + b)³ = 1000","lv":"কঠিন","ex":"3.2"},{"n":"b53","q":"5.5³ − 4.5³ − 3 × 5.5 × 4.5 × 1 এর মান নির্ণয় কর।","a":"a = 5.5, b = 4.5 হলে a − b = 1\nরাশি = a³ − b³ − 3ab(a − b) = (a − b)³ = 1","lv":"কঠিন","ex":"3.2"},{"n":"b54","q":"x = 1 − √2 হলে x³ − 1/x³ এর মান নির্ণয় কর।","a":"1/x = −(1 + √2) ⇒ x − 1/x = 2\nx³ − 1/x³ = 8 + 6 = 14","lv":"কঠিন","ex":"3.2"},{"n":"b55","q":"a + b = 1 হলে প্রমাণ কর যে, a³ + b³ + 3ab = 1","a":"a³ + b³ = (a + b)³ − 3ab(a + b) = 1 − 3ab\n∴ a³ + b³ + 3ab = 1","lv":"মধ্যম","ex":"3.2"},{"n":"b56","q":"a − b = 1 হলে প্রমাণ কর যে, a³ − b³ − 3ab = 1","a":"a³ − b³ = (a − b)³ + 3ab(a − b) = 1 + 3ab\n∴ a³ − b³ − 3ab = 1","lv":"মধ্যম","ex":"3.2"},{"n":"b57","q":"2a + 1/(2a) = 6 হলে 8a³ + 1/(8a³) এর মান নির্ণয় কর।","a":"= (2a + 1/(2a))³ − 3(2a + 1/(2a)) = 216 − 18 = 198","lv":"কঠিন","ex":"3.2"},{"n":"b58","q":"সূত্রের সাহায্যে (a − 2b)³ এর ঘন নির্ণয় কর।","a":"= a³ − 6a²b + 12ab² − 8b³","lv":"মধ্যম","ex":"3.2"},{"n":"b59","q":"a² + b² = 29, ab = 10 এবং a > b > 0 হলে a³ − b³ এর মান নির্ণয় কর।","a":"(a − b)² = 29 − 20 = 9 ⇒ a − b = 3\na³ − b³ = 27 + 3 · 10 · 3 = 117","lv":"কঠিন","ex":"3.2"},{"n":"b60","q":"x + y = 5 এবং x − y = 1 হলে 8xy(x² + y²) এর মান নির্ণয় কর।","a":"8xy(x² + y²) = (x + y)⁴ − (x − y)⁴ = 625 − 1 = 624","lv":"কঠিন","ex":"3.2"},{"n":"b61","q":"উৎপাদকে বিশ্লেষণ কর: x⁴ + x² + 1","a":"= (x² + 1)² − x²\n= (x² + x + 1)(x² − x + 1)","lv":"কঠিন","ex":"3.3"},{"n":"b62","q":"উৎপাদকে বিশ্লেষণ কর: a⁴ + 4","a":"= (a² + 2)² − (2a)²\n= (a² + 2a + 2)(a² − 2a + 2)","lv":"কঠিন","ex":"3.3"},{"n":"b63","q":"উৎপাদকে বিশ্লেষণ কর: x² − 2xy + y² − z²","a":"= (x − y)² − z²\n= (x − y + z)(x − y − z)","lv":"মধ্যম","ex":"3.3"},{"n":"b64","q":"উৎপাদকে বিশ্লেষণ কর: 4a² − 12ab + 9b² − 16c²","a":"= (2a − 3b)² − (4c)²\n= (2a − 3b + 4c)(2a − 3b − 4c)","lv":"কঠিন","ex":"3.3"},{"n":"b65","q":"উৎপাদকে বিশ্লেষণ কর: x³ + 27y³","a":"a³ + b³ সূত্র\n= (x + 3y)(x² − 3xy + 9y²)","lv":"মধ্যম","ex":"3.3"},{"n":"b66","q":"উৎপাদকে বিশ্লেষণ কর: 8a³ − 125","a":"a³ − b³ সূত্র\n= (2a − 5)(4a² + 10a + 25)","lv":"মধ্যম","ex":"3.3"},{"n":"b67","q":"উৎপাদকে বিশ্লেষণ কর: a³ + b³ + a + b","a":"= (a + b)(a² − ab + b²) + (a + b)\n= (a + b)(a² − ab + b² + 1)","lv":"কঠিন","ex":"3.3"},{"n":"b68","q":"উৎপাদকে বিশ্লেষণ কর: x³ − 7x − 6","a":"x = −1 এ রাশি 0, তাই (x + 1) উৎপাদক\n= (x + 1)(x + 2)(x − 3)","lv":"মধ্যম","ex":"3.3"},{"n":"b69","q":"উৎপাদকে বিশ্লেষণ কর: x³ − 6x² + 11x − 6","a":"x = 1 এ রাশি 0, তাই (x − 1) উৎপাদক\n= (x − 1)(x − 2)(x − 3)","lv":"মধ্যম","ex":"3.3"},{"n":"b70","q":"উৎপাদকে বিশ্লেষণ কর: 2x² + 7x + 3","a":"মধ্যপদ বিভক্তি: 2x² + 6x + x + 3\n= (2x + 1)(x + 3)","lv":"মধ্যম","ex":"3.3"},{"n":"b71","q":"উৎপাদকে বিশ্লেষণ কর: 6x² − x − 15","a":"মধ্যপদ বিভক্তি: 6x² − 10x + 9x − 15\n= (2x + 3)(3x − 5)","lv":"মধ্যম","ex":"3.3"},{"n":"b72","q":"উৎপাদকে বিশ্লেষণ কর: 3x² − 10xy + 3y²","a":"মধ্যপদ বিভক্তি: 3x² − 9xy − xy + 3y²\n= (3x − y)(x − 3y)","lv":"মধ্যম","ex":"3.3"},{"n":"b73","q":"উৎপাদকে বিশ্লেষণ কর: x⁴ − 13x² + 36","a":"= (x² − 4)(x² − 9)\n= (x + 2)(x − 2)(x + 3)(x − 3)","lv":"কঠিন","ex":"3.3"},{"n":"b74","q":"উৎপাদকে বিশ্লেষণ কর: (x² + x)² − 8(x² + x) + 12","a":"x² + x = a ধরলে a² − 8a + 12 = (a − 2)(a − 6)\n= (x + 2)(x − 1)(x + 3)(x − 2)","lv":"কঠিন","ex":"3.3"},{"n":"b75","q":"উৎপাদকে বিশ্লেষণ কর: a³ − 9a² + 26a − 24","a":"a = 2 এ রাশি 0\n= (a − 2)(a − 3)(a − 4)","lv":"মধ্যম","ex":"3.3"},{"n":"b76","q":"উৎপাদকে বিশ্লেষণ কর: x³ + 2x² − 5x − 6","a":"x = −1 এ রাশি 0\n= (x + 1)(x − 2)(x + 3)","lv":"মধ্যম","ex":"3.3"},{"n":"b77","q":"উৎপাদকে বিশ্লেষণ কর: 1 − a² + 2ab − b²","a":"= 1 − (a − b)²\n= (1 + a − b)(1 − a + b)","lv":"মধ্যম","ex":"3.3"},{"n":"b78","q":"উৎপাদকে বিশ্লেষণ কর: x² + 1/x² + 2 − 2x − 2/x","a":"x + 1/x = a ধরলে রাশি = a² − 2a\n= (x + 1/x)(x + 1/x − 2)","lv":"কঠিন","ex":"3.3"},{"n":"b79","q":"উৎপাদকে বিশ্লেষণ কর: a⁶ − 64","a":"= (a³ − 8)(a³ + 8)\n= (a + 2)(a − 2)(a² + 2a + 4)(a² − 2a + 4)","lv":"কঠিন","ex":"3.3"},{"n":"b80","q":"উৎপাদকে বিশ্লেষণ কর: x³ − 3x² + 4","a":"x = −1 এ রাশি 0, তারপর x² − 4x + 4\n= (x + 1)(x − 2)²","lv":"মধ্যম","ex":"3.3"},{"n":"b81","q":"উৎপাদকে বিশ্লেষণ কর: 4x⁴ + 1","a":"= (2x² + 1)² − (2x)²\n= (2x² + 2x + 1)(2x² − 2x + 1)","lv":"কঠিন","ex":"3.3"},{"n":"b82","q":"উৎপাদকে বিশ্লেষণ কর: (a + b)² − 5(a + b) + 6","a":"a + b = p ধরলে p² − 5p + 6\n= (a + b − 2)(a + b − 3)","lv":"মধ্যম","ex":"3.3"},{"n":"b83","q":"উৎপাদকে বিশ্লেষণ কর: x² − y² − 6y − 9","a":"= x² − (y + 3)²\n= (x + y + 3)(x − y − 3)","lv":"মধ্যম","ex":"3.3"},{"n":"b84","q":"উৎপাদকে বিশ্লেষণ কর: 2a³ + 16","a":"= 2(a³ + 8)\n= 2(a + 2)(a² − 2a + 4)","lv":"মধ্যম","ex":"3.3"},{"n":"b85","q":"উৎপাদকে বিশ্লেষণ কর: ab(x² + y²) + xy(a² + b²)","a":"= abx² + aby² + a²xy + b²xy = ax(bx + ay) + by(ay + bx)\n= (ax + by)(bx + ay)","lv":"কঠিন","ex":"3.3"},{"n":"b86","q":"উৎপাদকে বিশ্লেষণ কর: x⁴ − 5x² + 4","a":"= (x² − 1)(x² − 4)\n= (x + 1)(x − 1)(x + 2)(x − 2)","lv":"মধ্যম","ex":"3.3"},{"n":"b87","q":"উৎপাদকে বিশ্লেষণ কর: 12x² − 7x + 1","a":"মধ্যপদ বিভক্তি: 12x² − 4x − 3x + 1\n= (3x − 1)(4x − 1)","lv":"মধ্যম","ex":"3.3"},{"n":"b88","q":"উৎপাদকে বিশ্লেষণ কর: a² + 6a + 8 − y² + 2y","a":"= (a + 3)² − (y − 1)²\n= (a + y + 2)(a − y + 4)","lv":"কঠিন","ex":"3.3"},{"n":"b89","q":"উৎপাদকে বিশ্লেষণ কর: x³ + 3x² + 3x + 9","a":"= x²(x + 3) + 3(x + 3)\n= (x + 3)(x² + 3)","lv":"মধ্যম","ex":"3.3"},{"n":"b90","q":"উৎপাদকে বিশ্লেষণ কর: 2x³ − 3x² − 3x + 2","a":"x = −1 এ রাশি 0\n= (x + 1)(2x − 1)(x − 2)","lv":"কঠিন","ex":"3.3"},{"n":"b91","q":"ভাগশেষ উপপাদ্য ব্যবহার করে x³ − 2x² + 4x − 5 কে (x − 2) দ্বারা ভাগ করলে ভাগশেষ নির্ণয় কর।","a":"ভাগশেষ = P(2) = 8 − 8 + 8 − 5 = 3","lv":"মধ্যম","ex":"3.4"},{"n":"b92","q":"দেখাও যে, (x + 2) রাশিটি x³ + 3x² − 4 এর একটি উৎপাদক।","a":"P(−2) = −8 + 12 − 4 = 0\n∴ উৎপাদক উপপাদ্য অনুসারে (x + 2) একটি উৎপাদক।","lv":"মধ্যম","ex":"3.4"},{"n":"b93","q":"2x³ − 5x² + kx + 6 রাশিটি (x − 2) দ্বারা বিভাজ্য হলে k এর মান নির্ণয় কর।","a":"P(2) = 16 − 20 + 2k + 6 = 0 ⇒ 2k = −2 ⇒ k = −1","lv":"মধ্যম","ex":"3.4"},{"n":"b94","q":"x² + ax + b রাশির দুইটি উৎপাদক (x − 1) ও (x + 3) হলে a ও b এর মান নির্ণয় কর।","a":"(x − 1)(x + 3) = x² + 2x − 3\n∴ a = 2, b = −3","lv":"মধ্যম","ex":"3.4"},{"n":"b95","q":"x³ + ax² − 4x + 4 কে (x − 1) দ্বারা ভাগ করলে ভাগশেষ 3 হয়। a এর মান নির্ণয় কর।","a":"P(1) = 1 + a − 4 + 4 = 3 ⇒ a = 2","lv":"মধ্যম","ex":"3.4"},{"n":"b96","q":"3x³ − 2x² + x − 4 কে (3x − 2) দ্বারা ভাগ করলে ভাগশেষ কত?","a":"ভাগশেষ = P(2/3) = 8/9 − 8/9 + 2/3 − 4 = −10/3","lv":"কঠিন","ex":"3.4"},{"n":"b97","q":"4x³ − 3x + 1 কে (2x + 1) দ্বারা ভাগ করলে ভাগশেষ কত?","a":"ভাগশেষ = P(−1/2) = −1/2 + 3/2 + 1 = 2","lv":"কঠিন","ex":"3.4"},{"n":"b98","q":"দেখাও যে, x¹⁰⁰ − 1 রাশির একটি উৎপাদক (x − 1)।","a":"P(1) = 1¹⁰⁰ − 1 = 0\n∴ (x − 1) একটি উৎপাদক।","lv":"মধ্যম","ex":"3.4"},{"n":"b99","q":"n বিজোড় স্বাভাবিক সংখ্যা হলে দেখাও যে, (x + 1) রাশিটি xⁿ + 1 এর উৎপাদক।","a":"P(−1) = (−1)ⁿ + 1 = −1 + 1 = 0 (n বিজোড়)\n∴ (x + 1) উৎপাদক।","lv":"কঠিন","ex":"3.4"},{"n":"b100","q":"ax³ + 3x² − 13 এবং 2x³ − 5x + a কে (x − 2) দ্বারা ভাগ করলে একই ভাগশেষ থাকে। a এর মান নির্ণয় কর।","a":"8a + 12 − 13 = 16 − 10 + a ⇒ 8a − 1 = 6 + a ⇒ a = 1","lv":"কঠিন","ex":"3.4"},{"n":"b101","q":"x³ + px² + qx + 6 রাশির দুইটি উৎপাদক (x − 1) ও (x − 2) হলে p ও q এর মান নির্ণয় কর।","a":"P(1) = 0 ⇒ p + q = −7\nP(2) = 0 ⇒ 4p + 2q = −14 ⇒ 2p + q = −7\n∴ p = 0, q = −7","lv":"কঠিন","ex":"3.4"},{"n":"b102","q":"x³ − 3x² + kx − 10 কে (x − 3) দ্বারা ভাগ করলে ভাগশেষ 2 হয়। k এর মান নির্ণয় কর।","a":"P(3) = 27 − 27 + 3k − 10 = 2 ⇒ k = 4","lv":"মধ্যম","ex":"3.4"},{"n":"b103","q":"উৎপাদক উপপাদ্যের সাহায্যে x³ − x² − 4x + 4 কে উৎপাদকে বিশ্লেষণ কর।","a":"P(1) = 0 ⇒ (x − 1) উৎপাদক\n= x²(x − 1) − 4(x − 1) = (x − 1)(x − 2)(x + 2)","lv":"মধ্যম","ex":"3.4"},{"n":"b104","q":"x⁴ + 2x³ − 7x² − 8x + 12 কে উৎপাদকে বিশ্লেষণ কর।","a":"P(1) = 0, P(2) = 0, P(−2) = 0, P(−3) = 0\n= (x − 1)(x − 2)(x + 2)(x + 3)","lv":"কঠিন","ex":"3.4"},{"n":"b105","q":"x¹⁰ + 1 কে (x + 1) দ্বারা ভাগ করলে ভাগশেষ কত?","a":"P(−1) = 1 + 1 = 2","lv":"মধ্যম","ex":"3.4"},{"n":"b106","q":"x³ − 6x² + 9x − 4 কে উৎপাদকে বিশ্লেষণ কর।","a":"P(1) = 0 ⇒ (x − 1) উৎপাদক; ভাগফল x² − 5x + 4 = (x − 1)(x − 4)\n= (x − 1)²(x − 4)","lv":"কঠিন","ex":"3.4"},{"n":"b107","q":"2x² + 3x − k কে (x + 3) দ্বারা ভাগ করলে ভাগশেষ 4 হয়। k এর মান নির্ণয় কর।","a":"P(−3) = 18 − 9 − k = 4 ⇒ k = 5","lv":"মধ্যম","ex":"3.4"},{"n":"b108","q":"kx³ − 4x² + 3x − 8 কে (x − 2) দ্বারা ভাগ করলে ভাগশেষ 10 হয়। k এর মান নির্ণয় কর।","a":"8k − 16 + 6 − 8 = 10 ⇒ 8k = 28 ⇒ k = 7/2","lv":"কঠিন","ex":"3.4"},{"n":"b109","q":"(x − a) রাশিটি x³ − a²x + x + 2 এর উৎপাদক হলে a এর মান নির্ণয় কর।","a":"P(a) = a³ − a³ + a + 2 = 0 ⇒ a = −2","lv":"কঠিন","ex":"3.4"},{"n":"b110","q":"2x³ + x² − 13x + 6 কে উৎপাদকে বিশ্লেষণ কর।","a":"P(2) = 0 ⇒ (x − 2) উৎপাদক; ভাগফল 2x² + 5x − 3 = (2x − 1)(x + 3)\n= (x − 2)(2x − 1)(x + 3)","lv":"কঠিন","ex":"3.4"},{"n":"b111","q":"x³ + 6x² + 11x + 6 কে উৎপাদকে বিশ্লেষণ কর।","a":"P(−1) = 0 ⇒ (x + 1) উৎপাদক; ভাগফল x² + 5x + 6\n= (x + 1)(x + 2)(x + 3)","lv":"মধ্যম","ex":"3.4"},{"n":"b112","q":"x³ + 2x² − x + k কে (x − 1) দ্বারা ভাগ করলে ভাগশেষ 5 হয়। k এর মান নির্ণয় কর।","a":"P(1) = 1 + 2 − 1 + k = 5 ⇒ k = 3","lv":"মধ্যম","ex":"3.4"},{"n":"b113","q":"(2x − 1) রাশিটি 2x³ + 5x² − 4x + 1 এর উৎপাদক কি না যাচাই কর।","a":"P(1/2) = 1/4 + 5/4 − 2 + 1 = 1/2 ≠ 0\n∴ উৎপাদক নয়; ভাগশেষ 1/2","lv":"কঠিন","ex":"3.4"},{"n":"b114","q":"a³ + 3a² − 4 কে উৎপাদকে বিশ্লেষণ কর।","a":"P(1) = 0 ⇒ (a − 1) উৎপাদক; ভাগফল a² + 4a + 4\n= (a − 1)(a + 2)²","lv":"মধ্যম","ex":"3.4"},{"n":"b115","q":"x³ − 19x − 30 কে উৎপাদকে বিশ্লেষণ কর।","a":"P(−2) = 0 ⇒ (x + 2) উৎপাদক; ভাগফল x² − 2x − 15 = (x − 5)(x + 3)\n= (x + 2)(x + 3)(x − 5)","lv":"কঠিন","ex":"3.4"},{"n":"b116","q":"x³ + 1 কে (x − 1/2) দ্বারা ভাগ করলে ভাগশেষ কত?","a":"P(1/2) = 1/8 + 1 = 9/8","lv":"মধ্যম","ex":"3.4"},{"n":"b117","q":"উৎপাদক উপপাদ্যের সাহায্যে দেখাও যে, (a + b) রাশিটি a³ + b³ + a² − b² এর উৎপাদক।","a":"a = −b বসালে: −b³ + b³ + b² − b² = 0\n∴ (a + b) উৎপাদক।","lv":"কঠিন","ex":"3.4"},{"n":"b118","q":"6x³ − 11x² + 6x − 1 কে উৎপাদকে বিশ্লেষণ কর।","a":"P(1) = 0 ⇒ (x − 1) উৎপাদক; ভাগফল 6x² − 5x + 1 = (2x − 1)(3x − 1)\n= (x − 1)(2x − 1)(3x − 1)","lv":"কঠিন","ex":"3.4"},{"n":"b119","q":"x⁴ + ax + b রাশিটি x² − 3x + 2 দ্বারা বিভাজ্য হলে a ও b এর মান নির্ণয় কর।","a":"x² − 3x + 2 = (x − 1)(x − 2)\nP(1) = 1 + a + b = 0, P(2) = 16 + 2a + b = 0\n∴ a = −15, b = 14","lv":"কঠিন","ex":"3.4"},{"n":"b120","q":"x³ + 2x² + 2x + 1 কে উৎপাদকে বিশ্লেষণ কর।","a":"P(−1) = 0 ⇒ (x + 1) উৎপাদক\n= (x + 1)(x² + x + 1)","lv":"মধ্যম","ex":"3.4"},{"n":"b121","q":"ক একটি কাজ 12 দিনে এবং খ 18 দিনে করতে পারে। দুজনে একত্রে কাজটি কত দিনে করবে?","a":"একত্রে 1 দিনে করে 1/12 + 1/18 = 5/36 অংশ\n∴ সময় = 36/5 = 7.2 দিন","lv":"মধ্যম","ex":"3.5"},{"n":"b122","q":"ক ও খ একত্রে একটি কাজ 10 দিনে করে। ক একা 15 দিনে করলে খ একা কত দিনে করবে?","a":"খ এর 1 দিনের কাজ = 1/10 − 1/15 = 1/30\n∴ খ একা 30 দিনে করবে।","lv":"মধ্যম","ex":"3.5"},{"n":"b123","q":"একটি নল চৌবাচ্চা 6 ঘণ্টায় পূর্ণ করে, অন্য একটি নল 9 ঘণ্টায় খালি করে। দুইটি একসাথে খুলে দিলে খালি চৌবাচ্চা কত সময়ে পূর্ণ হবে?","a":"1 ঘণ্টায় পূর্ণ হয় 1/6 − 1/9 = 1/18 অংশ\n∴ 18 ঘণ্টা","lv":"কঠিন","ex":"3.5"},{"n":"b124","q":"স্থির পানিতে নৌকার বেগ ঘণ্টায় 12 কিমি এবং স্রোতের বেগ ঘণ্টায় 3 কিমি। নৌকাটি স্রোতের অনুকূলে 36 কিমি গিয়ে আবার ফিরে আসতে কত সময় লাগবে?","a":"অনুকূলে বেগ 15, প্রতিকূলে 9 কিমি/ঘণ্টা\nসময় = 36/15 + 36/9 = 2.4 + 4 = 6.4 ঘণ্টা = 6 ঘণ্টা 24 মিনিট","lv":"কঠিন","ex":"3.5"},{"n":"b125","q":"150 মিটার দীর্ঘ একটি ট্রেন ঘণ্টায় 54 কিমি বেগে চলে। একটি খুঁটি অতিক্রম করতে ট্রেনটির কত সময় লাগবে?","a":"54 কিমি/ঘণ্টা = 15 মি/সে\nসময় = 150/15 = 10 সেকেন্ড","lv":"মধ্যম","ex":"3.5"},{"n":"b126","q":"200 মিটার দীর্ঘ একটি ট্রেন ঘণ্টায় 72 কিমি বেগে চলে 300 মিটার দীর্ঘ একটি সেতু কত সময়ে অতিক্রম করবে?","a":"72 কিমি/ঘণ্টা = 20 মি/সে, অতিক্রান্ত দূরত্ব = 200 + 300 = 500 মি\nসময় = 25 সেকেন্ড","lv":"কঠিন","ex":"3.5"},{"n":"b127","q":"বার্ষিক 8% সরল মুনাফায় 5000 টাকার 3 বছরের মুনাফা ও মুনাফা-আসল নির্ণয় কর।","a":"মুনাফা = 5000 × 8 × 3/100 = 1200 টাকা\nমুনাফা-আসল = 6200 টাকা","lv":"মধ্যম","ex":"3.5"},{"n":"b128","q":"বার্ষিক 10% চক্রবৃদ্ধি মুনাফায় 10000 টাকার 2 বছরের চক্রবৃদ্ধি মূলধন ও চক্রবৃদ্ধি মুনাফা নির্ণয় কর।","a":"মূলধন = 10000(1 + 0.1)² = 12100 টাকা\nমুনাফা = 2100 টাকা","lv":"মধ্যম","ex":"3.5"},{"n":"b129","q":"বার্ষিক 5% হারে 8000 টাকার 2 বছরের চক্রবৃদ্ধি মুনাফা ও সরল মুনাফার পার্থক্য নির্ণয় কর।","a":"সরল মুনাফা = 800 টাকা\nচক্রবৃদ্ধি মুনাফা = 8000(1.05)² − 8000 = 820 টাকা\nপার্থক্য = 20 টাকা","lv":"কঠিন","ex":"3.5"},{"n":"b130","q":"একটি দ্রব্য 450 টাকায় বিক্রয় করলে 10% ক্ষতি হয়। 10% লাভ করতে হলে দ্রব্যটি কত টাকায় বিক্রয় করতে হবে?","a":"ক্রয়মূল্য = 450/0.9 = 500 টাকা\n10% লাভে বিক্রয়মূল্য = 550 টাকা","lv":"মধ্যম","ex":"3.5"},{"n":"b131","q":"80 টাকায় ক্রয় করা একটি দ্রব্য 100 টাকায় বিক্রয় করলে শতকরা কত লাভ হয়?","a":"লাভ = 20 টাকা\nশতকরা লাভ = 20/80 × 100 = 25%","lv":"মধ্যম","ex":"3.5"},{"n":"b132","q":"100 টাকায় 12টি কলম কিনে 100 টাকায় 10টি করে বিক্রয় করলে শতকরা কত লাভ হবে?","a":"1টির ক্রয়মূল্য = 25/3 টাকা, বিক্রয়মূল্য = 10 টাকা\nলাভ% = (10 − 25/3)/(25/3) × 100 = 20%","lv":"কঠিন","ex":"3.5"},{"n":"b133","q":"20 জন শ্রমিক একটি কাজ 15 দিনে করে। 25 জন শ্রমিক কাজটি কত দিনে করবে?","a":"মোট কাজ = 20 × 15 = 300 শ্রমিক-দিন\n25 জনে লাগবে 300/25 = 12 দিন","lv":"মধ্যম","ex":"3.5"},{"n":"b134","q":"বার্ষিক 4.5% সরল মুনাফায় কত টাকা 3 বছরে মুনাফা-আসলে 1362 টাকা হবে?","a":"1 টাকা 3 বছরে হয় 1 + 0.135 = 1.135 টাকা\nআসল = 1362/1.135 = 1200 টাকা","lv":"কঠিন","ex":"3.5"},{"n":"b135","q":"কত হার সরল মুনাফায় 2000 টাকা 4 বছরে মুনাফা-আসলে 2480 টাকা হবে?","a":"মুনাফা = 480 টাকা\nহার = 480 × 100/(2000 × 4) = 6%","lv":"মধ্যম","ex":"3.5"},{"n":"b136","q":"এক ব্যক্তি ঘণ্টায় 4 কিমি বেগে কোনো স্থানে গিয়ে ঘণ্টায় 6 কিমি বেগে ফিরে আসে। তার গড় বেগ নির্ণয় কর।","a":"দূরত্ব d হলে মোট সময় = d/4 + d/6 = 5d/12\nগড় বেগ = 2d ÷ (5d/12) = 24/5 = 4.8 কিমি/ঘণ্টা","lv":"কঠিন","ex":"3.5"},{"n":"b137","q":"কোনো সংখ্যার 25% এর সাথে 10 যোগ করলে সংখ্যাটির 35% পাওয়া যায়। সংখ্যাটি নির্ণয় কর।","a":"0.25x + 10 = 0.35x ⇒ 0.1x = 10 ⇒ x = 100","lv":"মধ্যম","ex":"3.5"},{"n":"b138","q":"পিতার বয়স পুত্রের বয়সের 4 গুণ। 5 বছর পর পিতার বয়স পুত্রের বয়সের 3 গুণ হবে। তাদের বর্তমান বয়স নির্ণয় কর।","a":"পুত্রের বয়স x হলে 4x + 5 = 3(x + 5) ⇒ x = 10\nপুত্র 10 বছর, পিতা 40 বছর","lv":"মধ্যম","ex":"3.5"},{"n":"b139","q":"40 লিটার মিশ্রণে দুধ ও পানির অনুপাত 3 : 1। কত লিটার পানি মেশালে অনুপাত 3 : 2 হবে?","a":"দুধ 30 লি, পানি 10 লি\n3 : 2 হতে পানি দরকার 20 লি ∴ আরও 10 লিটার পানি মেশাতে হবে।","lv":"কঠিন","ex":"3.5"},{"n":"b140","q":"কোনো দ্রব্যের দাম 25% বৃদ্ধি পেলে খরচ অপরিবর্তিত রাখতে ব্যবহার শতকরা কত কমাতে হবে?","a":"নতুন ব্যবহার = 1/1.25 = 0.8 অংশ\n∴ ব্যবহার 20% কমাতে হবে।","lv":"কঠিন","ex":"3.5"},{"n":"b141","q":"চালের দাম 20% কমে যাওয়ায় 400 টাকায় আগের চেয়ে 4 কেজি চাল বেশি পাওয়া যায়। প্রতি কেজি চালের পূর্বের দাম কত ছিল?","a":"পূর্বের দাম p হলে 400/(0.8p) − 400/p = 4 ⇒ 100/p = 4 ⇒ p = 25 টাকা","lv":"কঠিন","ex":"3.5"},{"n":"b142","q":"800 টাকা লিখিত মূল্যের একটি দ্রব্য 10% কমিশনে কিনে 900 টাকায় বিক্রয় করলে শতকরা কত লাভ হবে?","a":"ক্রয়মূল্য = 720 টাকা, লাভ = 180 টাকা\nলাভ% = 180/720 × 100 = 25%","lv":"কঠিন","ex":"3.5"},{"n":"b143","q":"দুইটি নল একটি চৌবাচ্চা যথাক্রমে 20 মিনিট ও 30 মিনিটে পূর্ণ করে। দুইটি একসাথে খুলে দিলে কত সময়ে পূর্ণ হবে?","a":"1 মিনিটে পূর্ণ হয় 1/20 + 1/30 = 1/12 অংশ\n∴ 12 মিনিট","lv":"মধ্যম","ex":"3.5"},{"n":"b144","q":"ক একটি কাজের 1/3 অংশ 5 দিনে করে এবং খ একা পুরো কাজটি 10 দিনে করে। দুজনে একত্রে পুরো কাজটি কত দিনে করবে?","a":"ক একা পুরো কাজ 15 দিনে করে।\nএকত্রে 1 দিনে 1/15 + 1/10 = 1/6 ∴ 6 দিন","lv":"কঠিন","ex":"3.5"},{"n":"b145","q":"বার্ষিক 10% চক্রবৃদ্ধি মুনাফায় 5000 টাকার 3 বছরের চক্রবৃদ্ধি মূলধন নির্ণয় কর।","a":"= 5000(1.1)³ = 5000 × 1.331 = 6655 টাকা","lv":"মধ্যম","ex":"3.5"},{"n":"b146","q":"একটি শহরের বর্তমান জনসংখ্যা 50000 এবং প্রতি বছর 4% হারে বৃদ্ধি পায়। 2 বছর পর জনসংখ্যা কত হবে?","a":"= 50000(1.04)² = 50000 × 1.0816 = 54080 জন","lv":"মধ্যম","ex":"3.5"},{"n":"b147","q":"একটি গাড়ি 300 কিমি পথ অতিক্রম করে। গাড়িটির বেগ ঘণ্টায় 10 কিমি বেশি হলে 1 ঘণ্টা কম সময় লাগত। গাড়িটির বেগ নির্ণয় কর।","a":"300/v − 300/(v + 10) = 1 ⇒ v² + 10v − 3000 = 0\n(v + 60)(v − 50) = 0 ⇒ v = 50 কিমি/ঘণ্টা","lv":"কঠিন","ex":"3.5"},{"n":"b148","q":"ক 5000 টাকা 12 মাসের জন্য এবং খ 6000 টাকা 10 মাসের জন্য বিনিয়োগ করে। মোট লাভ 2200 টাকা হলে কে কত টাকা পাবে?","a":"মূলধন × সময়: 60000 : 60000 = 1 : 1\nপ্রত্যেকে 1100 টাকা পাবে।","lv":"কঠিন","ex":"3.5"},{"n":"b149","q":"বার্ষিক 6% সরল মুনাফায় কোনো আসল কত বছরে দ্বিগুণ হবে?","a":"মুনাফা = আসল ⇒ P × 6 × n/100 = P ⇒ n = 100/6 = 16 2/3 বছর\n= 16 বছর 8 মাস","lv":"কঠিন","ex":"3.5"},{"n":"b150","q":"একটি নৌকা স্রোতের অনুকূলে 24 কিমি 2 ঘণ্টায় এবং প্রতিকূলে একই পথ 3 ঘণ্টায় যায়। নৌকার বেগ ও স্রোতের বেগ নির্ণয় কর।","a":"অনুকূলে 12, প্রতিকূলে 8 কিমি/ঘণ্টা\nনৌকার বেগ = (12 + 8)/2 = 10, স্রোতের বেগ = (12 − 8)/2 = 2 কিমি/ঘণ্টা","lv":"কঠিন","ex":"3.5"}],"4":[{"n":"b1","q":"সরল কর: (2ⁿ⁺⁴ − 4 · 2ⁿ)/(2 · 2ⁿ⁺³)","a":"= 2ⁿ(16 − 4)/(2ⁿ · 16) = 12/16 = 3/4","lv":"মধ্যম","ex":"4.1"},{"n":"b2","q":"সরল কর: (3ⁿ⁺² − 3ⁿ)/(3ⁿ⁺¹ + 3ⁿ)","a":"= 3ⁿ(9 − 1)/{3ⁿ(3 + 1)} = 8/4 = 2","lv":"মধ্যম","ex":"4.1"},{"n":"b3","q":"সমাধান কর: 2ˣ⁺¹ = 32","a":"2ˣ⁺¹ = 2⁵ ⇒ x + 1 = 5 ⇒ x = 4","lv":"মধ্যম","ex":"4.1"},{"n":"b4","q":"সমাধান কর: 3²ˣ⁻¹ = 27","a":"3²ˣ⁻¹ = 3³ ⇒ 2x − 1 = 3 ⇒ x = 2","lv":"মধ্যম","ex":"4.1"},{"n":"b5","q":"সমাধান কর: 4ˣ = 8","a":"2²ˣ = 2³ ⇒ 2x = 3 ⇒ x = 3/2","lv":"মধ্যম","ex":"4.1"},{"n":"b6","q":"সমাধান কর: 9ˣ = 3ˣ⁺²","a":"3²ˣ = 3ˣ⁺² ⇒ 2x = x + 2 ⇒ x = 2","lv":"মধ্যম","ex":"4.1"},{"n":"b7","q":"সমাধান কর: 2ˣ + 2ˣ⁺¹ = 48","a":"2ˣ(1 + 2) = 48 ⇒ 2ˣ = 16 ⇒ x = 4","lv":"কঠিন","ex":"4.1"},{"n":"b8","q":"সমাধান কর: 5ˣ⁺¹ + 5ˣ = 750","a":"5ˣ(5 + 1) = 750 ⇒ 5ˣ = 125 ⇒ x = 3","lv":"কঠিন","ex":"4.1"},{"n":"b9","q":"মান নির্ণয় কর: (27)^(2/3) × (16)^(−3/4)","a":"= (3³)^(2/3) × (2⁴)^(−3/4) = 9 × 1/8 = 9/8","lv":"মধ্যম","ex":"4.1"},{"n":"b10","q":"মান নির্ণয় কর: (64)^(−2/3) ÷ (1/8)^(1/3)","a":"= 1/16 ÷ 1/2 = 1/8","lv":"কঠিন","ex":"4.1"},{"n":"b11","q":"সরল কর: (a^(1/2) · a^(1/3))⁶","a":"= (a^(5/6))⁶ = a⁵","lv":"মধ্যম","ex":"4.1"},{"n":"b12","q":"aˣ = b, bʸ = c এবং cᶻ = a হলে দেখাও যে, xyz = 1","a":"a = cᶻ = (bʸ)ᶻ = b^(yz) = (aˣ)^(yz) = a^(xyz)\n∴ xyz = 1","lv":"কঠিন","ex":"4.1"},{"n":"b13","q":"2ˣ = 3ʸ = 6^(−z) হলে দেখাও যে, 1/x + 1/y + 1/z = 0","a":"ধরি 2ˣ = 3ʸ = 6^(−z) = k ⇒ 2 = k^(1/x), 3 = k^(1/y), 6 = k^(−1/z)\n2 × 3 = 6 ⇒ k^(1/x + 1/y) = k^(−1/z) ⇒ 1/x + 1/y + 1/z = 0","lv":"কঠিন","ex":"4.1"},{"n":"b14","q":"সমাধান কর: 2²ˣ − 5 · 2ˣ + 4 = 0","a":"2ˣ = y ধরলে y² − 5y + 4 = 0 ⇒ y = 1, 4\n∴ x = 0 অথবা x = 2","lv":"কঠিন","ex":"4.1"},{"n":"b15","q":"সমাধান কর: 3²ˣ − 10 · 3ˣ + 9 = 0","a":"3ˣ = y ধরলে y² − 10y + 9 = 0 ⇒ y = 1, 9\n∴ x = 0 অথবা x = 2","lv":"কঠিন","ex":"4.1"},{"n":"b16","q":"সমাধান কর: 4ˣ⁺¹ = 2³ˣ⁻¹","a":"2²ˣ⁺² = 2³ˣ⁻¹ ⇒ 2x + 2 = 3x − 1 ⇒ x = 3","lv":"মধ্যম","ex":"4.1"},{"n":"b17","q":"দেখাও যে, (2ⁿ · 6ⁿ⁺¹)/(3ⁿ · 4ⁿ⁺¹) = 3/2","a":"= 2ⁿ · 2ⁿ⁺¹ · 3ⁿ⁺¹/(3ⁿ · 2²ⁿ⁺²) = 2²ⁿ⁺¹ · 3ⁿ⁺¹/(2²ⁿ⁺² · 3ⁿ) = 3/2","lv":"কঠিন","ex":"4.1"},{"n":"b18","q":"সরল কর: (5ⁿ⁺³ − 6 · 5ⁿ⁺¹)/(9 · 5ⁿ − 2² · 5ⁿ)","a":"= 5ⁿ(125 − 30)/{5ⁿ(9 − 4)} = 95/5 = 19","lv":"কঠিন","ex":"4.1"},{"n":"b19","q":"√(2√(2√2)) কে 2 এর ঘাত আকারে প্রকাশ কর।","a":"√2 = 2^(1/2), 2√2 = 2^(3/2), √(2√2) = 2^(3/4)\n2√(2√2) = 2^(7/4) ⇒ মূল রাশি = 2^(7/8)","lv":"কঠিন","ex":"4.1"},{"n":"b20","q":"x = 2^(1/3) + 2^(−1/3) হলে দেখাও যে, 2x³ − 6x = 5","a":"x³ = 2 + 2⁻¹ + 3 · 2^(1/3) · 2^(−1/3)(2^(1/3) + 2^(−1/3)) = 5/2 + 3x\n∴ 2x³ − 6x = 5","lv":"কঠিন","ex":"4.1"},{"n":"b21","q":"a^(1/2) + a^(−1/2) = 3 হলে a + a⁻¹ এর মান নির্ণয় কর।","a":"বর্গ করে a + 2 + a⁻¹ = 9 ⇒ a + a⁻¹ = 7","lv":"কঠিন","ex":"4.1"},{"n":"b22","q":"3ˣ = 9ʸ এবং 2ˣ⁺ʸ = 64 হলে x ও y এর মান নির্ণয় কর।","a":"3ˣ = 3²ʸ ⇒ x = 2y; x + y = 6 ⇒ 3y = 6\n∴ y = 2, x = 4","lv":"কঠিন","ex":"4.1"},{"n":"b23","q":"সমাধান কর: (1/2)ˣ⁻¹ = 16","a":"2^(1 − x) = 2⁴ ⇒ 1 − x = 4 ⇒ x = −3","lv":"মধ্যম","ex":"4.1"},{"n":"b24","q":"সরল কর: (xᵃ⁺ᵇ)ᵃ⁻ᵇ · (xᵇ⁺ᶜ)ᵇ⁻ᶜ · (xᶜ⁺ᵃ)ᶜ⁻ᵃ","a":"= x^(a² − b² + b² − c² + c² − a²) = x⁰ = 1","lv":"কঠিন","ex":"4.1"},{"n":"b25","q":"মান নির্ণয় কর: (0.008)^(−2/3)","a":"0.008 = (0.2)³ ⇒ (0.2)⁻² = 1/0.04 = 25","lv":"কঠিন","ex":"4.1"},{"n":"b26","q":"প্রমাণ কর যে, 1/(1 + aʸ⁻ˣ + aᶻ⁻ˣ) + 1/(1 + aˣ⁻ʸ + aᶻ⁻ʸ) + 1/(1 + aˣ⁻ᶻ + aʸ⁻ᶻ) = 1","a":"প্রথম ভগ্নাংশের লব-হরকে aˣ, দ্বিতীয়টিকে aʸ, তৃতীয়টিকে aᶻ দিয়ে গুণ করলে\n= aˣ/(aˣ + aʸ + aᶻ) + aʸ/(aˣ + aʸ + aᶻ) + aᶻ/(aˣ + aʸ + aᶻ) = 1","lv":"কঠিন","ex":"4.1"},{"n":"b27","q":"a = 2 এবং b = 3 হলে (aᵇ · bᵃ)/(aᵃ · bᵇ) এর মান নির্ণয় কর।","a":"= (8 × 9)/(4 × 27) = 72/108 = 2/3","lv":"মধ্যম","ex":"4.1"},{"n":"b28","q":"সমাধান কর: 2ˣ⁺³ + 2ˣ⁺¹ = 320","a":"2ˣ(8 + 2) = 320 ⇒ 2ˣ = 32 ⇒ x = 5","lv":"কঠিন","ex":"4.1"},{"n":"b29","q":"মান নির্ণয় কর: (81)^0.25 × (81)^0.5","a":"= 81^0.75 = (3⁴)^(3/4) = 27","lv":"মধ্যম","ex":"4.1"},{"n":"b30","q":"সরল কর: (aᵐ/aⁿ)ᵐ⁺ⁿ × (aⁿ/aˡ)ⁿ⁺ˡ × (aˡ/aᵐ)ˡ⁺ᵐ","a":"= a^(m² − n²) × a^(n² − l²) × a^(l² − m²) = a⁰ = 1","lv":"কঠিন","ex":"4.1"},{"n":"b31","q":"মান নির্ণয় কর: log₂64 + log₃81","a":"= log₂2⁶ + log₃3⁴ = 6 + 4 = 10","lv":"মধ্যম","ex":"4.2"},{"n":"b32","q":"মান নির্ণয় কর: log_√3 81","a":"81 = 3⁴ = (√3)⁸ ⇒ log_√3 81 = 8","lv":"মধ্যম","ex":"4.2"},{"n":"b33","q":"মান নির্ণয় কর: log₅(1/125)","a":"1/125 = 5⁻³ ⇒ মান = −3","lv":"মধ্যম","ex":"4.2"},{"n":"b34","q":"log_x(1/16) = −2 হলে x এর মান নির্ণয় কর।","a":"x⁻² = 1/16 ⇒ x² = 16 ⇒ x = 4 (ভিত্তি ধনাত্মক)","lv":"মধ্যম","ex":"4.2"},{"n":"b35","q":"log₄x = 3/2 হলে x এর মান নির্ণয় কর।","a":"x = 4^(3/2) = 8","lv":"মধ্যম","ex":"4.2"},{"n":"b36","q":"log_x 324 = 4 হলে x এর মান নির্ণয় কর।","a":"x⁴ = 324 ⇒ x² = 18 ⇒ x = 3√2","lv":"কঠিন","ex":"4.2"},{"n":"b37","q":"log 2 = 0.3010 এবং log 3 = 0.4771 হলে log 12 এর মান নির্ণয় কর।","a":"log 12 = 2 log 2 + log 3 = 0.6020 + 0.4771 = 1.0791","lv":"মধ্যম","ex":"4.2"},{"n":"b38","q":"log 2 = 0.3010 এবং log 3 = 0.4771 হলে log 72 এর মান নির্ণয় কর।","a":"log 72 = 3 log 2 + 2 log 3 = 0.9030 + 0.9542 = 1.8572","lv":"মধ্যম","ex":"4.2"},{"n":"b39","q":"log 2 = 0.3010 এবং log 3 = 0.4771 হলে log 1.5 এর মান নির্ণয় কর।","a":"log 1.5 = log (3/2) = 0.4771 − 0.3010 = 0.1761","lv":"মধ্যম","ex":"4.2"},{"n":"b40","q":"log 2 = 0.3010 হলে log 25 এর মান নির্ণয় কর।","a":"log 25 = 2 log 5 = 2(1 − log 2) = 2 × 0.6990 = 1.3980","lv":"কঠিন","ex":"4.2"},{"n":"b41","q":"সরল কর: log 12 + log 5 − log 6","a":"= log (12 × 5/6) = log 10 = 1","lv":"মধ্যম","ex":"4.2"},{"n":"b42","q":"সরল কর: 2 log 5 + log 36 − log 9","a":"= log (25 × 36/9) = log 100 = 2","lv":"মধ্যম","ex":"4.2"},{"n":"b43","q":"দেখাও যে, log (1 + 2 + 3) = log 1 + log 2 + log 3","a":"বামপক্ষ = log 6\nডানপক্ষ = log (1 × 2 × 3) = log 6 ∴ সমান।","lv":"মধ্যম","ex":"4.2"},{"n":"b44","q":"মান নির্ণয় কর: log₂ log₂ log₂ 16","a":"log₂16 = 4, log₂4 = 2, log₂2 = 1\n∴ মান = 1","lv":"কঠিন","ex":"4.2"},{"n":"b45","q":"মান নির্ণয় কর: log₃5 × log₅9","a":"= log₃9 (ভিত্তি পরিবর্তন সূত্র) = 2","lv":"কঠিন","ex":"4.2"},{"n":"b46","q":"প্রমাণ কর যে, logₐb × log_bc × log_ca = 1","a":"ভিত্তি পরিবর্তন করে = (log b/log a)(log c/log b)(log a/log c) = 1","lv":"কঠিন","ex":"4.2"},{"n":"b47","q":"log x = 2 log 3 + 3 log 2 − log 6 হলে x এর মান নির্ণয় কর।","a":"log x = log (9 × 8/6) = log 12 ⇒ x = 12","lv":"মধ্যম","ex":"4.2"},{"n":"b48","q":"সমাধান কর: log₂(x + 3) = 4","a":"x + 3 = 2⁴ = 16 ⇒ x = 13","lv":"মধ্যম","ex":"4.2"},{"n":"b49","q":"সমাধান কর: log (x² − 15) = 1","a":"x² − 15 = 10 ⇒ x² = 25 ⇒ x = ±5","lv":"কঠিন","ex":"4.2"},{"n":"b50","q":"সমাধান কর: log₃(2x + 1) = 2","a":"2x + 1 = 9 ⇒ x = 4","lv":"মধ্যম","ex":"4.2"},{"n":"b51","q":"মান নির্ণয় কর: logₐ√(a√(a√a))","a":"√(a√(a√a)) = a^(7/8) ⇒ মান = 7/8","lv":"কঠিন","ex":"4.2"},{"n":"b52","q":"log 2 = 0.3010 হলে 2³⁰ সংখ্যাটিতে কয়টি অঙ্ক আছে?","a":"log 2³⁰ = 30 × 0.3010 = 9.03, পূর্ণক 9\n∴ অঙ্ক সংখ্যা = 9 + 1 = 10","lv":"কঠিন","ex":"4.2"},{"n":"b53","q":"log 0.00456 এর পূর্ণক নির্ণয় কর।","a":"0.00456 = 4.56 × 10⁻³\nপূর্ণক = −3 (অর্থাৎ 3̄)","lv":"মধ্যম","ex":"4.2"},{"n":"b54","q":"log 4567.8 এর পূর্ণক নির্ণয় কর।","a":"4567.8 = 4.5678 × 10³ ⇒ পূর্ণক = 3","lv":"মধ্যম","ex":"4.2"},{"n":"b55","q":"log x = 2.5 হলে x এর মান নির্ণয় কর।","a":"x = 10^2.5 = 10² × √10 = 100√10 ≈ 316.2","lv":"কঠিন","ex":"4.2"},{"n":"b56","q":"সমাধান কর: log₄x + log₄(x − 6) = 2","a":"x(x − 6) = 16 ⇒ x² − 6x − 16 = 0 ⇒ x = 8, −2\nলগারিদম সংজ্ঞায়িত হতে x > 6 ∴ x = 8","lv":"কঠিন","ex":"4.2"},{"n":"b57","q":"প্রমাণ কর যে, log_b a = 1/logₐb","a":"log_b a = log a/log b এবং logₐb = log b/log a\n∴ log_b a × logₐb = 1","lv":"মধ্যম","ex":"4.2"},{"n":"b58","q":"log_k 25 = 2/3 হলে k এর মান নির্ণয় কর।","a":"k^(2/3) = 25 ⇒ k = 25^(3/2) = 125","lv":"কঠিন","ex":"4.2"},{"n":"b59","q":"log a = p এবং log b = q হলে log (a²√b/10) কে p ও q এর মাধ্যমে প্রকাশ কর।","a":"= 2 log a + (1/2) log b − log 10 = 2p + q/2 − 1","lv":"কঠিন","ex":"4.2"},{"n":"b60","q":"log 3 = 0.4771 হলে log 0.009 এর মান নির্ণয় কর।","a":"log 0.009 = log (9 × 10⁻³) = 2 × 0.4771 − 3 = −2.0458 (= 3̄.9542)","lv":"কঠিন","ex":"4.2"},{"n":"b61","q":"0.000345 কে বৈজ্ঞানিক আকারে প্রকাশ কর।","a":"0.000345 = 3.45 × 10⁻⁴","lv":"মধ্যম","ex":"4.3"},{"n":"b62","q":"6,02,000 কে বৈজ্ঞানিক আকারে প্রকাশ কর।","a":"602000 = 6.02 × 10⁵","lv":"মধ্যম","ex":"4.3"},{"n":"b63","q":"(2.5 × 10⁴) × (4 × 10⁻⁷) এর মান বৈজ্ঞানিক আকারে লেখ।","a":"= 10 × 10⁻³ = 1 × 10⁻²","lv":"মধ্যম","ex":"4.3"},{"n":"b64","q":"(9 × 10⁸) ÷ (3 × 10⁻²) এর মান বৈজ্ঞানিক আকারে লেখ।","a":"= 3 × 10⁸⁺² = 3 × 10¹⁰","lv":"মধ্যম","ex":"4.3"},{"n":"b65","q":"সূর্য থেকে পৃথিবীর দূরত্ব 1.5 × 10⁸ কিমি এবং আলোর বেগ 3 × 10⁵ কিমি/সেকেন্ড। সূর্য থেকে আলো পৃথিবীতে আসতে কত সময় লাগে?","a":"সময় = (1.5 × 10⁸)/(3 × 10⁵) = 0.5 × 10³ = 500 সেকেন্ড = 8 মিনিট 20 সেকেন্ড","lv":"কঠিন","ex":"4.3"},{"n":"b66","q":"(3.2 × 10⁵) + (4.8 × 10⁴) এর মান বৈজ্ঞানিক আকারে লেখ।","a":"= 3.2 × 10⁵ + 0.48 × 10⁵ = 3.68 × 10⁵","lv":"কঠিন","ex":"4.3"},{"n":"b67","q":"(6 × 10⁻³)² এর মান বৈজ্ঞানিক আকারে লেখ।","a":"= 36 × 10⁻⁶ = 3.6 × 10⁻⁵","lv":"মধ্যম","ex":"4.3"},{"n":"b68","q":"√(1.6 × 10⁹) এর মান বৈজ্ঞানিক আকারে লেখ।","a":"= √(16 × 10⁸) = 4 × 10⁴","lv":"কঠিন","ex":"4.3"},{"n":"b69","q":"log 2 = 0.3010 হলে log 0.002 এর মান নির্ণয় কর।","a":"log 0.002 = log 2 − 3 = −2.6990 (= 3̄.3010)","lv":"মধ্যম","ex":"4.3"},{"n":"b70","q":"log 3.456 = 0.5386 হলে log 345.6 এবং log 0.03456 নির্ণয় কর।","a":"log 345.6 = 2 + 0.5386 = 2.5386\nlog 0.03456 = −2 + 0.5386 = 2̄.5386","lv":"কঠিন","ex":"4.3"},{"n":"b71","q":"log x = 3.4771 এবং log 3 = 0.4771 হলে x এর মান নির্ণয় কর।","a":"log x = 3 + log 3 = log 3000 ⇒ x = 3000","lv":"মধ্যম","ex":"4.3"},{"n":"b72","q":"log x = 2̄.3010 এবং log 2 = 0.3010 হলে x এর মান নির্ণয় কর।","a":"log x = −2 + log 2 = log (2 × 10⁻²) ⇒ x = 0.02","lv":"কঠিন","ex":"4.3"},{"n":"b73","q":"একটি পরমাণুর ব্যাস 1 × 10⁻¹⁰ মিটার এবং নিউক্লিয়াসের ব্যাস 1 × 10⁻¹⁵ মিটার। পরমাণুর ব্যাস নিউক্লিয়াসের ব্যাসের কত গুণ?","a":"= 10⁻¹⁰/10⁻¹⁵ = 10⁵ গুণ","lv":"মধ্যম","ex":"4.3"},{"n":"b74","q":"(1.2 × 10⁻³) × (5 × 10⁶) এর মান বৈজ্ঞানিক আকারে লেখ।","a":"= 6 × 10³","lv":"মধ্যম","ex":"4.3"},{"n":"b75","q":"0.0000000072 কে বৈজ্ঞানিক আকারে প্রকাশ কর।","a":"= 7.2 × 10⁻⁹","lv":"মধ্যম","ex":"4.3"},{"n":"b76","q":"4.5 × 10⁻³ কে সাধারণ দশমিক আকারে লেখ।","a":"= 0.0045","lv":"মধ্যম","ex":"4.3"},{"n":"b77","q":"log 3 = 0.4771 হলে 3²⁰ সংখ্যাটিতে কয়টি অঙ্ক আছে?","a":"log 3²⁰ = 20 × 0.4771 = 9.542, পূর্ণক 9\n∴ অঙ্ক সংখ্যা = 10","lv":"কঠিন","ex":"4.3"},{"n":"b78","q":"log 2 = 0.3010 হলে 5²⁵ সংখ্যাটিতে কয়টি অঙ্ক আছে?","a":"log 5 = 1 − 0.3010 = 0.6990\nlog 5²⁵ = 17.475 ⇒ অঙ্ক সংখ্যা = 18","lv":"কঠিন","ex":"4.3"},{"n":"b79","q":"log 2 = 0.3010 হলে 2⁶⁴ সংখ্যাটিতে কয়টি অঙ্ক আছে?","a":"log 2⁶⁴ = 64 × 0.3010 = 19.264 ⇒ অঙ্ক সংখ্যা = 20","lv":"কঠিন","ex":"4.3"},{"n":"b80","q":"log 2 = 0.3010 হলে n এর ক্ষুদ্রতম কোন স্বাভাবিক মানের জন্য 2ⁿ > 10⁶ হবে?","a":"n log 2 > 6 ⇒ n > 6/0.3010 = 19.93\n∴ n = 20","lv":"কঠিন","ex":"4.3"},{"n":"b81","q":"(8 × 10⁻⁴) ÷ (2 × 10⁻⁷) এর মান বৈজ্ঞানিক আকারে লেখ।","a":"= 4 × 10³","lv":"মধ্যম","ex":"4.3"},{"n":"b82","q":"একটি ব্যাকটেরিয়া কলোনিতে 1000টি ব্যাকটেরিয়া আছে এবং প্রতি ঘণ্টায় সংখ্যা দ্বিগুণ হয়। 10 ঘণ্টা পর সংখ্যা বৈজ্ঞানিক আকারে কত হবে?","a":"= 1000 × 2¹⁰ = 1024000 = 1.024 × 10⁶","lv":"কঠিন","ex":"4.3"},{"n":"b83","q":"আলোর বেগ 3 × 10⁸ মিটার/সেকেন্ড। আলো 1 মিনিটে কত মিটার যায়? বৈজ্ঞানিক আকারে লেখ।","a":"= 3 × 10⁸ × 60 = 1.8 × 10¹⁰ মিটার","lv":"মধ্যম","ex":"4.3"},{"n":"b84","q":"পৃথিবীর ভর 6 × 10²⁴ কেজি এবং চাঁদের ভর 7.5 × 10²² কেজি। পৃথিবীর ভর চাঁদের ভরের কত গুণ?","a":"= (6 × 10²⁴)/(7.5 × 10²²) = 0.8 × 10² = 80 গুণ","lv":"কঠিন","ex":"4.3"},{"n":"b85","q":"log 2 = 0.3010 হলে log (2 × 10⁵) এর মান নির্ণয় কর।","a":"= 5 + 0.3010 = 5.3010","lv":"মধ্যম","ex":"4.3"},{"n":"b86","q":"log 2 = 0.3010 হলে log 5 ও log 0.5 এর মান নির্ণয় কর।","a":"log 5 = 1 − 0.3010 = 0.6990\nlog 0.5 = −0.3010 (= 1̄.6990)","lv":"মধ্যম","ex":"4.3"},{"n":"b87","q":"log 7 = 0.8451 হলে log 4.9 এর মান নির্ণয় কর।","a":"log 4.9 = log (49/10) = 2 × 0.8451 − 1 = 0.6902","lv":"কঠিন","ex":"4.3"},{"n":"b88","q":"log 2 = 0.3010 হলে log √0.0016 এর মান নির্ণয় কর।","a":"√0.0016 = 0.04 ⇒ log 0.04 = 2 log 2 − 2 = −1.3980 (= 2̄.6020)","lv":"কঠিন","ex":"4.3"},{"n":"b89","q":"একটি শহরের জনসংখ্যা 8.2 × 10⁶ থেকে বেড়ে 1.64 × 10⁷ হলো। জনসংখ্যা কত গুণ হলো?","a":"= (1.64 × 10⁷)/(8.2 × 10⁶) = 0.2 × 10 = 2 গুণ","lv":"মধ্যম","ex":"4.3"},{"n":"b90","q":"log 54.3 এর পূর্ণক নির্ণয় কর এবং 54.3 কে বৈজ্ঞানিক আকারে লেখ।","a":"54.3 = 5.43 × 10¹ ⇒ পূর্ণক = 1","lv":"মধ্যম","ex":"4.3"}],"5":[{"n":"b1","q":"সমাধান কর: (x − 3)/2 + (x + 1)/3 = 3","a":"6 দিয়ে গুণ করে 3x − 9 + 2x + 2 = 18 ⇒ 5x = 25 ⇒ x = 5","lv":"মধ্যম","ex":"5.1"},{"n":"b2","q":"সমাধান কর: 3/(x + 1) = 2/(x − 1)","a":"3(x − 1) = 2(x + 1) ⇒ 3x − 3 = 2x + 2 ⇒ x = 5","lv":"মধ্যম","ex":"5.1"},{"n":"b3","q":"সমাধান কর: (x + 3)/(x − 3) = (x + 5)/(x − 1)","a":"(x + 3)(x − 1) = (x + 5)(x − 3) ⇒ x² + 2x − 3 = x² + 2x − 15 ⇒ −3 = −15, যা অসম্ভব\n∴ সমীকরণের কোনো সমাধান নেই।","lv":"কঠিন","ex":"5.1"},{"n":"b4","q":"সমাধান কর: 1/(x − 2) + 1/(x − 3) = 2/(x − 4)","a":"(2x − 5)(x − 4) = 2(x − 2)(x − 3) ⇒ 2x² − 13x + 20 = 2x² − 10x + 12 ⇒ −3x = −8\n∴ x = 8/3","lv":"কঠিন","ex":"5.1"},{"n":"b5","q":"সমাধান কর: ax + b = cx + d (a ≠ c)","a":"(a − c)x = d − b ⇒ x = (d − b)/(a − c)","lv":"মধ্যম","ex":"5.1"},{"n":"b6","q":"সমাধান কর: (x − a)/b + (x − b)/a = 2","a":"a(x − a) + b(x − b) = 2ab ⇒ (a + b)x = a² + 2ab + b² = (a + b)²\n∴ x = a + b","lv":"কঠিন","ex":"5.1"},{"n":"b7","q":"মা ও মেয়ের বয়সের সমষ্টি 50 বছর। 5 বছর আগে মায়ের বয়স মেয়ের বয়সের 7 গুণ ছিল। তাদের বর্তমান বয়স নির্ণয় কর।","a":"মেয়ের বয়স x হলে (50 − x) − 5 = 7(x − 5) ⇒ 45 − x = 7x − 35 ⇒ x = 10\nমেয়ে 10 বছর, মা 40 বছর","lv":"কঠিন","ex":"5.1"},{"n":"b8","q":"দুই অঙ্কবিশিষ্ট একটি সংখ্যার অঙ্কদ্বয়ের সমষ্টি 9। অঙ্কদ্বয় স্থান বিনিময় করলে সংখ্যাটি 27 বেড়ে যায়। সংখ্যাটি নির্ণয় কর।","a":"দশক অঙ্ক x হলে একক 9 − x\n10(9 − x) + x − {10x + 9 − x} = 27 ⇒ 81 − 18x = 27 ⇒ x = 3\nসংখ্যা = 36","lv":"কঠিন","ex":"5.1"},{"n":"b9","q":"একটি ভগ্নাংশের লব হর অপেক্ষা 3 কম। লব ও হর উভয়ের সাথে 2 যোগ করলে ভগ্নাংশটি 4/5 হয়। ভগ্নাংশটি নির্ণয় কর।","a":"হর x হলে (x − 1)/(x + 2) = 4/5 ⇒ 5x − 5 = 4x + 8 ⇒ x = 13\nভগ্নাংশ = 10/13","lv":"কঠিন","ex":"5.1"},{"n":"b10","q":"একটি আয়তক্ষেত্রের দৈর্ঘ্য প্রস্থ অপেক্ষা 4 মিটার বেশি এবং পরিসীমা 56 মিটার। ক্ষেত্রফল নির্ণয় কর।","a":"2(x + 4 + x) = 56 ⇒ x = 12\nদৈর্ঘ্য 16 মি, প্রস্থ 12 মি, ক্ষেত্রফল = 192 বর্গমিটার","lv":"মধ্যম","ex":"5.1"},{"n":"b11","q":"তিনটি ক্রমিক বিজোড় সংখ্যার যোগফল 87। সংখ্যাগুলো নির্ণয় কর।","a":"x + (x + 2) + (x + 4) = 87 ⇒ 3x = 81 ⇒ x = 27\nসংখ্যাগুলো 27, 29, 31","lv":"মধ্যম","ex":"5.1"},{"n":"b12","q":"2 টাকা ও 5 টাকার মোট 50টি মুদ্রায় 160 টাকা আছে। কোন প্রকারের মুদ্রা কয়টি?","a":"5 টাকার মুদ্রা x হলে 2(50 − x) + 5x = 160 ⇒ 3x = 60 ⇒ x = 20\n5 টাকার 20টি, 2 টাকার 30টি","lv":"কঠিন","ex":"5.1"},{"n":"b13","q":"একটি গাড়ি প্রথম 2 ঘণ্টা কোনো বেগে এবং পরবর্তী 3 ঘণ্টা ঘণ্টায় 10 কিমি বেশি বেগে চলে মোট 280 কিমি যায়। প্রথম বেগ নির্ণয় কর।","a":"2v + 3(v + 10) = 280 ⇒ 5v = 250 ⇒ v = 50 কিমি/ঘণ্টা","lv":"মধ্যম","ex":"5.1"},{"n":"b14","q":"সমাধান কর: 0.5x + 0.25(x − 4) = 5","a":"0.75x − 1 = 5 ⇒ 0.75x = 6 ⇒ x = 8","lv":"মধ্যম","ex":"5.1"},{"n":"b15","q":"সমাধান কর: (2x + 1)/(3x − 2) = 5/9","a":"9(2x + 1) = 5(3x − 2) ⇒ 18x + 9 = 15x − 10 ⇒ x = −19/3","lv":"মধ্যম","ex":"5.1"},{"n":"b16","q":"সমাধান কর: 5 − (2x − 3)/4 = x","a":"20 − 2x + 3 = 4x ⇒ 6x = 23 ⇒ x = 23/6","lv":"মধ্যম","ex":"5.1"},{"n":"b17","q":"সমাধান কর: x/3 − x/4 = 2","a":"(4x − 3x)/12 = 2 ⇒ x = 24","lv":"মধ্যম","ex":"5.1"},{"n":"b18","q":"এক ব্যক্তি বেতনের 1/3 অংশ বাসাভাড়া ও 1/4 অংশ খাবারে খরচ করে 5000 টাকা জমা রাখেন। তার বেতন কত?","a":"বাকি অংশ = 1 − 1/3 − 1/4 = 5/12\n(5/12)x = 5000 ⇒ x = 12000 টাকা","lv":"মধ্যম","ex":"5.1"},{"n":"b19","q":"1300 টাকা ক, খ ও গ এর মধ্যে এমনভাবে ভাগ করা হলো যে, ক পায় খ এর দ্বিগুণ এবং খ পায় গ এর চেয়ে 100 টাকা বেশি। কে কত পায়?","a":"গ = x, খ = x + 100, ক = 2x + 200\n4x + 300 = 1300 ⇒ x = 250\nক 700, খ 350, গ 250 টাকা","lv":"কঠিন","ex":"5.1"},{"n":"b20","q":"সমাধান কর: (x + 2)/(x − 2) = 3","a":"x + 2 = 3x − 6 ⇒ 2x = 8 ⇒ x = 4","lv":"মধ্যম","ex":"5.1"},{"n":"b21","q":"3x − 7 = 2(x + 1) হলে x² − 1 এর মান নির্ণয় কর।","a":"3x − 7 = 2x + 2 ⇒ x = 9\nx² − 1 = 80","lv":"মধ্যম","ex":"5.1"},{"n":"b22","q":"একটি সংখ্যা তার 2/5 অংশ অপেক্ষা 36 বেশি। সংখ্যাটি নির্ণয় কর।","a":"x − 2x/5 = 36 ⇒ 3x/5 = 36 ⇒ x = 60","lv":"মধ্যম","ex":"5.1"},{"n":"b23","q":"পিতার বয়স পুত্রের বয়সের 3 গুণ। 15 বছর পর পিতার বয়স পুত্রের বয়সের 2 গুণ হবে। তাদের বর্তমান বয়স কত?","a":"3x + 15 = 2(x + 15) ⇒ x = 15\nপুত্র 15 বছর, পিতা 45 বছর","lv":"মধ্যম","ex":"5.1"},{"n":"b24","q":"একজন দোকানদার একটি দ্রব্য 600 টাকায় বিক্রয় করে 20% লাভ করেন। দ্রব্যটির ক্রয়মূল্য কত?","a":"1.2x = 600 ⇒ x = 500 টাকা","lv":"মধ্যম","ex":"5.1"},{"n":"b25","q":"এক ব্যক্তি 20 কিমি পথের কিছু অংশ ঘণ্টায় 5 কিমি বেগে হেঁটে এবং বাকি অংশ ঘণ্টায় 15 কিমি বেগে সাইকেলে মোট 2 ঘণ্টায় অতিক্রম করেন। তিনি কত কিমি হেঁটেছেন?","a":"x/5 + (20 − x)/15 = 2 ⇒ 3x + 20 − x = 30 ⇒ x = 5 কিমি","lv":"কঠিন","ex":"5.1"},{"n":"b26","q":"দুইটি সংখ্যার অন্তর 15 এবং বড় সংখ্যাটি ছোট সংখ্যার 4 গুণ। সংখ্যা দুইটি নির্ণয় কর।","a":"4x − x = 15 ⇒ x = 5\nসংখ্যা দুইটি 5 ও 20","lv":"মধ্যম","ex":"5.1"},{"n":"b27","q":"একটি ত্রিভুজের বাহুগুলো x, x + 3 ও x + 6 সেমি এবং পরিসীমা 45 সেমি। বাহুগুলোর দৈর্ঘ্য নির্ণয় কর।","a":"3x + 9 = 45 ⇒ x = 12\nবাহুগুলো 12, 15, 18 সেমি","lv":"মধ্যম","ex":"5.1"},{"n":"b28","q":"সমাধান কর: (x + 1)/2 + (x + 2)/3 = 16 − (x + 3)/4","a":"12 দিয়ে গুণ করে 6x + 6 + 4x + 8 = 192 − 3x − 9 ⇒ 13x = 169 ⇒ x = 13","lv":"কঠিন","ex":"5.1"},{"n":"b29","q":"সমাধান কর: (x − 1)/(x + 1) + (x + 1)/(x − 1) = 2","a":"{(x − 1)² + (x + 1)²}/(x² − 1) = 2 ⇒ 2x² + 2 = 2x² − 2, যা অসম্ভব\n∴ কোনো সমাধান নেই।","lv":"কঠিন","ex":"5.1"},{"n":"b30","q":"একটি শ্রেণিতে 40 জন শিক্ষার্থী আছে। ছাত্রসংখ্যা ছাত্রীসংখ্যা অপেক্ষা 8 বেশি। ছাত্র ও ছাত্রী কতজন?","a":"ছাত্রী x হলে x + x + 8 = 40 ⇒ x = 16\nছাত্রী 16 জন, ছাত্র 24 জন","lv":"মধ্যম","ex":"5.1"},{"n":"b31","q":"সমাধান কর: x² − 7x + 12 = 0","a":"(x − 3)(x − 4) = 0 ⇒ x = 3, 4","lv":"মধ্যম","ex":"5.2"},{"n":"b32","q":"সমাধান কর: 2x² − 5x − 3 = 0","a":"2x² − 6x + x − 3 = (2x + 1)(x − 3) = 0 ⇒ x = 3, −1/2","lv":"মধ্যম","ex":"5.2"},{"n":"b33","q":"সমাধান কর: 3x² + 5x − 2 = 0","a":"3x² + 6x − x − 2 = (3x − 1)(x + 2) = 0 ⇒ x = 1/3, −2","lv":"মধ্যম","ex":"5.2"},{"n":"b34","q":"সমাধান কর: x² − 2√3x + 3 = 0","a":"(x − √3)² = 0 ⇒ x = √3","lv":"কঠিন","ex":"5.2"},{"n":"b35","q":"সমাধান কর: x(x − 4) = 12","a":"x² − 4x − 12 = 0 ⇒ (x − 6)(x + 2) = 0 ⇒ x = 6, −2","lv":"মধ্যম","ex":"5.2"},{"n":"b36","q":"সমাধান কর: (x + 1)/(x − 1) = (2x + 5)/(x + 2)","a":"(x + 1)(x + 2) = (2x + 5)(x − 1) ⇒ x² + 3x + 2 = 2x² + 3x − 5 ⇒ x² = 7\n∴ x = ±√7","lv":"কঠিন","ex":"5.2"},{"n":"b37","q":"সমাধান কর: x + 1/x = 5/2","a":"2x² − 5x + 2 = 0 ⇒ (2x − 1)(x − 2) = 0 ⇒ x = 2, 1/2","lv":"মধ্যম","ex":"5.2"},{"n":"b38","q":"সমাধান কর এবং শুদ্ধি পরীক্ষা কর: √(2x + 7) = x + 2","a":"বর্গ করে 2x + 7 = x² + 4x + 4 ⇒ x² + 2x − 3 = 0 ⇒ x = 1, −3\nx = −3 এ বামপক্ষ 1, ডানপক্ষ −1 (গ্রহণযোগ্য নয়) ∴ x = 1","lv":"কঠিন","ex":"5.2"},{"n":"b39","q":"সমাধান কর এবং শুদ্ধি পরীক্ষা কর: √(x − 1) + 3 = x","a":"√(x − 1) = x − 3 ⇒ x − 1 = x² − 6x + 9 ⇒ x² − 7x + 10 = 0 ⇒ x = 5, 2\nx = 2 এ 1 + 3 ≠ 2 ∴ x = 5","lv":"কঠিন","ex":"5.2"},{"n":"b40","q":"সমাধান কর: x⁴ − 5x² + 4 = 0","a":"(x² − 1)(x² − 4) = 0 ⇒ x = ±1, ±2","lv":"কঠিন","ex":"5.2"},{"n":"b41","q":"সমাধান কর: (x² − x)² − 8(x² − x) + 12 = 0","a":"x² − x = a ধরলে (a − 2)(a − 6) = 0\nx² − x = 2 ⇒ x = 2, −1; x² − x = 6 ⇒ x = 3, −2","lv":"কঠিন","ex":"5.2"},{"n":"b42","q":"কোনো সংখ্যা ও তার বর্গের যোগফল 72। সংখ্যাটি নির্ণয় কর।","a":"x² + x − 72 = 0 ⇒ (x + 9)(x − 8) = 0 ⇒ x = 8 অথবা −9","lv":"মধ্যম","ex":"5.2"},{"n":"b43","q":"দুইটি ক্রমিক ধনাত্মক পূর্ণসংখ্যার গুণফল 132। সংখ্যা দুইটি নির্ণয় কর।","a":"x(x + 1) = 132 ⇒ x² + x − 132 = 0 ⇒ (x + 12)(x − 11) = 0\nসংখ্যা দুইটি 11 ও 12","lv":"মধ্যম","ex":"5.2"},{"n":"b44","q":"একটি আয়তক্ষেত্রের ক্ষেত্রফল 48 বর্গমিটার এবং পরিসীমা 28 মিটার। দৈর্ঘ্য ও প্রস্থ নির্ণয় কর।","a":"দৈর্ঘ্য + প্রস্থ = 14, দৈর্ঘ্য x হলে x(14 − x) = 48 ⇒ x² − 14x + 48 = 0 ⇒ x = 8, 6\nদৈর্ঘ্য 8 মি, প্রস্থ 6 মি","lv":"কঠিন","ex":"5.2"},{"n":"b45","q":"একটি সমকোণী ত্রিভুজের সমকোণ সংলগ্ন বাহুদ্বয়ের অন্তর 7 সেমি এবং অতিভুজ 13 সেমি। বাহুদ্বয় নির্ণয় কর।","a":"x² + (x + 7)² = 169 ⇒ x² + 7x − 60 = 0 ⇒ x = 5\nবাহুদ্বয় 5 সেমি ও 12 সেমি","lv":"কঠিন","ex":"5.2"},{"n":"b46","q":"কোনো সংখ্যা ও তার গুণাত্মক বিপরীত সংখ্যার যোগফল 10/3। সংখ্যাটি নির্ণয় কর।","a":"x + 1/x = 10/3 ⇒ 3x² − 10x + 3 = 0 ⇒ (3x − 1)(x − 3) = 0 ⇒ x = 3 অথবা 1/3","lv":"মধ্যম","ex":"5.2"},{"n":"b47","q":"দুই অঙ্কের একটি সংখ্যার অঙ্কদ্বয়ের গুণফল 12। সংখ্যাটির সাথে 36 যোগ করলে অঙ্কদ্বয় স্থান বিনিময় করে। সংখ্যাটি নির্ণয় কর।","a":"দশক x, একক y: xy = 12, 10x + y + 36 = 10y + x ⇒ y − x = 4\nx(x + 4) = 12 ⇒ x = 2, y = 6 ∴ সংখ্যা 26","lv":"কঠিন","ex":"5.2"},{"n":"b48","q":"একটি বর্গাকার বাগানের বাইরে চারদিকে 2 মিটার চওড়া রাস্তা আছে। রাস্তার ক্ষেত্রফল 96 বর্গমিটার হলে বাগানের এক বাহুর দৈর্ঘ্য নির্ণয় কর।","a":"(x + 4)² − x² = 96 ⇒ 8x + 16 = 96 ⇒ x = 10 মিটার","lv":"কঠিন","ex":"5.2"},{"n":"b49","q":"একটি ট্রেন 480 কিমি পথ সমবেগে যায়। বেগ ঘণ্টায় 20 কিমি বেশি হলে 2 ঘণ্টা কম লাগত। ট্রেনের বেগ নির্ণয় কর।","a":"480/v − 480/(v + 20) = 2 ⇒ v² + 20v − 4800 = 0 ⇒ (v + 80)(v − 60) = 0\n∴ v = 60 কিমি/ঘণ্টা","lv":"কঠিন","ex":"5.2"},{"n":"b50","q":"দুইটি ক্রমিক ধনাত্মক বিজোড় সংখ্যার বর্গের সমষ্টি 202। সংখ্যা দুইটি নির্ণয় কর।","a":"x² + (x + 2)² = 202 ⇒ x² + 2x − 99 = 0 ⇒ (x + 11)(x − 9) = 0\nসংখ্যা দুইটি 9 ও 11","lv":"কঠিন","ex":"5.2"},{"n":"b51","q":"x² − kx + 9 = 0 সমীকরণের মূলদ্বয় সমান হলে k এর মান নির্ণয় কর।","a":"মূলদ্বয় সমান হলে নিশ্চায়ক k² − 36 = 0 ⇒ k = ±6","lv":"কঠিন","ex":"5.2"},{"n":"b52","q":"যে দ্বিঘাত সমীকরণের মূলদ্বয় 2 ও −5 তা নির্ণয় কর।","a":"(x − 2)(x + 5) = 0 ⇒ x² + 3x − 10 = 0","lv":"মধ্যম","ex":"5.2"},{"n":"b53","q":"সূত্রের সাহায্যে সমাধান কর: x² − 4x + 1 = 0","a":"x = {4 ± √(16 − 4)}/2 = 2 ± √3","lv":"কঠিন","ex":"5.2"},{"n":"b54","q":"সমাধান কর: 3x² − 2x − 1 = 0","a":"(3x + 1)(x − 1) = 0 ⇒ x = 1, −1/3","lv":"মধ্যম","ex":"5.2"},{"n":"b55","q":"সমাধান কর: (x − 3)² = 2(x − 3)","a":"(x − 3)(x − 3 − 2) = 0 ⇒ x = 3, 5","lv":"মধ্যম","ex":"5.2"},{"n":"b56","q":"সমাধান কর: 1/(x − 1) − 1/(x + 2) = 3/4","a":"3/{(x − 1)(x + 2)} = 3/4 ⇒ x² + x − 2 = 4 ⇒ x² + x − 6 = 0 ⇒ x = 2, −3","lv":"কঠিন","ex":"5.2"},{"n":"b57","q":"পিতা পুত্রের চেয়ে 30 বছরের বড় এবং পুত্রের বয়সের বর্গ পিতার বয়সের সমান। তাদের বয়স নির্ণয় কর।","a":"x² = x + 30 ⇒ (x − 6)(x + 5) = 0 ⇒ x = 6\nপুত্র 6 বছর, পিতা 36 বছর","lv":"কঠিন","ex":"5.2"},{"n":"b58","q":"কিছু শিক্ষার্থী 600 টাকা সমানভাবে ভাগ করে নেয়। 5 জন কম হলে প্রত্যেকে 4 টাকা বেশি পেত। শিক্ষার্থীর সংখ্যা নির্ণয় কর।","a":"600/(n − 5) − 600/n = 4 ⇒ n² − 5n − 750 = 0 ⇒ (n − 30)(n + 25) = 0\n∴ n = 30 জন","lv":"কঠিন","ex":"5.2"},{"n":"b59","q":"সমাধান কর: x² − 6x + 9 = 4","a":"(x − 3)² = 4 ⇒ x − 3 = ±2 ⇒ x = 5, 1","lv":"মধ্যম","ex":"5.2"},{"n":"b60","q":"সমাধান কর: (x + 3)(x − 3) = 40","a":"x² − 9 = 40 ⇒ x² = 49 ⇒ x = ±7","lv":"মধ্যম","ex":"5.2"}],"6":[{"n":"b1","q":"দুইটি সম্পূরক কোণের একটি অপরটির 4 গুণ অপেক্ষা 10° কম। কোণ দুইটি নির্ণয় কর।","a":"x + (4x − 10°) = 180° ⇒ x = 38°\nকোণ দুইটি 38° ও 142°","lv":"মধ্যম","ex":"6.1"},{"n":"b2","q":"কোনো কোণের পূরক কোণ তার সম্পূরক কোণের এক-চতুর্থাংশ। কোণটি নির্ণয় কর।","a":"90° − x = (180° − x)/4 ⇒ 360° − 4x = 180° − x ⇒ x = 60°","lv":"কঠিন","ex":"6.1"},{"n":"b3","q":"দুইটি পূরক কোণের অনুপাত 2 : 3। কোণ দুইটি নির্ণয় কর।","a":"2k + 3k = 90° ⇒ k = 18°\nকোণ দুইটি 36° ও 54°","lv":"মধ্যম","ex":"6.1"},{"n":"b4","q":"একটি বিন্দুতে উৎপন্ন চারটি কোণ x, 2x, 3x ও 4x। কোণগুলো নির্ণয় কর।","a":"10x = 360° ⇒ x = 36°\nকোণগুলো 36°, 72°, 108°, 144°","lv":"মধ্যম","ex":"6.1"},{"n":"b5","q":"দুইটি সরলরেখা পরস্পর ছেদ করায় উৎপন্ন দুইটি বিপ্রতীপ কোণ (3x + 10)° ও (5x − 30)°। x এর মান এবং কোণ চারটি নির্ণয় কর।","a":"বিপ্রতীপ কোণ সমান ⇒ 3x + 10 = 5x − 30 ⇒ x = 20\nকোণগুলো 70°, 110°, 70°, 110°","lv":"কঠিন","ex":"6.1"},{"n":"b6","q":"দুইটি সমান্তরাল রেখাকে একটি ছেদক ছেদ করায় একান্তর কোণদ্বয় (2x + 15)° ও (3x − 5)°। কোণটির মান নির্ণয় কর।","a":"একান্তর কোণ সমান ⇒ 2x + 15 = 3x − 5 ⇒ x = 20\nকোণ = 55°","lv":"মধ্যম","ex":"6.1"},{"n":"b7","q":"দুইটি সমান্তরাল রেখাকে একটি ছেদক ছেদ করায় ছেদকের একই পাশের অন্তঃস্থ কোণদ্বয় (3x + 20)° ও (2x + 10)°। কোণদ্বয় নির্ণয় কর।","a":"একই পাশের অন্তঃস্থ কোণদ্বয় সম্পূরক ⇒ 5x + 30 = 180 ⇒ x = 30\nকোণদ্বয় 110° ও 70°","lv":"মধ্যম","ex":"6.1"},{"n":"b8","q":"দুইটি সমান্তরাল রেখার অনুরূপ কোণদ্বয় (5x − 20)° ও (3x + 30)°। কোণটির মান নির্ণয় কর।","a":"অনুরূপ কোণ সমান ⇒ 5x − 20 = 3x + 30 ⇒ x = 25\nকোণ = 105°","lv":"মধ্যম","ex":"6.1"},{"n":"b9","q":"প্রমাণ কর যে, দুইটি সরলরেখা পরস্পর ছেদ করলে উৎপন্ন বিপ্রতীপ কোণদ্বয় সমান।","a":"AB ও CD রেখা O তে ছেদ করে। ∠AOC + ∠AOD = 180° এবং ∠AOD + ∠BOD = 180° (সরলকোণ)\n∴ ∠AOC = ∠BOD। একইভাবে ∠AOD = ∠BOC","lv":"মধ্যম","ex":"6.1"},{"n":"b10","q":"AB ∥ CD এবং ছেদক EF এদের যথাক্রমে G ও H বিন্দুতে ছেদ করে। ∠AGH = 65° হলে ∠GHD ও ∠GHC নির্ণয় কর।","a":"∠GHD = ∠AGH = 65° (একান্তর)\n∠GHC = 180° − 65° = 115°","lv":"মধ্যম","ex":"6.1"},{"n":"b11","q":"প্রমাণ কর যে, দুইটি সন্নিহিত সম্পূরক কোণের সমদ্বিখণ্ডকদ্বয় পরস্পর লম্ব।","a":"কোণদ্বয় x ও y হলে x + y = 180°\nসমদ্বিখণ্ডকদ্বয়ের অন্তর্ভুক্ত কোণ = x/2 + y/2 = 90° ∴ পরস্পর লম্ব।","lv":"কঠিন","ex":"6.1"},{"n":"b12","q":"কোনো কোণ তার পূরক কোণের সমান হলে কোণটি নির্ণয় কর।","a":"x = 90° − x ⇒ x = 45°","lv":"মধ্যম","ex":"6.1"},{"n":"b13","q":"কোনো কোণ তার সম্পূরক কোণ অপেক্ষা 30° বড়। কোণটি নির্ণয় কর।","a":"x − (180° − x) = 30° ⇒ 2x = 210° ⇒ x = 105°","lv":"মধ্যম","ex":"6.1"},{"n":"b14","q":"37°24′ কোণের পূরক কোণ নির্ণয় কর।","a":"90° − 37°24′ = 89°60′ − 37°24′ = 52°36′","lv":"মধ্যম","ex":"6.1"},{"n":"b15","q":"112°45′ কোণের সম্পূরক কোণ নির্ণয় কর।","a":"180° − 112°45′ = 179°60′ − 112°45′ = 67°15′","lv":"মধ্যম","ex":"6.1"},{"n":"b16","q":"ঘড়িতে যখন 4টা বেজে 20 মিনিট, তখন ঘণ্টার কাঁটা ও মিনিটের কাঁটার মধ্যবর্তী কোণ কত?","a":"ঘণ্টার কাঁটা = 4 × 30° + 20 × 0.5° = 130°, মিনিটের কাঁটা = 20 × 6° = 120°\nকোণ = 10°","lv":"কঠিন","ex":"6.1"},{"n":"b17","q":"ঘড়িতে যখন 2টা 30 মিনিট, তখন কাঁটা দুইটির মধ্যবর্তী কোণ কত?","a":"ঘণ্টার কাঁটা = 60° + 15° = 75°, মিনিটের কাঁটা = 180°\nকোণ = 105°","lv":"কঠিন","ex":"6.1"},{"n":"b18","q":"দুইটি সরলরেখা পরস্পর ছেদ করায় উৎপন্ন একটি কোণ 48°। অপর কোণ তিনটি নির্ণয় কর।","a":"বিপ্রতীপ কোণ 48°, সন্নিহিত কোণদ্বয় 180° − 48° = 132°\nকোণগুলো 132°, 48°, 132°","lv":"মধ্যম","ex":"6.1"},{"n":"b19","q":"একটি বিন্দুতে উৎপন্ন তিনটি কোণ x, (2x + 10)° ও (3x − 10)°। কোণগুলো নির্ণয় কর।","a":"6x = 360° ⇒ x = 60°\nকোণগুলো 60°, 130°, 170°","lv":"মধ্যম","ex":"6.1"},{"n":"b20","q":"একটি সরলরেখার একই পাশে একই বিন্দুতে তিনটি কোণ 2x, 3x ও 4x। কোণগুলো নির্ণয় কর।","a":"9x = 180° ⇒ x = 20°\nকোণগুলো 40°, 60°, 80°","lv":"মধ্যম","ex":"6.1"},{"n":"b21","q":"দুইটি সমান্তরাল রেখাকে ছেদক ছেদ করলে একটি একান্তর কোণ 72°। ছেদকের একই পাশের অন্তঃস্থ কোণটি কত?","a":"অপর একান্তর কোণ 72°, একই পাশের অন্তঃস্থ কোণ = 180° − 72° = 108°","lv":"মধ্যম","ex":"6.1"},{"n":"b22","q":"প্রমাণ কর যে, দুইটি সমান্তরাল রেখা ও একটি ছেদকের একই পাশের অন্তঃস্থ কোণদ্বয়ের সমদ্বিখণ্ডকদ্বয় পরস্পর লম্ব।","a":"অন্তঃস্থ কোণদ্বয়ের সমষ্টি 180° ⇒ অর্ধেকের সমষ্টি 90°\nসমদ্বিখণ্ডকদ্বয় ও ছেদক দ্বারা গঠিত ত্রিভুজে তৃতীয় কোণ = 180° − 90° = 90° ∴ লম্ব।","lv":"কঠিন","ex":"6.1"},{"n":"b23","q":"AB ∥ CD এবং E বিন্দুটি রেখাদ্বয়ের মাঝে অবস্থিত। ∠ABE = 40° এবং ∠CDE = 35° হলে ∠BED নির্ণয় কর (E বিন্দুটি B ও D এর একই দিকে)।","a":"E দিয়ে AB এর সমান্তরাল রেখা টানলে ∠BED = ∠ABE + ∠CDE (একান্তর কোণ)\n= 40° + 35° = 75°","lv":"কঠিন","ex":"6.1"},{"n":"b24","q":"AB ∥ CD এবং E বিন্দুটি রেখাদ্বয়ের মাঝে অবস্থিত। ∠ABE = 130° এবং ∠CDE = 120° হলে ∠BED নির্ণয় কর।","a":"E দিয়ে AB এর সমান্তরাল রেখা টানলে একই পাশের অন্তঃস্থ কোণ সম্পূরক হয়\n∠BED = 360° − (130° + 120°) = 110°","lv":"কঠিন","ex":"6.1"},{"n":"b25","q":"কোনো কোণ তার পূরক কোণের 2/3 অংশ। কোণটি নির্ণয় কর।","a":"x = (2/3)(90° − x) ⇒ 5x/3 = 60° ⇒ x = 36°","lv":"মধ্যম","ex":"6.1"},{"n":"b26","q":"কোনো কোণের সম্পূরক কোণ তার পূরক কোণের 3 গুণ। কোণটি নির্ণয় কর।","a":"180° − x = 3(90° − x) ⇒ 2x = 90° ⇒ x = 45°","lv":"কঠিন","ex":"6.1"},{"n":"b27","q":"কোনো কোণের পূরক কোণ ও সম্পূরক কোণের সমষ্টি 130°। কোণটি নির্ণয় কর।","a":"(90° − x) + (180° − x) = 130° ⇒ 2x = 140° ⇒ x = 70°","lv":"কঠিন","ex":"6.1"},{"n":"b28","q":"দুইটি সম্পূরক কোণের অন্তর 40°। কোণ দুইটি নির্ণয় কর।","a":"x + y = 180°, x − y = 40° ⇒ x = 110°, y = 70°","lv":"মধ্যম","ex":"6.1"},{"n":"b29","q":"AOB একটি সরলরেখা এবং OC রশ্মি এমন যে ∠AOC = 3∠BOC। ∠AOC ও ∠BOC নির্ণয় কর।","a":"4∠BOC = 180° ⇒ ∠BOC = 45°, ∠AOC = 135°","lv":"মধ্যম","ex":"6.1"},{"n":"b30","q":"প্রমাণ কর যে, একই সরলরেখার উপর লম্ব দুইটি সরলরেখা পরস্পর সমান্তরাল।","a":"l ও m উভয়ে n এর উপর লম্ব হলে n ছেদকের সাপেক্ষে অনুরূপ কোণদ্বয় 90° করে সমান।\nঅনুরূপ কোণ সমান হলে রেখাদ্বয় সমান্তরাল ∴ l ∥ m","lv":"কঠিন","ex":"6.1"},{"n":"b31","q":"একটি ত্রিভুজের কোণগুলোর অনুপাত 2 : 3 : 4। কোণগুলো নির্ণয় কর।","a":"9k = 180° ⇒ k = 20°\nকোণগুলো 40°, 60°, 80°","lv":"মধ্যম","ex":"6.2"},{"n":"b32","q":"একটি সমদ্বিবাহু ত্রিভুজের শীর্ষকোণ 40°। ভূমি সংলগ্ন কোণ দুইটি নির্ণয় কর।","a":"ভূমি সংলগ্ন কোণদ্বয় সমান = (180° − 40°)/2 = 70° করে","lv":"মধ্যম","ex":"6.2"},{"n":"b33","q":"একটি ত্রিভুজের একটি বহিঃস্থ কোণ 120° এবং একটি বিপরীত অন্তঃস্থ কোণ 50°। অপর কোণ দুইটি নির্ণয় কর।","a":"অপর বিপরীত অন্তঃস্থ কোণ = 120° − 50° = 70°\nতৃতীয় কোণ = 180° − 120° = 60°","lv":"মধ্যম","ex":"6.2"},{"n":"b34","q":"একটি ত্রিভুজের কোণগুলো (x + 10)°, (2x − 20)° ও (3x + 10)°। কোণগুলো নির্ণয় কর।","a":"6x = 180 ⇒ x = 30\nকোণগুলো 40°, 40°, 100°","lv":"মধ্যম","ex":"6.2"},{"n":"b35","q":"একটি সমকোণী ত্রিভুজের একটি সূক্ষ্মকোণ অপরটির দ্বিগুণ। সূক্ষ্মকোণ দুইটি নির্ণয় কর।","a":"x + 2x = 90° ⇒ x = 30°\nকোণ দুইটি 30° ও 60°","lv":"মধ্যম","ex":"6.2"},{"n":"b36","q":"প্রমাণ কর যে, সমবাহু ত্রিভুজের প্রত্যেকটি বহিঃস্থ কোণ 120°।","a":"সমবাহু ত্রিভুজের প্রতিটি কোণ 180°/3 = 60°\nবহিঃস্থ কোণ = 180° − 60° = 120°","lv":"মধ্যম","ex":"6.2"},{"n":"b37","q":"একটি সমদ্বিবাহু ত্রিভুজের ভূমি সংলগ্ন প্রতিটি কোণ শীর্ষকোণের দ্বিগুণ। কোণগুলো নির্ণয় কর।","a":"x + 2x + 2x = 180° ⇒ x = 36°\nকোণগুলো 36°, 72°, 72°","lv":"কঠিন","ex":"6.2"},{"n":"b38","q":"প্রমাণ কর যে, ত্রিভুজের তিন কোণের সমষ্টি দুই সমকোণ।","a":"△ABC এর A বিন্দু দিয়ে BC এর সমান্তরাল DE টানি।\n∠DAB = ∠B, ∠EAC = ∠C (একান্তর)\n∠DAB + ∠A + ∠EAC = 180° ⇒ ∠A + ∠B + ∠C = 180°","lv":"মধ্যম","ex":"6.2"},{"n":"b39","q":"প্রমাণ কর যে, ত্রিভুজের একটি বাহু বর্ধিত করলে উৎপন্ন বহিঃস্থ কোণ বিপরীত অন্তঃস্থ কোণদ্বয়ের সমষ্টির সমান।","a":"BC কে D পর্যন্ত বর্ধিত করলে ∠ACD + ∠ACB = 180°\nআবার ∠A + ∠B + ∠ACB = 180° ∴ ∠ACD = ∠A + ∠B","lv":"মধ্যম","ex":"6.2"},{"n":"b40","q":"△ABC এর ∠B ও ∠C এর অন্তঃসমদ্বিখণ্ডক O বিন্দুতে মিলিত হয়। ∠A = 70° হলে ∠BOC নির্ণয় কর।","a":"∠BOC = 180° − (∠B + ∠C)/2 = 180° − (180° − 70°)/2 = 90° + 70°/2 = 125°","lv":"কঠিন","ex":"6.2"},{"n":"b41","q":"△ABC এর ∠B ও ∠C এর বহিঃসমদ্বিখণ্ডক O বিন্দুতে মিলিত হয়। ∠A = 60° হলে ∠BOC নির্ণয় কর।","a":"∠BOC = 90° − ∠A/2 = 90° − 30° = 60°","lv":"কঠিন","ex":"6.2"},{"n":"b42","q":"△ABC এ AB = AC এবং ∠B = 65° হলে ∠A নির্ণয় কর।","a":"∠C = ∠B = 65° ⇒ ∠A = 180° − 130° = 50°","lv":"মধ্যম","ex":"6.2"},{"n":"b43","q":"প্রমাণ কর যে, ত্রিভুজের তিনটি শীর্ষে উৎপন্ন বহিঃস্থ কোণত্রয়ের সমষ্টি চার সমকোণ।","a":"প্রতিটি বহিঃস্থ কোণ = 180° − সংলগ্ন অন্তঃস্থ কোণ\nসমষ্টি = 3 × 180° − 180° = 360° = চার সমকোণ","lv":"কঠিন","ex":"6.2"},{"n":"b44","q":"△ABC এ ∠A − ∠B = 15° এবং ∠B − ∠C = 30°। কোণগুলো নির্ণয় কর।","a":"∠A = ∠B + 15°, ∠C = ∠B − 30° ⇒ 3∠B − 15° = 180° ⇒ ∠B = 65°\n∠A = 80°, ∠C = 35°","lv":"কঠিন","ex":"6.2"},{"n":"b45","q":"একটি ত্রিভুজের দুইটি কোণ স্থূলকোণ হতে পারে কি? যুক্তি দাও।","a":"দুইটি স্থূলকোণের সমষ্টি 180° এর বেশি, অথচ তিন কোণের সমষ্টি 180°।\n∴ পারে না।","lv":"মধ্যম","ex":"6.2"},{"n":"b46","q":"△ABC এ ∠B = 90° এবং BD ⊥ AC। ∠A = 35° হলে ∠DBC নির্ণয় কর।","a":"∠C = 90° − 35° = 55°\n△BDC তে ∠DBC = 90° − ∠C = 35°","lv":"কঠিন","ex":"6.2"},{"n":"b47","q":"△ABC এ AD ⊥ BC, AE হলো ∠A এর সমদ্বিখণ্ডক, ∠B = 50° এবং ∠C = 70°। ∠DAE নির্ণয় কর।","a":"∠A = 60°, ∠BAE = 30°, ∠BAD = 90° − 50° = 40°\n∠DAE = 40° − 30° = 10°","lv":"কঠিন","ex":"6.2"},{"n":"b48","q":"একটি সমদ্বিবাহু সমকোণী ত্রিভুজের কোণগুলো নির্ণয় কর।","a":"সমান কোণদ্বয় x হলে 2x + 90° = 180° ⇒ x = 45°\nকোণগুলো 45°, 45°, 90°","lv":"মধ্যম","ex":"6.2"},{"n":"b49","q":"একটি ত্রিভুজের কোণগুলো তিনটি ক্রমিক পূর্ণসংখ্যা (ডিগ্রিতে)। কোণগুলো নির্ণয় কর।","a":"x + (x + 1) + (x + 2) = 180 ⇒ x = 59\nকোণগুলো 59°, 60°, 61°","lv":"মধ্যম","ex":"6.2"},{"n":"b50","q":"একটি ত্রিভুজের বহিঃস্থ কোণগুলোর অনুপাত 4 : 5 : 6। অন্তঃস্থ কোণগুলো নির্ণয় কর।","a":"বহিঃস্থ কোণের সমষ্টি 360° ⇒ 96°, 120°, 144°\nঅন্তঃস্থ কোণ 84°, 60°, 36°","lv":"কঠিন","ex":"6.2"},{"n":"b51","q":"△ABC এ AB = AC এবং BA কে D পর্যন্ত বর্ধিত করা হলো। ∠DAC = 110° হলে ∠B ও ∠C নির্ণয় কর।","a":"∠DAC = ∠B + ∠C = 2∠B = 110° ⇒ ∠B = ∠C = 55°","lv":"কঠিন","ex":"6.2"},{"n":"b52","q":"△ABC এ ∠A = ∠B + ∠C হলে ∠A এর মান নির্ণয় কর এবং ত্রিভুজটি কোন ধরনের বল।","a":"2∠A = 180° ⇒ ∠A = 90°\nত্রিভুজটি সমকোণী।","lv":"মধ্যম","ex":"6.2"},{"n":"b53","q":"একটি ত্রিভুজের দুইটি কোণ 75° ও 65°। তৃতীয় কোণ নির্ণয় কর এবং কোণভেদে ত্রিভুজটির নাম লেখ।","a":"তৃতীয় কোণ = 180° − 140° = 40°\nসব কোণ সূক্ষ্ম ∴ সূক্ষ্মকোণী ত্রিভুজ","lv":"মধ্যম","ex":"6.2"},{"n":"b54","q":"△ABC এ AB = AC এবং AD, ∠A এর সমদ্বিখণ্ডক যা BC কে D তে ছেদ করে। প্রমাণ কর যে, AD ⊥ BC","a":"△ABD ও △ACD তে AB = AC, ∠BAD = ∠CAD, AD সাধারণ ⇒ △ABD ≅ △ACD (বাহু-কোণ-বাহু)\n∴ ∠ADB = ∠ADC; সমষ্টি 180° ⇒ প্রত্যেকে 90°","lv":"কঠিন","ex":"6.2"},{"n":"b55","q":"প্রমাণ কর যে, সমদ্বিবাহু ত্রিভুজের ভূমি সংলগ্ন কোণদ্বয় সমান।","a":"△ABC এ AB = AC, ∠A এর সমদ্বিখণ্ডক AD টানি।\n△ABD ≅ △ACD (বাহু-কোণ-বাহু) ∴ ∠B = ∠C","lv":"মধ্যম","ex":"6.2"},{"n":"b56","q":"△ABC এ ∠B = 90° এবং AB = BC হলে ∠A এর মান নির্ণয় কর।","a":"∠A = ∠C এবং ∠A + ∠C = 90° ⇒ ∠A = 45°","lv":"মধ্যম","ex":"6.2"},{"n":"b57","q":"△ABC এর BC বাহুর উপর D এমন একটি বিন্দু যে AD = BD = DC। প্রমাণ কর যে, ∠BAC = 90°","a":"AD = BD ⇒ ∠BAD = ∠B; AD = DC ⇒ ∠CAD = ∠C\n∠BAC = ∠B + ∠C; আবার ∠BAC + ∠B + ∠C = 180° ⇒ ∠BAC = 90°","lv":"কঠিন","ex":"6.2"},{"n":"b58","q":"△ABC এ ∠B = ∠C = 2∠A। কোণগুলো নির্ণয় কর।","a":"x + 2x + 2x = 180° ⇒ x = 36°\n∠A = 36°, ∠B = ∠C = 72°","lv":"মধ্যম","ex":"6.2"},{"n":"b59","q":"△ABC এর C বিন্দুতে উৎপন্ন বহিঃস্থ কোণ 110° এবং ∠A = ∠B। ∠A নির্ণয় কর।","a":"∠A + ∠B = 110° ⇒ ∠A = 55°","lv":"মধ্যম","ex":"6.2"},{"n":"b60","q":"△ABC এর ∠A এর সমদ্বিখণ্ডক BC কে D বিন্দুতে ছেদ করে। ∠B = 60° এবং ∠C = 40° হলে ∠ADB ও ∠ADC নির্ণয় কর।","a":"∠A = 80°, ∠BAD = 40°\n∠ADB = 180° − 60° − 40° = 80°, ∠ADC = 100°","lv":"কঠিন","ex":"6.2"},{"n":"b61","q":"3 সেমি, 4 সেমি ও 8 সেমি দৈর্ঘ্যের রেখাংশ দিয়ে ত্রিভুজ গঠন সম্ভব কি? যুক্তি দাও।","a":"3 + 4 = 7 < 8, অর্থাৎ দুই বাহুর সমষ্টি তৃতীয় বাহু অপেক্ষা ছোট।\n∴ সম্ভব নয়।","lv":"মধ্যম","ex":"6.3"},{"n":"b62","q":"একটি ত্রিভুজের দুইটি বাহু 5 সেমি ও 9 সেমি। তৃতীয় বাহুর দৈর্ঘ্য কোন সীমার মধ্যে থাকবে?","a":"9 − 5 < x < 9 + 5 ⇒ 4 < x < 14 সেমি","lv":"মধ্যম","ex":"6.3"},{"n":"b63","q":"একটি ষড়ভুজের অন্তঃস্থ কোণগুলোর সমষ্টি নির্ণয় কর।","a":"(n − 2) × 180° = 4 × 180° = 720°","lv":"মধ্যম","ex":"6.3"},{"n":"b64","q":"একটি সুষম অষ্টভুজের প্রতিটি অন্তঃস্থ কোণের মান নির্ণয় কর।","a":"বহিঃস্থ কোণ = 360°/8 = 45°, অন্তঃস্থ কোণ = 135°","lv":"মধ্যম","ex":"6.3"},{"n":"b65","q":"একটি সুষম বহুভুজের প্রতিটি বহিঃস্থ কোণ 30° হলে এর বাহুর সংখ্যা কত?","a":"n = 360°/30° = 12","lv":"মধ্যম","ex":"6.3"},{"n":"b66","q":"একটি সুষম বহুভুজের প্রতিটি অন্তঃস্থ কোণ 140° হলে বাহুর সংখ্যা কত?","a":"বহিঃস্থ কোণ = 40° ⇒ n = 360°/40° = 9","lv":"মধ্যম","ex":"6.3"},{"n":"b67","q":"কোনো বহুভুজের অন্তঃস্থ কোণগুলোর সমষ্টি 1440° হলে এর বাহুর সংখ্যা কত?","a":"(n − 2) × 180° = 1440° ⇒ n − 2 = 8 ⇒ n = 10","lv":"মধ্যম","ex":"6.3"},{"n":"b68","q":"একটি সুষম বহুভুজের প্রতিটি অন্তঃস্থ কোণ বহিঃস্থ কোণের 4 গুণ। বাহুর সংখ্যা নির্ণয় কর।","a":"বহিঃস্থ x হলে x + 4x = 180° ⇒ x = 36° ⇒ n = 360°/36° = 10","lv":"কঠিন","ex":"6.3"},{"n":"b69","q":"একটি অষ্টভুজের কর্ণের সংখ্যা নির্ণয় কর।","a":"কর্ণসংখ্যা = n(n − 3)/2 = 8 × 5/2 = 20","lv":"মধ্যম","ex":"6.3"},{"n":"b70","q":"কোনো বহুভুজের কর্ণের সংখ্যা 35 হলে বাহুর সংখ্যা কত?","a":"n(n − 3)/2 = 35 ⇒ n² − 3n − 70 = 0 ⇒ (n − 10)(n + 7) = 0 ⇒ n = 10","lv":"কঠিন","ex":"6.3"},{"n":"b71","q":"△ABC এ AB = 7 সেমি, BC = 5 সেমি এবং CA = 9 সেমি। কোণগুলোকে মানের অধঃক্রমে সাজাও।","a":"বৃহত্তর বাহুর বিপরীত কোণ বৃহত্তর।\nCA > AB > BC ⇒ ∠B > ∠C > ∠A","lv":"কঠিন","ex":"6.3"},{"n":"b72","q":"△ABC এ ∠A = 70° এবং ∠B = 50°। বৃহত্তম ও ক্ষুদ্রতম বাহু চিহ্নিত কর।","a":"∠C = 60°; বৃহত্তম কোণ ∠A ⇒ বৃহত্তম বাহু BC\nক্ষুদ্রতম কোণ ∠B ⇒ ক্ষুদ্রতম বাহু AC","lv":"কঠিন","ex":"6.3"},{"n":"b73","q":"প্রমাণ কর যে, ত্রিভুজের যেকোনো দুই বাহুর সমষ্টি তৃতীয় বাহু অপেক্ষা বৃহত্তর।","a":"△ABC এর BA কে D পর্যন্ত বাড়াই যেন AD = AC। তাহলে ∠ACD = ∠ADC\n∠BCD > ∠ACD = ∠BDC ⇒ BD > BC ⇒ AB + AC > BC","lv":"কঠিন","ex":"6.3"},{"n":"b74","q":"প্রমাণ কর যে, ত্রিভুজের যেকোনো দুই বাহুর অন্তর তৃতীয় বাহু অপেক্ষা ক্ষুদ্রতর।","a":"AB < AC + BC ⇒ AB − AC < BC\nএকইভাবে অন্যান্য বাহুর জন্যও প্রযোজ্য।","lv":"কঠিন","ex":"6.3"},{"n":"b75","q":"6 সেমি, 6 সেমি ও 12 সেমি বাহু দিয়ে ত্রিভুজ আঁকা সম্ভব কি?","a":"6 + 6 = 12, যা তৃতীয় বাহুর সমান (বৃহত্তর নয়)।\n∴ সম্ভব নয়।","lv":"মধ্যম","ex":"6.3"},{"n":"b76","q":"প্রমাণ কর যে, চতুর্ভুজের কর্ণদ্বয়ের সমষ্টি তার পরিসীমা অপেক্ষা ক্ষুদ্রতর।","a":"ABCD চতুর্ভুজে AC < AB + BC, AC < AD + DC, BD < AB + AD, BD < BC + CD\nযোগ করে 2(AC + BD) < 2(পরিসীমা) ⇒ AC + BD < পরিসীমা","lv":"কঠিন","ex":"6.3"},{"n":"b77","q":"একটি সুষম বহুভুজের প্রতিটি বহিঃস্থ কোণ অন্তঃস্থ কোণের এক-পঞ্চমাংশ। বাহুর সংখ্যা নির্ণয় কর।","a":"x + 5x = 180° ⇒ x = 30° ⇒ n = 12","lv":"কঠিন","ex":"6.3"},{"n":"b78","q":"একটি পঞ্চভুজের কোণগুলো x, x + 10°, x + 20°, x + 30° ও x + 40°। কোণগুলো নির্ণয় কর।","a":"5x + 100° = 540° ⇒ x = 88°\nকোণগুলো 88°, 98°, 108°, 118°, 128°","lv":"কঠিন","ex":"6.3"},{"n":"b79","q":"একটি চতুর্ভুজের কোণগুলোর অনুপাত 1 : 2 : 3 : 4। কোণগুলো নির্ণয় কর।","a":"10k = 360° ⇒ k = 36°\nকোণগুলো 36°, 72°, 108°, 144°","lv":"মধ্যম","ex":"6.3"},{"n":"b80","q":"20 বাহুবিশিষ্ট সুষম বহুভুজের প্রতিটি অন্তঃস্থ কোণ নির্ণয় কর।","a":"বহিঃস্থ কোণ = 18° ⇒ অন্তঃস্থ কোণ = 162°","lv":"মধ্যম","ex":"6.3"},{"n":"b81","q":"প্রতিটি অন্তঃস্থ কোণ 100° এমন সুষম বহুভুজ সম্ভব কি? যুক্তি দাও।","a":"বহিঃস্থ কোণ 80° ⇒ n = 360/80 = 4.5, যা পূর্ণসংখ্যা নয়।\n∴ সম্ভব নয়।","lv":"কঠিন","ex":"6.3"},{"n":"b82","q":"△ABC এর অভ্যন্তরে P একটি বিন্দু। প্রমাণ কর যে, PB + PC < AB + AC","a":"BP কে বাড়ালে AC কে D তে ছেদ করে।\nPB + PC < PB + PD + DC = BD + DC < AB + AD + DC = AB + AC","lv":"কঠিন","ex":"6.3"},{"n":"b83","q":"একটি ত্রিভুজের দুইটি বাহু 3 সেমি ও 8 সেমি এবং তৃতীয় বাহু পূর্ণসংখ্যা। তৃতীয় বাহুর সম্ভাব্য মানগুলো লেখ।","a":"5 < x < 11 ⇒ x = 6, 7, 8, 9, 10 সেমি","lv":"কঠিন","ex":"6.3"},{"n":"b84","q":"△ABC এর AD মধ্যমা। প্রমাণ কর যে, AB + AC > 2AD","a":"AD কে E পর্যন্ত বাড়াই যেন DE = AD। △ABD ≅ △ECD ⇒ CE = AB\n△ACE এ AC + CE > AE ⇒ AB + AC > 2AD","lv":"কঠিন","ex":"6.3"},{"n":"b85","q":"একটি সপ্তভুজের বহিঃস্থ কোণগুলোর সমষ্টি কত? (প্রতি শীর্ষে একটি করে)","a":"যেকোনো উত্তল বহুভুজের বহিঃস্থ কোণগুলোর সমষ্টি 360°","lv":"মধ্যম","ex":"6.3"},{"n":"b86","q":"একটি ষড়ভুজের পাঁচটি কোণ 120°, 130°, 110°, 140° ও 125°। ষষ্ঠ কোণটি নির্ণয় কর।","a":"কোণগুলোর সমষ্টি 720° ⇒ ষষ্ঠ কোণ = 720° − 625° = 95°","lv":"মধ্যম","ex":"6.3"},{"n":"b87","q":"কোনো বহুভুজের অন্তঃস্থ কোণগুলোর সমষ্টি বহিঃস্থ কোণগুলোর সমষ্টির দ্বিগুণ। বাহুর সংখ্যা কত?","a":"(n − 2) × 180° = 2 × 360° ⇒ n = 6","lv":"কঠিন","ex":"6.3"},{"n":"b88","q":"একটি সুষম বহুভুজের অন্তঃস্থ ও বহিঃস্থ কোণের অন্তর 108°। বাহুর সংখ্যা নির্ণয় কর।","a":"অন্তঃস্থ + বহিঃস্থ = 180°, অন্তর = 108° ⇒ বহিঃস্থ = 36° ⇒ n = 10","lv":"কঠিন","ex":"6.3"},{"n":"b89","q":"একটি ত্রিভুজের বাহুগুলো 2x, 3x ও 4x সেমি এবং পরিসীমা 36 সেমি। বাহুগুলো নির্ণয় কর এবং ত্রিভুজ গঠন সম্ভব কি না যাচাই কর।","a":"9x = 36 ⇒ x = 4 ⇒ বাহু 8, 12, 16 সেমি\n8 + 12 = 20 > 16 ∴ সম্ভব","lv":"মধ্যম","ex":"6.3"},{"n":"b90","q":"প্রমাণ কর যে, সমকোণী ত্রিভুজের অতিভুজই বৃহত্তম বাহু।","a":"সমকোণী ত্রিভুজে অপর দুই কোণ সূক্ষ্মকোণ, তাই সমকোণই বৃহত্তম কোণ।\nবৃহত্তম কোণের বিপরীত বাহু বৃহত্তম ∴ অতিভুজ বৃহত্তম।","lv":"মধ্যম","ex":"6.3"}],"7":[{"n":"b1","q":"একটি ত্রিভুজ নির্দিষ্টভাবে আঁকার জন্য ন্যূনতম কয়টি স্বতন্ত্র উপাত্ত প্রয়োজন? উদাহরণ দাও।","a":"ন্যূনতম 3টি স্বতন্ত্র উপাত্ত।\nযেমন: তিনটি বাহু, অথবা দুইটি বাহু ও এদের অন্তর্ভুক্ত কোণ, অথবা দুইটি কোণ ও একটি বাহু।","lv":"মধ্যম","ex":"7.1"},{"n":"b2","q":"তিনটি কোণ 50°, 60° ও 70° দেওয়া থাকলে নির্দিষ্ট একটি ত্রিভুজ আঁকা সম্ভব কি? যুক্তি দাও।","a":"কোণগুলোর সমষ্টি 180° হওয়ায় ত্রিভুজ আঁকা যায়, কিন্তু অসংখ্য সদৃশ ত্রিভুজ পাওয়া যায়।\n∴ নির্দিষ্ট ত্রিভুজ আঁকা সম্ভব নয়।","lv":"মধ্যম","ex":"7.1"},{"n":"b3","q":"△ABC এ ∠A = 90°, BC = 4 সেমি এবং AC = 5 সেমি দেওয়া আছে। এমন ত্রিভুজ আঁকা সম্ভব কি?","a":"∠A = 90° হলে BC অতিভুজ এবং বৃহত্তম বাহু হতে হবে।\nকিন্তু BC = 4 < AC = 5 ∴ সম্ভব নয়।","lv":"কঠিন","ex":"7.1"},{"n":"b4","q":"5 সেমি, 6 সেমি ও 7 সেমি বাহুবিশিষ্ট ত্রিভুজ আঁকার ধাপগুলো সংক্ষেপে লেখ।","a":"1) BC = 7 সেমি রেখাংশ আঁকি।\n2) B কে কেন্দ্র করে 5 সেমি ও C কে কেন্দ্র করে 6 সেমি ব্যাসার্ধে বৃত্তচাপ আঁকি; ছেদবিন্দু A।\n3) A, B ও A, C যোগ করলে △ABC আঁকা হলো।","lv":"মধ্যম","ex":"7.1"},{"n":"b5","q":"দুইটি বাহু 5 সেমি ও 6 সেমি এবং এদের অন্তর্ভুক্ত কোণ 60° দেওয়া থাকলে ত্রিভুজ আঁকার ধাপগুলো লেখ।","a":"1) BC = 6 সেমি আঁকি।\n2) B বিন্দুতে ∠CBX = 60° আঁকি।\n3) BX থেকে BA = 5 সেমি কেটে নিই এবং A, C যোগ করি।","lv":"মধ্যম","ex":"7.1"},{"n":"b6","q":"ভূমি 6 সেমি এবং ভূমি সংলগ্ন কোণ দুইটি 45° ও 60° হলে ত্রিভুজ আঁকার ধাপ লেখ। তৃতীয় কোণটি কত?","a":"1) BC = 6 সেমি আঁকি। 2) B তে 45° ও C তে 60° কোণ আঁকি; রশ্মিদ্বয় A তে ছেদ করে।\nতৃতীয় কোণ = 180° − 105° = 75°","lv":"মধ্যম","ex":"7.1"},{"n":"b7","q":"একটি সমকোণী ত্রিভুজের অতিভুজ 10 সেমি এবং একটি বাহু 6 সেমি। অপর বাহুর দৈর্ঘ্য নির্ণয় কর।","a":"অপর বাহু = √(10² − 6²) = √64 = 8 সেমি","lv":"মধ্যম","ex":"7.1"},{"n":"b8","q":"একটি ত্রিভুজের কোণগুলো 30°, 60°, 90° এবং অতিভুজ 12 সেমি। অপর বাহুদ্বয় নির্ণয় কর।","a":"30° কোণের বিপরীত বাহু = অতিভুজের অর্ধেক = 6 সেমি\nঅপর বাহু = √(144 − 36) = 6√3 সেমি","lv":"কঠিন","ex":"7.1"},{"n":"b9","q":"একটি সমবাহু ত্রিভুজের পরিসীমা 18 সেমি। এর উচ্চতা নির্ণয় কর।","a":"বাহু = 6 সেমি\nউচ্চতা = (√3/2) × 6 = 3√3 সেমি","lv":"মধ্যম","ex":"7.1"},{"n":"b10","q":"একটি সমদ্বিবাহু ত্রিভুজের ভূমি 8 সেমি এবং সমান বাহুদ্বয়ের প্রতিটি 5 সেমি। উচ্চতা ও ক্ষেত্রফল নির্ণয় কর।","a":"উচ্চতা = √(5² − 4²) = 3 সেমি\nক্ষেত্রফল = (1/2) × 8 × 3 = 12 বর্গসেমি","lv":"মধ্যম","ex":"7.1"},{"n":"b11","q":"ভূমি, ভূমি সংলগ্ন একটি কোণ এবং অপর দুই বাহুর সমষ্টি দেওয়া আছে। ত্রিভুজ আঁকার ধাপগুলো সংক্ষেপে লেখ।","a":"1) ভূমি BC আঁকি, B তে প্রদত্ত কোণ ∠CBX আঁকি।\n2) BX থেকে BD = বাহুদ্বয়ের সমষ্টি কেটে নিই, C, D যোগ করি।\n3) ∠DCY = ∠BDC আঁকি; CY, BD কে A তে ছেদ করে। △ABC নির্ণেয়।","lv":"কঠিন","ex":"7.1"},{"n":"b12","q":"ভূমি, ভূমি সংলগ্ন একটি সূক্ষ্মকোণ এবং অপর দুই বাহুর অন্তর দেওয়া আছে। ত্রিভুজ আঁকার মূল ধারণা লেখ।","a":"ভূমি BC ও B তে প্রদত্ত কোণ আঁকি। BX থেকে BD = বাহুদ্বয়ের অন্তর কেটে নিই।\nCD এর লম্বদ্বিখণ্ডক BX কে A তে ছেদ করলে AD = AC হয় ⇒ AB − AC = BD","lv":"কঠিন","ex":"7.1"},{"n":"b13","q":"পরিসীমা এবং ভূমি সংলগ্ন দুইটি কোণ দেওয়া থাকলে ত্রিভুজ আঁকার মূল ধাপ লেখ।","a":"পরিসীমার সমান PQ আঁকি, P ও Q তে প্রদত্ত কোণদ্বয়ের অর্ধেক আঁকি; এরা A তে ছেদ করে।\nAP ও AQ এর লম্বদ্বিখণ্ডক PQ কে B ও C তে ছেদ করে। △ABC নির্ণেয়।","lv":"কঠিন","ex":"7.1"},{"n":"b14","q":"রুলার ও কম্পাসের সাহায্যে 60° কোণ আঁকার ধাপ লেখ।","a":"1) রশ্মি AB আঁকি। 2) A কে কেন্দ্র করে যেকোনো ব্যাসার্ধে বৃত্তচাপ আঁকি, যা AB কে C তে ছেদ করে।\n3) C কে কেন্দ্র করে একই ব্যাসার্ধে চাপ আঁকি, আগের চাপকে D তে ছেদ করে। ∠DAB = 60°","lv":"মধ্যম","ex":"7.1"},{"n":"b15","q":"রুলার ও কম্পাসের সাহায্যে 45° কোণ কীভাবে আঁকবে?","a":"প্রথমে 90° কোণ আঁকি (লম্ব অঙ্কন করে)।\nতারপর এটিকে সমদ্বিখণ্ডিত করলে 45° কোণ পাওয়া যায়।","lv":"মধ্যম","ex":"7.1"},{"n":"b16","q":"রুলার ও কম্পাসের সাহায্যে 75° কোণ কীভাবে আঁকবে?","a":"একই বিন্দুতে 60° ও 90° কোণ আঁকি।\nএদের মধ্যবর্তী 30° কোণকে সমদ্বিখণ্ডিত করলে 60° + 15° = 75° পাওয়া যায়।","lv":"কঠিন","ex":"7.1"},{"n":"b17","q":"একটি রেখাংশের লম্বদ্বিখণ্ডক আঁকার ধাপগুলো লেখ।","a":"1) AB এর অর্ধেকের বেশি ব্যাসার্ধ নিয়ে A ও B কে কেন্দ্র করে উভয় পাশে চাপ আঁকি।\n2) চাপগুলোর ছেদবিন্দু P ও Q যোগ করি। PQ হলো AB এর লম্বদ্বিখণ্ডক।","lv":"মধ্যম","ex":"7.1"},{"n":"b18","q":"রুলার ও কম্পাসের সাহায্যে 120° কোণ আঁকার ধাপ লেখ।","a":"রশ্মি AB আঁকি, A কে কেন্দ্র করে চাপ আঁকি যা AB কে C তে ছেদ করে।\nC থেকে একই ব্যাসার্ধে পরপর দুইবার চাপ কেটে D ও E পাই। ∠EAB = 120°","lv":"মধ্যম","ex":"7.1"},{"n":"b19","q":"7 সেমি দৈর্ঘ্যের একটি রেখাংশকে তিনটি সমান অংশে বিভক্ত করার পদ্ধতি লেখ।","a":"AB এর A বিন্দু থেকে সূক্ষ্মকোণে রশ্মি AX টেনে সমান দূরত্বে A₁, A₂, A₃ চিহ্নিত করি।\nA₃B যোগ করে A₁ ও A₂ দিয়ে A₃B এর সমান্তরাল রেখা টানলে AB তিন সমান অংশে বিভক্ত হয়।","lv":"কঠিন","ex":"7.1"},{"n":"b20","q":"3 সেমি, 4 সেমি ও 5 সেমি বাহুবিশিষ্ট ত্রিভুজ আঁকলে এটি কোন ধরনের ত্রিভুজ হবে? যাচাই কর।","a":"3² + 4² = 9 + 16 = 25 = 5²\n∴ পিথাগোরাসের উপপাদ্যের বিপরীত অনুসারে এটি সমকোণী ত্রিভুজ।","lv":"মধ্যম","ex":"7.1"},{"n":"b21","q":"একটি সমদ্বিবাহু ত্রিভুজের পরিসীমা 16 সেমি এবং ভূমি 6 সেমি। সমান বাহু দুইটির দৈর্ঘ্য কত?","a":"2x + 6 = 16 ⇒ x = 5 সেমি","lv":"মধ্যম","ex":"7.1"},{"n":"b22","q":"একটি সমবাহু ত্রিভুজের উচ্চতা 3√3 সেমি। এর বাহুর দৈর্ঘ্য নির্ণয় কর।","a":"(√3/2) × a = 3√3 ⇒ a = 6 সেমি","lv":"মধ্যম","ex":"7.1"},{"n":"b23","q":"6 সেমি, 8 সেমি ও 12 সেমি বাহু দিয়ে ত্রিভুজ আঁকা সম্ভব কি? সম্ভব হলে কোণভেদে কোন ধরনের ত্রিভুজ?","a":"6 + 8 = 14 > 12 ∴ সম্ভব\n6² + 8² = 100 < 144 = 12² ∴ স্থূলকোণী ত্রিভুজ","lv":"কঠিন","ex":"7.1"},{"n":"b24","q":"7, 24 ও 25 একক বাহুবিশিষ্ট ত্রিভুজটি কোন ধরনের? যাচাই কর।","a":"7² + 24² = 49 + 576 = 625 = 25² ∴ সমকোণী ত্রিভুজ","lv":"মধ্যম","ex":"7.1"},{"n":"b25","q":"একটি সমদ্বিবাহু সমকোণী ত্রিভুজের অতিভুজ 8√2 সেমি। সমান বাহু দুইটির দৈর্ঘ্য নির্ণয় কর।","a":"2a² = (8√2)² = 128 ⇒ a = 8 সেমি","lv":"মধ্যম","ex":"7.1"},{"n":"b26","q":"একটি সমকোণী ত্রিভুজের সমকোণ সংলগ্ন বাহুদ্বয়ের অনুপাত 3 : 4 এবং অতিভুজ 20 সেমি। বাহুদ্বয় নির্ণয় কর।","a":"(3k)² + (4k)² = 400 ⇒ 25k² = 400 ⇒ k = 4\nবাহুদ্বয় 12 সেমি ও 16 সেমি","lv":"কঠিন","ex":"7.1"},{"n":"b27","q":"একটি সমকোণী ত্রিভুজের একটি কোণ 30° এবং 30° কোণের বিপরীত বাহু 5 সেমি। অতিভুজ ও অপর বাহু নির্ণয় কর।","a":"অতিভুজ = 2 × 5 = 10 সেমি\nঅপর বাহু = √(100 − 25) = 5√3 সেমি","lv":"কঠিন","ex":"7.1"},{"n":"b28","q":"2 সেমি, 3 সেমি ও 6 সেমি বাহু দিয়ে ত্রিভুজ আঁকা যাবে না কেন?","a":"2 + 3 = 5 < 6; ত্রিভুজের যেকোনো দুই বাহুর সমষ্টি তৃতীয় বাহু অপেক্ষা বৃহত্তর হতে হয়।","lv":"মধ্যম","ex":"7.1"},{"n":"b29","q":"রুলার ও কম্পাসের সাহায্যে একটি কোণকে সমদ্বিখণ্ডিত করার ধাপ লেখ।","a":"1) কোণের শীর্ষ O কে কেন্দ্র করে চাপ আঁকি, বাহুদ্বয়কে P ও Q তে ছেদ করে।\n2) P ও Q কে কেন্দ্র করে সমান ব্যাসার্ধে চাপ আঁকি, ছেদবিন্দু R। OR কোণটির সমদ্বিখণ্ডক।","lv":"মধ্যম","ex":"7.1"},{"n":"b30","q":"△ABC এ AB = AC, ভূমি BC = 6 সেমি এবং উচ্চতা 4 সেমি। AB এর দৈর্ঘ্য নির্ণয় কর।","a":"শীর্ষ থেকে লম্ব ভূমিকে সমদ্বিখণ্ডিত করে।\nAB = √(3² + 4²) = 5 সেমি","lv":"মধ্যম","ex":"7.1"},{"n":"b31","q":"একটি চতুর্ভুজ নির্দিষ্টভাবে আঁকার জন্য ন্যূনতম কয়টি স্বতন্ত্র উপাত্ত প্রয়োজন?","a":"ন্যূনতম 5টি স্বতন্ত্র উপাত্ত প্রয়োজন।\nযেমন: চারটি বাহু ও একটি কোণ, অথবা চারটি বাহু ও একটি কর্ণ।","lv":"মধ্যম","ex":"7.2"},{"n":"b32","q":"একটি চতুর্ভুজের তিনটি কোণ 90°, 112° ও 80°। চতুর্থ কোণটি নির্ণয় কর।","a":"= 360° − 282° = 78°","lv":"মধ্যম","ex":"7.2"},{"n":"b33","q":"একটি আয়তক্ষেত্রের কর্ণ 15 সেমি এবং একটি বাহু 9 সেমি। অপর বাহু ও ক্ষেত্রফল নির্ণয় কর।","a":"অপর বাহু = √(225 − 81) = 12 সেমি\nক্ষেত্রফল = 9 × 12 = 108 বর্গসেমি","lv":"মধ্যম","ex":"7.2"},{"n":"b34","q":"একটি সামান্তরিকের দুইটি সন্নিহিত কোণ (4x + 6)° ও 54°। x এর মান নির্ণয় কর।","a":"সন্নিহিত কোণ সম্পূরক ⇒ 4x + 6 + 54 = 180 ⇒ x = 30","lv":"মধ্যম","ex":"7.2"},{"n":"b35","q":"একটি রম্বসের কর্ণদ্বয় 16 সেমি ও 12 সেমি। বাহুর দৈর্ঘ্য ও ক্ষেত্রফল নির্ণয় কর।","a":"কর্ণদ্বয় পরস্পরকে লম্বভাবে সমদ্বিখণ্ডিত করে ⇒ বাহু = √(8² + 6²) = 10 সেমি\nক্ষেত্রফল = (16 × 12)/2 = 96 বর্গসেমি","lv":"মধ্যম","ex":"7.2"},{"n":"b36","q":"একটি বর্গের কর্ণ 8√2 সেমি। বাহু ও ক্ষেত্রফল নির্ণয় কর।","a":"বাহু = কর্ণ/√2 = 8 সেমি, ক্ষেত্রফল = 64 বর্গসেমি","lv":"মধ্যম","ex":"7.2"},{"n":"b37","q":"একটি বর্গের ক্ষেত্রফল 50 বর্গসেমি। এর কর্ণের দৈর্ঘ্য নির্ণয় কর।","a":"ক্ষেত্রফল = কর্ণ²/2 ⇒ কর্ণ² = 100 ⇒ কর্ণ = 10 সেমি","lv":"কঠিন","ex":"7.2"},{"n":"b38","q":"একটি সামান্তরিকের একটি কোণ 70° হলে অপর কোণগুলো নির্ণয় কর।","a":"বিপরীত কোণ সমান, সন্নিহিত কোণ সম্পূরক\nকোণগুলো 70°, 110°, 70°, 110°","lv":"মধ্যম","ex":"7.2"},{"n":"b39","q":"একটি আয়তক্ষেত্রের দৈর্ঘ্য প্রস্থ অপেক্ষা 3 সেমি বেশি এবং কর্ণ 15 সেমি। দৈর্ঘ্য ও প্রস্থ নির্ণয় কর।","a":"x² + (x + 3)² = 225 ⇒ x² + 3x − 108 = 0 ⇒ (x + 12)(x − 9) = 0\nপ্রস্থ 9 সেমি, দৈর্ঘ্য 12 সেমি","lv":"কঠিন","ex":"7.2"},{"n":"b40","q":"একটি রম্বসের বাহু 13 সেমি এবং একটি কর্ণ 24 সেমি। অপর কর্ণের দৈর্ঘ্য নির্ণয় কর।","a":"অর্ধকর্ণ = √(13² − 12²) = 5 সেমি ⇒ অপর কর্ণ = 10 সেমি","lv":"কঠিন","ex":"7.2"},{"n":"b41","q":"একটি সমদ্বিবাহু ট্রাপিজিয়ামের সমান্তরাল বাহুদ্বয় 10 সেমি ও 16 সেমি এবং তির্যক বাহুদ্বয় 5 সেমি করে। উচ্চতা ও ক্ষেত্রফল নির্ণয় কর।","a":"প্রতি পাশে বাড়তি অংশ = (16 − 10)/2 = 3 সেমি ⇒ উচ্চতা = √(25 − 9) = 4 সেমি\nক্ষেত্রফল = (10 + 16)/2 × 4 = 52 বর্গসেমি","lv":"কঠিন","ex":"7.2"},{"n":"b42","q":"5 সেমি বাহুবিশিষ্ট একটি বর্গ আঁকার ধাপগুলো লেখ।","a":"1) AB = 5 সেমি আঁকি। 2) A ও B বিন্দুতে AB এর উপর লম্ব আঁকি।\n3) লম্বদ্বয় থেকে AD = BC = 5 সেমি কেটে নিই এবং C, D যোগ করি।","lv":"মধ্যম","ex":"7.2"},{"n":"b43","q":"একটি বাহু ও একটি কর্ণ দেওয়া থাকলে আয়তক্ষেত্র আঁকার ধাপ লেখ।","a":"1) প্রদত্ত বাহু AB আঁকি এবং B তে লম্ব BX আঁকি।\n2) A কে কেন্দ্র করে কর্ণের সমান ব্যাসার্ধে চাপ আঁকি, যা BX কে C তে ছেদ করে।\n3) A ও C থেকে যথাক্রমে BC ও AB এর সমান চাপ এঁকে D পাই।","lv":"কঠিন","ex":"7.2"},{"n":"b44","q":"দুইটি সন্নিহিত বাহু ও এদের অন্তর্ভুক্ত কোণ দেওয়া থাকলে সামান্তরিক আঁকার ধাপ লেখ।","a":"1) AB আঁকি এবং A তে প্রদত্ত কোণ আঁকি; সেই রশ্মি থেকে AD কেটে নিই।\n2) D কে কেন্দ্র করে AB এর সমান এবং B কে কেন্দ্র করে AD এর সমান চাপ আঁকি; ছেদবিন্দু C।","lv":"কঠিন","ex":"7.2"},{"n":"b45","q":"দুইটি কর্ণ দেওয়া থাকলে রম্বস আঁকার ধাপ লেখ।","a":"1) একটি কর্ণ AC আঁকি এবং এর লম্বদ্বিখণ্ডক টানি, যা AC কে O তে ছেদ করে।\n2) লম্বদ্বিখণ্ডক থেকে O এর দুই পাশে অপর কর্ণের অর্ধেক OB ও OD কেটে নিই।\n3) A, B, C, D যোগ করি।","lv":"কঠিন","ex":"7.2"},{"n":"b46","q":"কর্ণ দেওয়া থাকলে বর্গ আঁকার ধাপ লেখ।","a":"1) কর্ণ AC আঁকি এবং এর লম্বদ্বিখণ্ডক টানি, যা AC কে O তে ছেদ করে।\n2) লম্বদ্বিখণ্ডক থেকে O এর দুই পাশে OB = OD = AC/2 কেটে নিই।\n3) A, B, C, D যোগ করি।","lv":"কঠিন","ex":"7.2"},{"n":"b47","q":"শুধু চারটি বাহু দেওয়া থাকলে নির্দিষ্ট চতুর্ভুজ আঁকা যায় কি? যুক্তি দাও।","a":"না। চারটি বাহু অপরিবর্তিত রেখে কোণ পরিবর্তন করে অসংখ্য চতুর্ভুজ আঁকা যায়।\nনির্দিষ্ট চতুর্ভুজের জন্য আরও একটি উপাত্ত (কোণ বা কর্ণ) লাগে।","lv":"মধ্যম","ex":"7.2"},{"n":"b48","q":"একটি চতুর্ভুজের কোণগুলো (x + 20)°, (x − 20)°, (2x + 10)° ও (2x − 10)°। কোণগুলো নির্ণয় কর।","a":"6x = 360 ⇒ x = 60\nকোণগুলো 80°, 40°, 130°, 110°","lv":"মধ্যম","ex":"7.2"},{"n":"b49","q":"ABCD সামান্তরিকে ∠A = 3∠B। সামান্তরিকের কোণগুলো নির্ণয় কর।","a":"∠A + ∠B = 180° ⇒ 4∠B = 180° ⇒ ∠B = 45°\nকোণগুলো 135°, 45°, 135°, 45°","lv":"মধ্যম","ex":"7.2"},{"n":"b50","q":"একটি আয়তক্ষেত্রের পরিসীমা 34 সেমি এবং কর্ণ 13 সেমি। দৈর্ঘ্য ও প্রস্থ নির্ণয় কর।","a":"l + w = 17, l² + w² = 169 ⇒ 2lw = 289 − 169 = 120 ⇒ lw = 60\nl = 12 সেমি, w = 5 সেমি","lv":"কঠিন","ex":"7.2"},{"n":"b51","q":"একটি রম্বসের বাহু 6 সেমি এবং একটি কোণ 60°। কর্ণদ্বয়ের দৈর্ঘ্য নির্ণয় কর।","a":"60° কোণ বিপরীত কর্ণ সমবাহু ত্রিভুজ গঠন করে ⇒ ক্ষুদ্র কর্ণ = 6 সেমি\nবৃহৎ কর্ণ = 2 × √(36 − 9) = 6√3 সেমি","lv":"কঠিন","ex":"7.2"},{"n":"b52","q":"7 সেমি বাহুবিশিষ্ট বর্গের কর্ণের দৈর্ঘ্য নির্ণয় কর।","a":"কর্ণ = 7√2 সেমি","lv":"মধ্যম","ex":"7.2"},{"n":"b53","q":"একটি সামান্তরিকের সন্নিহিত বাহুদ্বয় 8 সেমি ও 6 সেমি এবং অন্তর্ভুক্ত কোণ 30°। ক্ষেত্রফল নির্ণয় কর।","a":"8 সেমি বাহুকে ভূমি ধরলে উচ্চতা = 6 সেমির বিপরীতে 30° ⇒ 6 × 1/2 = 3 সেমি\nক্ষেত্রফল = 8 × 3 = 24 বর্গসেমি","lv":"কঠিন","ex":"7.2"},{"n":"b54","q":"ABCD সামান্তরিকের কর্ণদ্বয় O বিন্দুতে ছেদ করে। AC = 10 সেমি এবং BD = 14 সেমি হলে AO ও BO নির্ণয় কর।","a":"সামান্তরিকের কর্ণদ্বয় পরস্পরকে সমদ্বিখণ্ডিত করে।\nAO = 5 সেমি, BO = 7 সেমি","lv":"মধ্যম","ex":"7.2"},{"n":"b55","q":"ABCD আয়তক্ষেত্রের কর্ণ AC = (2x + 3) সেমি এবং BD = (3x − 4) সেমি। x ও কর্ণের দৈর্ঘ্য নির্ণয় কর।","a":"আয়তক্ষেত্রের কর্ণদ্বয় সমান ⇒ 2x + 3 = 3x − 4 ⇒ x = 7\nকর্ণ = 17 সেমি","lv":"মধ্যম","ex":"7.2"},{"n":"b56","q":"ABCD রম্বসে ∠ABD = 35°। ∠BAD নির্ণয় কর।","a":"রম্বসের কর্ণ কোণকে সমদ্বিখণ্ডিত করে ⇒ ∠ABC = 70°\n∠BAD = 180° − 70° = 110°","lv":"কঠিন","ex":"7.2"},{"n":"b57","q":"ABCD ট্রাপিজিয়ামে AB ∥ DC এবং ∠A = 65°। ∠D নির্ণয় কর।","a":"AB ∥ DC এবং AD ছেদক ⇒ ∠A + ∠D = 180° ⇒ ∠D = 115°","lv":"মধ্যম","ex":"7.2"},{"n":"b58","q":"একটি সমদ্বিবাহু ট্রাপিজিয়ামের ভূমি সংলগ্ন একটি কোণ 70°। অপর কোণগুলো নির্ণয় কর।","a":"ভূমি সংলগ্ন কোণদ্বয় সমান = 70°, 70°\nঅপর দুইটি = 180° − 70° = 110°, 110°","lv":"মধ্যম","ex":"7.2"},{"n":"b59","q":"একটি বর্গের পরিসীমা 36 সেমি। এর কর্ণের দৈর্ঘ্য ও ক্ষেত্রফল নির্ণয় কর।","a":"বাহু = 36/4 = 9 সেমি\nকর্ণ = 9√2 সেমি, ক্ষেত্রফল = 81 বর্গসেমি","lv":"মধ্যম","ex":"7.2"},{"n":"b60","q":"একটি আয়তক্ষেত্রের ক্ষেত্রফল 120 বর্গসেমি এবং দৈর্ঘ্য 15 সেমি। প্রস্থ ও কর্ণ নির্ণয় কর।","a":"প্রস্থ = 120/15 = 8 সেমি\nকর্ণ = √(225 + 64) = 17 সেমি","lv":"মধ্যম","ex":"7.2"}],"8":[{"n":"b1","q":"13 সেমি ব্যাসার্ধের বৃত্তে 24 সেমি দৈর্ঘ্যের একটি জ্যা এর কেন্দ্র থেকে দূরত্ব নির্ণয় কর।","a":"কেন্দ্র থেকে জ্যা এর উপর লম্ব জ্যাকে সমদ্বিখণ্ডিত করে।\nদূরত্ব = √(13² − 12²) = 5 সেমি","lv":"মধ্যম","ex":"8.1"},{"n":"b2","q":"10 সেমি ব্যাসার্ধের বৃত্তের কেন্দ্র থেকে 6 সেমি দূরত্বে অবস্থিত জ্যা এর দৈর্ঘ্য নির্ণয় কর।","a":"অর্ধজ্যা = √(100 − 36) = 8 সেমি ⇒ জ্যা = 16 সেমি","lv":"মধ্যম","ex":"8.1"},{"n":"b3","q":"একটি বৃত্তের 16 সেমি দৈর্ঘ্যের জ্যা কেন্দ্র থেকে 6 সেমি দূরে অবস্থিত। বৃত্তের ব্যাসার্ধ নির্ণয় কর।","a":"ব্যাসার্ধ = √(8² + 6²) = 10 সেমি","lv":"মধ্যম","ex":"8.1"},{"n":"b4","q":"5 সেমি ব্যাসার্ধের বৃত্তে 6 সেমি ও 8 সেমি দৈর্ঘ্যের দুইটি সমান্তরাল জ্যা আছে। জ্যা দুইটি কেন্দ্রের একই পাশে এবং বিপরীত পাশে থাকলে এদের মধ্যবর্তী দূরত্ব নির্ণয় কর।","a":"কেন্দ্র থেকে দূরত্ব: √(25 − 9) = 4 সেমি ও √(25 − 16) = 3 সেমি\nএকই পাশে: 4 − 3 = 1 সেমি; বিপরীত পাশে: 4 + 3 = 7 সেমি","lv":"কঠিন","ex":"8.1"},{"n":"b5","q":"প্রমাণ কর যে, বৃত্তের কেন্দ্র থেকে ব্যাস ভিন্ন কোনো জ্যা এর উপর অঙ্কিত লম্ব জ্যাকে সমদ্বিখণ্ডিত করে।","a":"O কেন্দ্র, OM ⊥ AB। △OAM ও △OBM সমকোণী, OA = OB (ব্যাসার্ধ), OM সাধারণ\n∴ △OAM ≅ △OBM (অতিভুজ-বাহু) ⇒ AM = BM","lv":"মধ্যম","ex":"8.1"},{"n":"b6","q":"প্রমাণ কর যে, বৃত্তের কেন্দ্র ও ব্যাস ভিন্ন কোনো জ্যা এর মধ্যবিন্দুর সংযোজক রেখাংশ ঐ জ্যা এর উপর লম্ব।","a":"M, AB এর মধ্যবিন্দু। △OAM ও △OBM এ OA = OB, AM = BM, OM সাধারণ ⇒ সর্বসম\n∴ ∠OMA = ∠OMB, সমষ্টি 180° ⇒ প্রত্যেকে 90°","lv":"মধ্যম","ex":"8.1"},{"n":"b7","q":"প্রমাণ কর যে, বৃত্তের সমান সমান জ্যা কেন্দ্র থেকে সমদূরবর্তী।","a":"AB = CD, OM ⊥ AB, ON ⊥ CD ⇒ AM = AB/2 = CD/2 = CN\nOM² = OA² − AM² = OC² − CN² = ON² ⇒ OM = ON","lv":"কঠিন","ex":"8.1"},{"n":"b8","q":"17 সেমি ব্যাসার্ধের বৃত্তে 30 সেমি দৈর্ঘ্যের জ্যা এর কেন্দ্র থেকে দূরত্ব নির্ণয় কর।","a":"দূরত্ব = √(17² − 15²) = √64 = 8 সেমি","lv":"মধ্যম","ex":"8.1"},{"n":"b9","q":"প্রমাণ কর যে, বৃত্তের ব্যাসই বৃহত্তম জ্যা।","a":"AB যেকোনো জ্যা হলে △OAB এ AB < OA + OB = 2r (ত্রিভুজের বাহু সম্পর্ক)\nব্যাসের দৈর্ঘ্য 2r ∴ ব্যাস বৃহত্তম জ্যা","lv":"কঠিন","ex":"8.1"},{"n":"b10","q":"13 সেমি ব্যাসার্ধের বৃত্তে 10 সেমি ও 24 সেমি দৈর্ঘ্যের দুইটি সমান্তরাল জ্যা আছে। কেন্দ্রের একই পাশে ও বিপরীত পাশে থাকলে এদের মধ্যবর্তী দূরত্ব নির্ণয় কর।","a":"দূরত্ব: √(169 − 25) = 12 সেমি, √(169 − 144) = 5 সেমি\nএকই পাশে 7 সেমি, বিপরীত পাশে 17 সেমি","lv":"কঠিন","ex":"8.1"},{"n":"b11","q":"একটি বৃত্তের 8 সেমি দৈর্ঘ্যের জ্যা কেন্দ্র থেকে 3 সেমি দূরে অবস্থিত। কেন্দ্র থেকে 4 সেমি দূরের জ্যা এর দৈর্ঘ্য নির্ণয় কর।","a":"ব্যাসার্ধ = √(16 + 9) = 5 সেমি\nনতুন জ্যা = 2√(25 − 16) = 6 সেমি","lv":"কঠিন","ex":"8.1"},{"n":"b12","q":"5 সেমি ব্যাসার্ধের বৃত্তের ভেতরে P বিন্দুটি কেন্দ্র থেকে 3 সেমি দূরে। P বিন্দুগামী ক্ষুদ্রতম ও বৃহত্তম জ্যা এর দৈর্ঘ্য নির্ণয় কর।","a":"ক্ষুদ্রতম জ্যা OP এর উপর লম্ব: 2√(25 − 9) = 8 সেমি\nবৃহত্তম জ্যা = ব্যাস = 10 সেমি","lv":"কঠিন","ex":"8.1"},{"n":"b13","q":"25 সেমি ব্যাসার্ধের বৃত্তে একটি জ্যা কেন্দ্র থেকে 24 সেমি দূরে অবস্থিত। জ্যা টির দৈর্ঘ্য নির্ণয় কর।","a":"জ্যা = 2√(625 − 576) = 2 × 7 = 14 সেমি","lv":"মধ্যম","ex":"8.1"},{"n":"b14","q":"একটি বৃত্তের AB ও CD দুইটি সমান জ্যা। AB কেন্দ্র থেকে 4 সেমি দূরে হলে CD কেন্দ্র থেকে কত দূরে?","a":"সমান জ্যা কেন্দ্র থেকে সমদূরবর্তী ∴ 4 সেমি","lv":"মধ্যম","ex":"8.1"},{"n":"b15","q":"একটি বৃত্তের 48 সেমি দৈর্ঘ্যের জ্যা কেন্দ্র থেকে 7 সেমি দূরে। বৃত্তের ব্যাস নির্ণয় কর।","a":"ব্যাসার্ধ = √(24² + 7²) = 25 সেমি ⇒ ব্যাস = 50 সেমি","lv":"মধ্যম","ex":"8.1"},{"n":"b16","q":"দুইটি এককেন্দ্রিক বৃত্তের ব্যাসার্ধ 10 সেমি ও 6 সেমি। বড় বৃত্তের যে জ্যা ছোট বৃত্তকে স্পর্শ করে তার দৈর্ঘ্য নির্ণয় কর।","a":"জ্যা কেন্দ্র থেকে 6 সেমি দূরে ⇒ জ্যা = 2√(100 − 36) = 16 সেমি","lv":"কঠিন","ex":"8.1"},{"n":"b17","q":"O কেন্দ্রবিশিষ্ট বৃত্তে OM ⊥ AB, AM = 4 সেমি এবং OM = 3 সেমি। AB ও ব্যাসার্ধ নির্ণয় কর।","a":"AB = 2AM = 8 সেমি\nব্যাসার্ধ = √(16 + 9) = 5 সেমি","lv":"মধ্যম","ex":"8.1"},{"n":"b18","q":"6 সেমি ব্যাসার্ধের বৃত্তে একটি জ্যা এর দৈর্ঘ্য ব্যাসার্ধের সমান। কেন্দ্র থেকে জ্যা টির দূরত্ব নির্ণয় কর।","a":"অর্ধজ্যা = 3 সেমি ⇒ দূরত্ব = √(36 − 9) = 3√3 সেমি","lv":"কঠিন","ex":"8.1"},{"n":"b19","q":"একই সরলরেখায় অবস্থিত নয় এমন তিনটি বিন্দু দিয়ে কয়টি বৃত্ত আঁকা যায়? একই সরলরেখায় থাকলে কয়টি?","a":"একরেখীয় নয় এমন তিন বিন্দু দিয়ে একটি এবং কেবল একটি বৃত্ত আঁকা যায়।\nএকরেখীয় হলে কোনো বৃত্ত আঁকা যায় না।","lv":"মধ্যম","ex":"8.1"},{"n":"b20","q":"দুইটি বৃত্ত পরস্পরকে A ও B বিন্দুতে ছেদ করে। প্রমাণ কর যে, কেন্দ্রদ্বয়ের সংযোজক রেখা AB এর লম্বদ্বিখণ্ডক।","a":"AB উভয় বৃত্তের সাধারণ জ্যা। প্রত্যেক কেন্দ্র A ও B থেকে সমদূরবর্তী।\nA ও B থেকে সমদূরবর্তী বিন্দুগুলো AB এর লম্বদ্বিখণ্ডকে থাকে ∴ কেন্দ্রদ্বয়ের সংযোজক রেখা AB এর লম্বদ্বিখণ্ডক।","lv":"কঠিন","ex":"8.1"},{"n":"b21","q":"10 সেমি ব্যাসার্ধের বৃত্তে 12 সেমি ও 16 সেমি দৈর্ঘ্যের দুইটি জ্যা আছে। কোনটি কেন্দ্রের নিকটতর? দূরত্ব দুইটি নির্ণয় কর।","a":"দূরত্ব: √(100 − 36) = 8 সেমি ও √(100 − 64) = 6 সেমি\n16 সেমি জ্যা টি কেন্দ্রের নিকটতর (বৃহত্তর জ্যা কেন্দ্রের নিকটতর)।","lv":"মধ্যম","ex":"8.1"},{"n":"b22","q":"26 সেমি ব্যাসবিশিষ্ট বৃত্তে 10 সেমি দৈর্ঘ্যের একটি জ্যা কেন্দ্র থেকে কত দূরে?","a":"ব্যাসার্ধ 13 সেমি ⇒ দূরত্ব = √(169 − 25) = 12 সেমি","lv":"মধ্যম","ex":"8.1"},{"n":"b23","q":"প্রমাণ কর যে, বৃত্তের দুইটি জ্যা পরস্পরকে সমদ্বিখণ্ডিত করলে জ্যা দুইটির প্রত্যেকে ব্যাস।","a":"AB ও CD, E তে পরস্পরকে সমদ্বিখণ্ডিত করলে E উভয়ের মধ্যবিন্দু।\nকেন্দ্র O ≠ E হলে OE ⊥ AB এবং OE ⊥ CD, যা অসম্ভব (AB, CD ভিন্ন দিকে)। ∴ E = O, উভয় জ্যা ব্যাস।","lv":"কঠিন","ex":"8.1"},{"n":"b24","q":"13 সেমি ব্যাসার্ধের একটি গোলাকার পাইপে পানির উপরিতলের প্রস্থ 24 সেমি। কেন্দ্রের নিচে পানি থাকলে পানির গভীরতা কত?","a":"কেন্দ্র থেকে পানিতলের দূরত্ব = √(169 − 144) = 5 সেমি\nগভীরতা = 13 − 5 = 8 সেমি","lv":"কঠিন","ex":"8.1"},{"n":"b25","q":"একটি বৃত্তচাপাকৃতি সেতুর জ্যা 16 মিটার এবং মাঝখানে উচ্চতা 4 মিটার। চাপটির ব্যাসার্ধ নির্ণয় কর।","a":"r² = 8² + (r − 4)² ⇒ 8r = 80 ⇒ r = 10 মিটার","lv":"কঠিন","ex":"8.1"},{"n":"b26","q":"17 সেমি ব্যাসার্ধের বৃত্তে 16 সেমি ও 30 সেমি দৈর্ঘ্যের দুইটি সমান্তরাল জ্যা কেন্দ্রের বিপরীত পাশে আছে। এদের মধ্যবর্তী দূরত্ব নির্ণয় কর।","a":"দূরত্ব: √(289 − 64) = 15 সেমি, √(289 − 225) = 8 সেমি\nমধ্যবর্তী দূরত্ব = 23 সেমি","lv":"কঠিন","ex":"8.1"},{"n":"b27","q":"একটি বৃত্তাকার চাকতির কেন্দ্র কীভাবে নির্ণয় করবে? ব্যাখ্যা কর।","a":"বৃত্তে যেকোনো দুইটি অসমান্তরাল জ্যা আঁকি এবং এদের লম্বদ্বিখণ্ডক টানি।\nজ্যা এর লম্বদ্বিখণ্ডক কেন্দ্রগামী, তাই লম্বদ্বিখণ্ডকদ্বয়ের ছেদবিন্দুই কেন্দ্র।","lv":"কঠিন","ex":"8.1"},{"n":"b28","q":"O কেন্দ্রবিশিষ্ট বৃত্তে AB = 24 সেমি জ্যা এর মধ্যবিন্দু M এবং OM = 5 সেমি। ব্যাসার্ধ নির্ণয় কর।","a":"OM ⊥ AB ⇒ OA = √(12² + 5²) = 13 সেমি","lv":"মধ্যম","ex":"8.1"},{"n":"b29","q":"5√2 সেমি ব্যাসার্ধের বৃত্তে 10 সেমি দৈর্ঘ্যের জ্যা AB। কেন্দ্র থেকে AB এর দূরত্ব এবং ∠AOB নির্ণয় কর।","a":"দূরত্ব = √(50 − 25) = 5 সেমি\nOA² + OB² = 50 + 50 = 100 = AB² ⇒ ∠AOB = 90°","lv":"কঠিন","ex":"8.1"},{"n":"b30","q":"5 সেমি ব্যাসার্ধের দুইটি সমান বৃত্ত পরস্পরকে ছেদ করে এবং সাধারণ জ্যা এর দৈর্ঘ্য 8 সেমি। কেন্দ্রদ্বয়ের দূরত্ব নির্ণয় কর।","a":"প্রত্যেক কেন্দ্র থেকে সাধারণ জ্যা এর দূরত্ব = √(25 − 16) = 3 সেমি\nকেন্দ্রদ্বয়ের দূরত্ব = 6 সেমি","lv":"কঠিন","ex":"8.1"},{"n":"b31","q":"একই চাপের উপর দণ্ডায়মান বৃত্তস্থ কোণ 35° হলে কেন্দ্রস্থ কোণ কত?","a":"কেন্দ্রস্থ কোণ = 2 × বৃত্তস্থ কোণ = 70°","lv":"মধ্যম","ex":"8.2"},{"n":"b32","q":"একটি চাপের উপর দণ্ডায়মান কেন্দ্রস্থ কোণ 140°। ঐ চাপের অবশিষ্ট (বৃহত্তর) অংশে ও ক্ষুদ্রতর চাপে অবস্থিত বৃত্তস্থ কোণ নির্ণয় কর।","a":"বৃহত্তর চাপে বৃত্তস্থ কোণ = 70°\nক্ষুদ্রতর চাপে বৃত্তস্থ কোণ = 180° − 70° = 110°","lv":"কঠিন","ex":"8.2"},{"n":"b33","q":"AB বৃত্তের ব্যাস এবং C বৃত্তের উপর একটি বিন্দু। ∠CAB = 43° হলে ∠CBA নির্ণয় কর।","a":"অর্ধবৃত্তস্থ কোণ ∠ACB = 90° ⇒ ∠CBA = 90° − 43° = 47°","lv":"মধ্যম","ex":"8.2"},{"n":"b34","q":"একই বৃত্তাংশে অবস্থিত দুইটি বৃত্তস্থ কোণ ∠ACB ও ∠ADB। ∠ACB = 40° হলে ∠ADB কত? কারণ লেখ।","a":"∠ADB = 40°, কারণ একই বৃত্তাংশস্থ কোণগুলো পরস্পর সমান।","lv":"মধ্যম","ex":"8.2"},{"n":"b35","q":"প্রমাণ কর যে, অর্ধবৃত্তস্থ কোণ এক সমকোণ।","a":"AB ব্যাস, C বৃত্তে। কেন্দ্রস্থ কোণ ∠AOB = 180° (সরলকোণ)\nবৃত্তস্থ কোণ = কেন্দ্রস্থ কোণের অর্ধেক ⇒ ∠ACB = 90°","lv":"মধ্যম","ex":"8.2"},{"n":"b36","q":"O কেন্দ্রবিশিষ্ট বৃত্তে AB জ্যা এবং ∠OAB = 25°। বৃহত্তর চাপে অবস্থিত C বিন্দুতে ∠ACB নির্ণয় কর।","a":"OA = OB ⇒ ∠OBA = 25°, ∠AOB = 130°\n∠ACB = 130°/2 = 65°","lv":"কঠিন","ex":"8.2"},{"n":"b37","q":"O কেন্দ্রবিশিষ্ট বৃত্তে ∠AOB = 100° হলে ∠OAB নির্ণয় কর।","a":"OA = OB ⇒ ∠OAB = (180° − 100°)/2 = 40°","lv":"মধ্যম","ex":"8.2"},{"n":"b38","q":"△ABC একটি বৃত্তে অন্তর্লিখিত এবং O কেন্দ্র। ∠BOC = 120° হলে ∠BAC নির্ণয় কর।","a":"∠BAC = ∠BOC/2 = 60°","lv":"মধ্যম","ex":"8.2"},{"n":"b39","q":"একটি বৃত্তে AB ও CD দুইটি জ্যা এর উপর দণ্ডায়মান কেন্দ্রস্থ কোণ সমান হলে জ্যা দুইটি সমান হবে — প্রমাণ কর।","a":"△AOB ও △COD এ OA = OC, OB = OD (ব্যাসার্ধ), ∠AOB = ∠COD\n∴ △AOB ≅ △COD (বাহু-কোণ-বাহু) ⇒ AB = CD","lv":"কঠিন","ex":"8.2"},{"n":"b40","q":"বৃত্তের ব্যাসার্ধের সমান একটি জ্যা কেন্দ্রে কত কোণ উৎপন্ন করে? বৃহত্তর চাপে ও ক্ষুদ্রতর চাপে বৃত্তস্থ কোণ কত?","a":"জ্যা = ব্যাসার্ধ ⇒ △OAB সমবাহু ⇒ কেন্দ্রস্থ কোণ 60°\nবৃহত্তর চাপে 30°, ক্ষুদ্রতর চাপে 150°","lv":"কঠিন","ex":"8.2"},{"n":"b41","q":"O কেন্দ্রবিশিষ্ট বৃত্তে অন্তর্লিখিত △ABC এ ∠BAC = 50°। ∠OBC নির্ণয় কর।","a":"∠BOC = 100°, OB = OC ⇒ ∠OBC = (180° − 100°)/2 = 40°","lv":"কঠিন","ex":"8.2"},{"n":"b42","q":"6 সেমি ব্যাসার্ধের বৃত্তে জ্যা AB এর উপর বৃহত্তর চাপে দণ্ডায়মান বৃত্তস্থ কোণ 30°। AB এর দৈর্ঘ্য নির্ণয় কর।","a":"কেন্দ্রস্থ কোণ = 60° ⇒ △OAB সমবাহু\nAB = 6 সেমি","lv":"কঠিন","ex":"8.2"},{"n":"b43","q":"বৃত্তের একটি জ্যা AB এর উপর বৃত্তস্থ কোণ ∠APB = 90° হলে AB সম্পর্কে কী বলা যায়?","a":"কেন্দ্রস্থ কোণ = 180° ⇒ AB একটি ব্যাস।","lv":"মধ্যম","ex":"8.2"},{"n":"b44","q":"AB বৃত্তের ব্যাস এবং C বৃত্তের উপর একটি বিন্দু। ∠ABC = 2∠BAC হলে কোণ দুইটি নির্ণয় কর।","a":"∠ACB = 90° ⇒ ∠BAC + 2∠BAC = 90° ⇒ ∠BAC = 30°, ∠ABC = 60°","lv":"মধ্যম","ex":"8.2"},{"n":"b45","q":"একটি বৃত্তে AC ও BD জ্যা দুইটি E বিন্দুতে ছেদ করে। ∠BAC = 35° এবং ∠ABD = 45° হলে ∠ACD, ∠BDC ও ∠AEB নির্ণয় কর।","a":"∠ACD = ∠ABD = 45° (AD চাপের উপর), ∠BDC = ∠BAC = 35° (BC চাপের উপর)\n∠AEB = 180° − 35° − 45° = 100°","lv":"কঠিন","ex":"8.2"},{"n":"b46","q":"প্রমাণ কর যে, বৃত্তের একই চাপের উপর দণ্ডায়মান কেন্দ্রস্থ কোণ বৃত্তস্থ কোণের দ্বিগুণ।","a":"C থেকে কেন্দ্রগামী CD টানি। △OAC সমদ্বিবাহু ⇒ ∠AOD = 2∠ACO\nএকইভাবে ∠BOD = 2∠BCO; যোগ করে ∠AOB = 2∠ACB","lv":"কঠিন","ex":"8.2"},{"n":"b47","q":"O কেন্দ্রবিশিষ্ট বৃত্তে অন্তর্লিখিত △ABC এ ∠A = 70°। ∠OBC নির্ণয় কর।","a":"∠BOC = 140° ⇒ ∠OBC = (180° − 140°)/2 = 20°","lv":"কঠিন","ex":"8.2"},{"n":"b48","q":"10 সেমি ব্যাসার্ধের বৃত্তে একটি জ্যা কেন্দ্রে 90° কোণ উৎপন্ন করে। জ্যা এর দৈর্ঘ্য নির্ণয় কর।","a":"জ্যা = √(10² + 10²) = 10√2 সেমি","lv":"মধ্যম","ex":"8.2"},{"n":"b49","q":"একটি চাপের প্রবৃদ্ধ কেন্দ্রস্থ কোণ 240° হলে বিপরীত ক্ষুদ্রতর চাপে বৃত্তস্থ কোণ কত?","a":"বৃত্তস্থ কোণ = 240°/2 = 120°","lv":"কঠিন","ex":"8.2"},{"n":"b50","q":"একই বৃত্তাংশে অবস্থিত দুইটি বৃত্তস্থ কোণ ∠ADB = 3x এবং ∠ACB = x + 40°। কোণটির মান নির্ণয় কর।","a":"একই বৃত্তাংশস্থ কোণ সমান ⇒ 3x = x + 40° ⇒ x = 20°\nকোণ = 60°","lv":"মধ্যম","ex":"8.2"},{"n":"b51","q":"O কেন্দ্রবিশিষ্ট বৃত্তে অন্তর্লিখিত △ABC এ AB = AC এবং ∠BAC = 40°। ∠BOC ও ∠OBC নির্ণয় কর।","a":"∠BOC = 2 × 40° = 80°\n∠OBC = (180° − 80°)/2 = 50°","lv":"কঠিন","ex":"8.2"},{"n":"b52","q":"বৃত্তের উপর A, B, C, D বিন্দুগুলো ক্রমানুসারে আছে। ∠ABD = 30° এবং ∠DBC = 40° হলে ∠ACD ও ∠CAD নির্ণয় কর।","a":"∠ACD = ∠ABD = 30° (AD চাপ)\n∠CAD = ∠CBD = 40° (CD চাপ)","lv":"কঠিন","ex":"8.2"},{"n":"b53","q":"AB বৃত্তের ব্যাস, C বৃত্তের উপর একটি বিন্দু, AC = 6 সেমি এবং BC = 8 সেমি। বৃত্তের ব্যাসার্ধ নির্ণয় কর।","a":"∠ACB = 90° ⇒ AB = √(36 + 64) = 10 সেমি\nব্যাসার্ধ = 5 সেমি","lv":"মধ্যম","ex":"8.2"},{"n":"b54","q":"AB বৃত্তের ব্যাস এবং C বৃত্তের উপর এমন বিন্দু যে AC = BC। ∠CAB নির্ণয় কর।","a":"∠ACB = 90° এবং AC = BC ⇒ ∠CAB = ∠CBA = 45°","lv":"মধ্যম","ex":"8.2"},{"n":"b55","q":"O কেন্দ্রবিশিষ্ট বৃত্তে ∠AOC = 150°। বৃহত্তর চাপের উপর অবস্থিত B বিন্দুতে ∠ABC নির্ণয় কর।","a":"∠ABC = 150°/2 = 75°","lv":"মধ্যম","ex":"8.2"},{"n":"b56","q":"BC ব্যাসবিশিষ্ট বৃত্তে A একটি বিন্দু এবং ∠ABC = 3∠ACB। কোণ দুইটি নির্ণয় কর।","a":"∠BAC = 90° ⇒ 4∠ACB = 90° ⇒ ∠ACB = 22.5°, ∠ABC = 67.5°","lv":"কঠিন","ex":"8.2"},{"n":"b57","q":"△ABC এ ∠BAC = 90° এবং BC = 10 সেমি। ত্রিভুজটির পরিবৃত্তের ব্যাসার্ধ কত?","a":"সমকোণী ত্রিভুজের অতিভুজ পরিবৃত্তের ব্যাস ⇒ ব্যাসার্ধ = 5 সেমি","lv":"মধ্যম","ex":"8.2"},{"n":"b58","q":"O কেন্দ্রবিশিষ্ট বৃত্তে AB জ্যা এবং বৃহত্তর চাপে C বিন্দুতে ∠ACB = 55°। ∠OAB নির্ণয় কর।","a":"∠AOB = 110° ⇒ ∠OAB = (180° − 110°)/2 = 35°","lv":"কঠিন","ex":"8.2"},{"n":"b59","q":"একই বৃত্তাংশস্থ দুইটি কোণ ∠ACB = (2x + 10)° ও ∠ADB = (3x − 15)°। x এর মান ও কোণটি নির্ণয় কর।","a":"2x + 10 = 3x − 15 ⇒ x = 25 ⇒ কোণ = 60°","lv":"মধ্যম","ex":"8.2"},{"n":"b60","q":"একটি সমকোণী ত্রিভুজের সমকোণ সংলগ্ন বাহুদ্বয় 5 সেমি ও 12 সেমি। এর পরিবৃত্তের ব্যাসার্ধ নির্ণয় কর।","a":"অতিভুজ = 13 সেমি = পরিবৃত্তের ব্যাস ⇒ ব্যাসার্ধ = 6.5 সেমি","lv":"মধ্যম","ex":"8.2"},{"n":"b61","q":"ABCD বৃত্তস্থ চতুর্ভুজে ∠A = 82° হলে ∠C নির্ণয় কর।","a":"বৃত্তস্থ চতুর্ভুজের বিপরীত কোণদ্বয় সম্পূরক ⇒ ∠C = 98°","lv":"মধ্যম","ex":"8.3"},{"n":"b62","q":"বৃত্তস্থ চতুর্ভুজের দুইটি বিপরীত কোণের অনুপাত 7 : 11। কোণ দুইটি নির্ণয় কর।","a":"18k = 180° ⇒ k = 10° ⇒ কোণ দুইটি 70° ও 110°","lv":"মধ্যম","ex":"8.3"},{"n":"b63","q":"ABCD বৃত্তস্থ চতুর্ভুজে ∠A = 92° এবং ∠B = 78°। ∠C ও ∠D নির্ণয় কর।","a":"∠C = 180° − 92° = 88°, ∠D = 180° − 78° = 102°","lv":"মধ্যম","ex":"8.3"},{"n":"b64","q":"ABCD বৃত্তস্থ চতুর্ভুজের BC বাহুকে E পর্যন্ত বর্ধিত করা হলো। ∠DCE = 100° হলে ∠A নির্ণয় কর।","a":"বৃত্তস্থ চতুর্ভুজের বহিঃস্থ কোণ বিপরীত অন্তঃস্থ কোণের সমান ⇒ ∠A = 100°","lv":"মধ্যম","ex":"8.3"},{"n":"b65","q":"প্রমাণ কর যে, বৃত্তস্থ চতুর্ভুজের যেকোনো দুইটি বিপরীত কোণের সমষ্টি দুই সমকোণ।","a":"O কেন্দ্র; BD চাপের উপর ∠A = (1/2)∠BOD (বৃহত্তর) এবং ∠C = (1/2) প্রবৃদ্ধ ∠BOD\n∠A + ∠C = (1/2) × 360° = 180°","lv":"কঠিন","ex":"8.3"},{"n":"b66","q":"কোনো চতুর্ভুজের দুইটি বিপরীত কোণ সম্পূরক হলে তার শীর্ষবিন্দু চারটি সম্পর্কে কী বলা যায়?","a":"শীর্ষবিন্দু চারটি সমবৃত্ত, অর্থাৎ এদের দিয়ে একটি বৃত্ত আঁকা যায়।","lv":"মধ্যম","ex":"8.3"},{"n":"b67","q":"ABCD বৃত্তস্থ চতুর্ভুজে ∠A = (2x + 10)° এবং ∠C = (3x − 5)°। কোণ দুইটি নির্ণয় কর।","a":"5x + 5 = 180 ⇒ x = 35\n∠A = 80°, ∠C = 100°","lv":"মধ্যম","ex":"8.3"},{"n":"b68","q":"প্রমাণ কর যে, কোনো সামান্তরিক বৃত্তস্থ হলে তা একটি আয়তক্ষেত্র।","a":"সামান্তরিকে বিপরীত কোণ সমান: ∠A = ∠C\nবৃত্তস্থ হলে ∠A + ∠C = 180° ⇒ ∠A = 90° ∴ আয়তক্ষেত্র","lv":"কঠিন","ex":"8.3"},{"n":"b69","q":"প্রমাণ কর যে, বৃত্তস্থ ট্রাপিজিয়াম সমদ্বিবাহু।","a":"AB ∥ DC হলে ∠A + ∠D = 180°; বৃত্তস্থ হওয়ায় ∠A + ∠C = 180° ⇒ ∠C = ∠D\nভূমি সংলগ্ন কোণ সমান ⇒ AD = BC","lv":"কঠিন","ex":"8.3"},{"n":"b70","q":"ABCD বৃত্তস্থ চতুর্ভুজে AB ব্যাস এবং ∠ADC = 120°। ∠BAC নির্ণয় কর।","a":"∠ABC = 180° − 120° = 60°, ∠ACB = 90° (অর্ধবৃত্তস্থ)\n∠BAC = 30°","lv":"কঠিন","ex":"8.3"},{"n":"b71","q":"ABCD বৃত্তস্থ চতুর্ভুজে ∠BAC = 40° হলে ∠BDC নির্ণয় কর।","a":"একই চাপ BC এর উপর বৃত্তস্থ কোণ ⇒ ∠BDC = 40°","lv":"মধ্যম","ex":"8.3"},{"n":"b72","q":"ABCD বৃত্তস্থ চতুর্ভুজে ∠ABD = 30° এবং ∠ADB = 70°। ∠BCD নির্ণয় কর।","a":"∠BAD = 180° − 100° = 80° ⇒ ∠BCD = 180° − 80° = 100°","lv":"কঠিন","ex":"8.3"},{"n":"b73","q":"ABCD বৃত্তস্থ চতুর্ভুজে ∠A = (x + 20)°, ∠C = (2x + 10)°, ∠B = y এবং ∠D = 2y। চারটি কোণ নির্ণয় কর।","a":"3x + 30 = 180 ⇒ x = 50; 3y = 180 ⇒ y = 60\n∠A = 70°, ∠B = 60°, ∠C = 110°, ∠D = 120°","lv":"কঠিন","ex":"8.3"},{"n":"b74","q":"বর্গ নয় এমন একটি রম্বস বৃত্তস্থ হতে পারে কি? যুক্তি দাও।","a":"রম্বসের বিপরীত কোণ সমান; বৃত্তস্থ হলে সমষ্টি 180° ⇒ প্রত্যেকে 90°, তখন এটি বর্গ।\n∴ বর্গ নয় এমন রম্বস বৃত্তস্থ হতে পারে না।","lv":"কঠিন","ex":"8.3"},{"n":"b75","q":"ABCD বৃত্তস্থ চতুর্ভুজে AB = AD এবং ∠BCD = 100°। ∠ABD নির্ণয় কর।","a":"∠BAD = 80°; AB = AD ⇒ ∠ABD = (180° − 80°)/2 = 50°","lv":"কঠিন","ex":"8.3"},{"n":"b76","q":"বৃত্তস্থ চতুর্ভুজ ABCD এর C শীর্ষে বহিঃস্থ কোণ 70°। ∠A ও ∠BCD নির্ণয় কর।","a":"∠A = বহিঃস্থ কোণ = 70°, ∠BCD = 110°","lv":"মধ্যম","ex":"8.3"},{"n":"b77","q":"ABCD বৃত্তস্থ চতুর্ভুজে ∠A − ∠C = 40°। ∠A ও ∠C নির্ণয় কর।","a":"∠A + ∠C = 180°, ∠A − ∠C = 40° ⇒ ∠A = 110°, ∠C = 70°","lv":"মধ্যম","ex":"8.3"},{"n":"b78","q":"প্রমাণ কর যে, বৃত্তস্থ চতুর্ভুজের একটি বাহু বর্ধিত করলে উৎপন্ন বহিঃস্থ কোণ বিপরীত অন্তঃস্থ কোণের সমান।","a":"BC কে E পর্যন্ত বাড়ালে ∠DCE + ∠BCD = 180°\nআবার ∠A + ∠BCD = 180° ∴ ∠DCE = ∠A","lv":"মধ্যম","ex":"8.3"},{"n":"b79","q":"প্রমাণ কর যে, সমদ্বিবাহু ট্রাপিজিয়াম বৃত্তস্থ।","a":"AB ∥ DC, AD = BC ⇒ ∠C = ∠D; আবার ∠A + ∠D = 180°\n∴ ∠A + ∠C = 180° ⇒ চতুর্ভুজটি বৃত্তস্থ","lv":"কঠিন","ex":"8.3"},{"n":"b80","q":"ABCD বৃত্তস্থ চতুর্ভুজের কর্ণদ্বয় E তে ছেদ করে। ∠ADB = 35° এবং ∠BDC = 40° হলে ∠ACB, ∠BAC ও ∠ABC নির্ণয় কর।","a":"∠ACB = ∠ADB = 35°, ∠BAC = ∠BDC = 40°\n∠ADC = 75° ⇒ ∠ABC = 105°","lv":"কঠিন","ex":"8.3"},{"n":"b81","q":"ABCD বৃত্তস্থ চতুর্ভুজে AB ∥ DC এবং ∠A = 70°। অপর কোণগুলো নির্ণয় কর।","a":"∠D = 180° − 70° = 110° (সমান্তরাল), ∠C = 180° − 70° = 110° (বৃত্তস্থ), ∠B = 70°","lv":"কঠিন","ex":"8.3"},{"n":"b82","q":"ABCD বৃত্তস্থ চতুর্ভুজে ∠B = 3∠D। ∠B ও ∠D নির্ণয় কর।","a":"4∠D = 180° ⇒ ∠D = 45°, ∠B = 135°","lv":"মধ্যম","ex":"8.3"},{"n":"b83","q":"ABCD বৃত্তস্থ চতুর্ভুজের AB বাহুকে E পর্যন্ত বর্ধিত করা হলো এবং ∠ABC = 85°। ∠CBE ও ∠ADC নির্ণয় কর।","a":"∠CBE = 180° − 85° = 95°\n∠ADC = 180° − 85° = 95° (= ∠CBE)","lv":"মধ্যম","ex":"8.3"},{"n":"b84","q":"একটি বৃত্তের উপর A, B, C, D চারটি বিন্দু এবং ∠ACB = 50°। C ও D একই পাশে হলে ∠ADB কত?","a":"একই বৃত্তাংশস্থ কোণ ⇒ ∠ADB = 50°","lv":"মধ্যম","ex":"8.3"},{"n":"b85","q":"ABCD বৃত্তস্থ চতুর্ভুজে AB ব্যাস এবং ∠ADC = 130°। ∠BAC নির্ণয় কর।","a":"∠ABC = 50°, ∠ACB = 90° ⇒ ∠BAC = 40°","lv":"কঠিন","ex":"8.3"},{"n":"b86","q":"5 সেমি ব্যাসার্ধের বৃত্তে অন্তর্লিখিত বর্গের বাহুর দৈর্ঘ্য নির্ণয় কর।","a":"বর্গের কর্ণ = ব্যাস = 10 সেমি ⇒ বাহু = 10/√2 = 5√2 সেমি","lv":"মধ্যম","ex":"8.3"},{"n":"b87","q":"13 সেমি ব্যাসার্ধের বৃত্তে অন্তর্লিখিত আয়তক্ষেত্রের একটি বাহু 10 সেমি। অপর বাহু নির্ণয় কর।","a":"কর্ণ = ব্যাস = 26 সেমি ⇒ অপর বাহু = √(676 − 100) = 24 সেমি","lv":"কঠিন","ex":"8.3"},{"n":"b88","q":"ABCD বৃত্তস্থ চতুর্ভুজে ∠A : ∠B : ∠C = 2 : 3 : 4। চারটি কোণ নির্ণয় কর।","a":"∠A + ∠C = 6k = 180° ⇒ k = 30°\n∠A = 60°, ∠B = 90°, ∠C = 120°, ∠D = 90°","lv":"কঠিন","ex":"8.3"},{"n":"b89","q":"বৃত্তস্থ চতুর্ভুজের দুইটি বিপরীত কোণ সমান হলে প্রত্যেকটির মান কত?","a":"x + x = 180° ⇒ x = 90°","lv":"মধ্যম","ex":"8.3"},{"n":"b90","q":"O কেন্দ্রবিশিষ্ট বৃত্তে ABCD বৃত্তস্থ চতুর্ভুজ এবং ∠BOD = 140°। ∠BAD ও ∠BCD নির্ণয় কর (A বৃহত্তর চাপে)।","a":"∠BAD = 140°/2 = 70°, ∠BCD = 180° − 70° = 110°","lv":"কঠিন","ex":"8.3"},{"n":"b91","q":"5 সেমি ব্যাসার্ধের বৃত্তের কেন্দ্র থেকে 13 সেমি দূরের একটি বিন্দু থেকে অঙ্কিত স্পর্শকের দৈর্ঘ্য নির্ণয় কর।","a":"স্পর্শক ⊥ ব্যাসার্ধ ⇒ দৈর্ঘ্য = √(13² − 5²) = 12 সেমি","lv":"মধ্যম","ex":"8.4"},{"n":"b92","q":"একটি বহিঃস্থ বিন্দু থেকে অঙ্কিত স্পর্শকের দৈর্ঘ্য 24 সেমি এবং বিন্দুটি কেন্দ্র থেকে 25 সেমি দূরে। ব্যাসার্ধ নির্ণয় কর।","a":"ব্যাসার্ধ = √(625 − 576) = 7 সেমি","lv":"মধ্যম","ex":"8.4"},{"n":"b93","q":"বহিঃস্থ বিন্দু P থেকে O কেন্দ্রবিশিষ্ট বৃত্তে PA ও PB স্পর্শক এবং ∠APB = 50°। ∠AOB নির্ণয় কর।","a":"OAPB চতুর্ভুজে ∠OAP = ∠OBP = 90° ⇒ ∠AOB = 360° − 180° − 50° = 130°","lv":"মধ্যম","ex":"8.4"},{"n":"b94","q":"বহিঃস্থ বিন্দু P থেকে PA ও PB স্পর্শক এবং ∠AOB = 110° (O কেন্দ্র)। ∠APB নির্ণয় কর।","a":"∠APB = 180° − 110° = 70°","lv":"মধ্যম","ex":"8.4"},{"n":"b95","q":"বহিঃস্থ বিন্দু P থেকে অঙ্কিত দুইটি স্পর্শক PA ও PB এবং PA = 8 সেমি। PB কত? কারণ লেখ।","a":"PB = 8 সেমি, কারণ বহিঃস্থ বিন্দু থেকে বৃত্তে অঙ্কিত দুইটি স্পর্শক সমান।","lv":"মধ্যম","ex":"8.4"},{"n":"b96","q":"প্রমাণ কর যে, বৃত্তের কোনো বিন্দুতে অঙ্কিত স্পর্শক ঐ বিন্দুগামী ব্যাসার্ধের উপর লম্ব।","a":"স্পর্শকের উপর স্পর্শবিন্দু P ছাড়া যেকোনো বিন্দু Q বৃত্তের বাইরে ⇒ OQ > OP\nকেন্দ্র থেকে স্পর্শকের ক্ষুদ্রতম দূরত্ব OP ⇒ OP ⊥ স্পর্শক","lv":"কঠিন","ex":"8.4"},{"n":"b97","q":"প্রমাণ কর যে, বহিঃস্থ বিন্দু থেকে বৃত্তে অঙ্কিত দুইটি স্পর্শক সমান।","a":"△OAP ও △OBP সমকোণী, OA = OB, OP সাধারণ\n∴ △OAP ≅ △OBP (অতিভুজ-বাহু) ⇒ PA = PB","lv":"কঠিন","ex":"8.4"},{"n":"b98","q":"5 সেমি ও 3 সেমি ব্যাসার্ধের দুইটি বৃত্ত পরস্পরকে বহিঃস্পর্শ ও অন্তঃস্পর্শ করলে কেন্দ্রদ্বয়ের দূরত্ব কত?","a":"বহিঃস্পর্শে: 5 + 3 = 8 সেমি\nঅন্তঃস্পর্শে: 5 − 3 = 2 সেমি","lv":"মধ্যম","ex":"8.4"},{"n":"b99","q":"5 সেমি ও 2 সেমি ব্যাসার্ধের দুইটি বৃত্তের কেন্দ্রদ্বয়ের দূরত্ব 5 সেমি। এদের সরল সাধারণ স্পর্শকের দৈর্ঘ্য নির্ণয় কর।","a":"দৈর্ঘ্য = √{d² − (r₁ − r₂)²} = √(25 − 9) = 4 সেমি","lv":"কঠিন","ex":"8.4"},{"n":"b100","q":"ABCD চতুর্ভুজের চারটি বাহু একটি বৃত্তকে স্পর্শ করে। AB = 6, BC = 7 এবং CD = 8 সেমি হলে AD নির্ণয় কর।","a":"বহিঃস্থ বিন্দু থেকে স্পর্শক সমান ⇒ AB + CD = BC + AD\n6 + 8 = 7 + AD ⇒ AD = 7 সেমি","lv":"কঠিন","ex":"8.4"},{"n":"b101","q":"△ABC এর অন্তর্বৃত্ত বাহুগুলোকে স্পর্শ করে। AB = 7, BC = 8, CA = 9 সেমি হলে A, B ও C থেকে স্পর্শবিন্দু পর্যন্ত দূরত্ব নির্ণয় কর।","a":"s = 12; A থেকে = s − BC = 4, B থেকে = s − CA = 3, C থেকে = s − AB = 5 সেমি","lv":"কঠিন","ex":"8.4"},{"n":"b102","q":"বৃত্তের A বিন্দুতে অঙ্কিত স্পর্শক ও জ্যা AB এর অন্তর্ভুক্ত কোণ 50°। একান্তর বৃত্তাংশে AB এর উপর বৃত্তস্থ কোণ কত?","a":"স্পর্শক ও জ্যা এর অন্তর্ভুক্ত কোণ একান্তর বৃত্তাংশস্থ কোণের সমান ⇒ 50°","lv":"কঠিন","ex":"8.4"},{"n":"b103","q":"O কেন্দ্রবিশিষ্ট বৃত্তে PA স্পর্শক, OP = 10 সেমি এবং ∠APO = 30°। ব্যাসার্ধ ও PA নির্ণয় কর।","a":"△OAP সমকোণী (A তে) ⇒ OA = OP sin30° = 5 সেমি\nPA = √(100 − 25) = 5√3 সেমি","lv":"কঠিন","ex":"8.4"},{"n":"b104","q":"বহিঃস্থ বিন্দু P থেকে 4 সেমি ব্যাসার্ধের বৃত্তে অঙ্কিত স্পর্শকদ্বয় পরস্পর লম্ব। PA ও PO নির্ণয় কর।","a":"OAPB বর্গ (তিনটি কোণ 90°, OA = OB) ⇒ PA = 4 সেমি\nPO = 4√2 সেমি","lv":"কঠিন","ex":"8.4"},{"n":"b105","q":"6 সেমি ব্যাসার্ধের বৃত্তের A বিন্দুতে স্পর্শক কেন্দ্রগামী একটি রেখাকে P তে ছেদ করে এবং ∠AOP = 60°। AP ও OP নির্ণয় কর।","a":"AP = OA tan60° = 6√3 সেমি\nOP = OA/cos60° = 12 সেমি","lv":"কঠিন","ex":"8.4"},{"n":"b106","q":"বৃত্তের ভেতরের, উপরের ও বাইরের কোনো বিন্দু থেকে বৃত্তে কয়টি স্পর্শক আঁকা যায়?","a":"ভেতরের বিন্দু থেকে 0টি, বৃত্তের উপরের বিন্দু থেকে 1টি, বাইরের বিন্দু থেকে 2টি।","lv":"মধ্যম","ex":"8.4"},{"n":"b107","q":"দুইটি বৃত্ত পরস্পরকে বহিঃস্পর্শ করলে এদের কয়টি সাধারণ স্পর্শক থাকে? অন্তঃস্পর্শ করলে কয়টি?","a":"বহিঃস্পর্শে 3টি, অন্তঃস্পর্শে 1টি।","lv":"মধ্যম","ex":"8.4"},{"n":"b108","q":"দুইটি এককেন্দ্রিক বৃত্তের ব্যাসার্ধ 13 সেমি ও 5 সেমি। বড় বৃত্তের যে জ্যা ছোট বৃত্তকে স্পর্শ করে তার দৈর্ঘ্য নির্ণয় কর।","a":"জ্যা স্পর্শবিন্দুতে সমদ্বিখণ্ডিত হয় ⇒ দৈর্ঘ্য = 2√(169 − 25) = 24 সেমি","lv":"কঠিন","ex":"8.4"},{"n":"b109","q":"ABCD চতুর্ভুজের বাহুগুলো একটি বৃত্তকে স্পর্শ করে। AB = (x + 2), BC = 7, CD = (2x − 1) এবং DA = 9 সেমি। x নির্ণয় কর।","a":"AB + CD = BC + DA ⇒ 3x + 1 = 16 ⇒ x = 5","lv":"কঠিন","ex":"8.4"},{"n":"b110","q":"বহিঃস্থ বিন্দু P থেকে PA ও PB স্পর্শক এবং ∠PAB = 65°। ∠APB নির্ণয় কর।","a":"PA = PB ⇒ ∠PBA = 65° ⇒ ∠APB = 180° − 130° = 50°","lv":"কঠিন","ex":"8.4"},{"n":"b111","q":"O কেন্দ্রবিশিষ্ট 8 সেমি ব্যাসার্ধের বৃত্তে PA স্পর্শক এবং OP = 17 সেমি। PA ও △OAP এর ক্ষেত্রফল নির্ণয় কর।","a":"PA = √(289 − 64) = 15 সেমি\nক্ষেত্রফল = (1/2) × 8 × 15 = 60 বর্গসেমি","lv":"কঠিন","ex":"8.4"},{"n":"b112","q":"কোনো রেখা বৃত্তের ব্যাসার্ধের প্রান্তবিন্দুতে ব্যাসার্ধের উপর লম্ব হলে রেখাটি সম্পর্কে কী বলা যায়?","a":"রেখাটি ঐ প্রান্তবিন্দুতে বৃত্তের স্পর্শক।","lv":"মধ্যম","ex":"8.4"},{"n":"b113","q":"3 সেমি ও 4 সেমি ব্যাসার্ধের দুইটি বৃত্তের কেন্দ্রদ্বয়ের দূরত্ব 7 সেমি। বৃত্তদ্বয়ের অবস্থান কেমন?","a":"দূরত্ব = 3 + 4 = ব্যাসার্ধদ্বয়ের যোগফল ⇒ বৃত্তদ্বয় পরস্পরকে বহিঃস্পর্শ করে।","lv":"মধ্যম","ex":"8.4"},{"n":"b114","q":"9 সেমি ও 4 সেমি ব্যাসার্ধের দুইটি বৃত্তের কেন্দ্রদ্বয়ের দূরত্ব 5 সেমি। বৃত্তদ্বয়ের অবস্থান কেমন?","a":"দূরত্ব = 9 − 4 = ব্যাসার্ধদ্বয়ের অন্তর ⇒ বৃত্তদ্বয় পরস্পরকে অন্তঃস্পর্শ করে।","lv":"মধ্যম","ex":"8.4"},{"n":"b115","q":"বহিঃস্থ বিন্দু P থেকে অঙ্কিত স্পর্শকের দৈর্ঘ্য 12 সেমি এবং P থেকে বৃত্তের নিকটতম বিন্দুর দূরত্ব 8 সেমি। ব্যাসার্ধ নির্ণয় কর।","a":"(r + 8)² = r² + 144 ⇒ 16r + 64 = 144 ⇒ r = 5 সেমি","lv":"কঠিন","ex":"8.4"},{"n":"b116","q":"বহিঃস্থ বিন্দু P থেকে PA ও PB স্পর্শক এবং OP = 2 × ব্যাসার্ধ। ∠APB নির্ণয় কর।","a":"sin∠APO = OA/OP = 1/2 ⇒ ∠APO = 30° ⇒ ∠APB = 60°","lv":"কঠিন","ex":"8.4"},{"n":"b117","q":"একটি সমকোণী ত্রিভুজের সমকোণ সংলগ্ন বাহুদ্বয় 6 সেমি ও 8 সেমি। এর অন্তর্বৃত্তের ব্যাসার্ধ নির্ণয় কর।","a":"অতিভুজ = 10 সেমি\nr = (6 + 8 − 10)/2 = 2 সেমি","lv":"কঠিন","ex":"8.4"},{"n":"b118","q":"10 সেমি বাহুবিশিষ্ট বর্গের চারটি বাহুকে স্পর্শ করে এমন বৃত্তের ব্যাসার্ধ কত?","a":"বৃত্তের ব্যাস = বর্গের বাহু = 10 সেমি ⇒ ব্যাসার্ধ 5 সেমি","lv":"মধ্যম","ex":"8.4"},{"n":"b119","q":"প্রমাণ কর যে, বৃত্তের কোনো ব্যাসের প্রান্তবিন্দুদ্বয়ে অঙ্কিত স্পর্শকদ্বয় পরস্পর সমান্তরাল।","a":"প্রতিটি স্পর্শক ব্যাসের উপর লম্ব।\nএকই রেখার উপর লম্ব দুইটি রেখা সমান্তরাল ∴ স্পর্শকদ্বয় সমান্তরাল।","lv":"মধ্যম","ex":"8.4"},{"n":"b120","q":"2 সেমি ব্যাসার্ধের বৃত্তকে পরিবেষ্টনকারী সমবাহু ত্রিভুজের বাহুর দৈর্ঘ্য নির্ণয় কর।","a":"সমবাহু ত্রিভুজে অন্তর্ব্যাসার্ধ r = a/(2√3) ⇒ a = 2√3 × 2 = 4√3 সেমি","lv":"কঠিন","ex":"8.4"},{"n":"b121","q":"ত্রিভুজের পরিবৃত্তের কেন্দ্র কোন রেখাগুলোর ছেদবিন্দু? এর বৈশিষ্ট্য কী?","a":"বাহুগুলোর লম্বদ্বিখণ্ডকত্রয়ের ছেদবিন্দু।\nএটি তিনটি শীর্ষবিন্দু থেকে সমদূরবর্তী।","lv":"মধ্যম","ex":"8.5"},{"n":"b122","q":"ত্রিভুজের অন্তর্বৃত্তের কেন্দ্র কোন রেখাগুলোর ছেদবিন্দু? এর বৈশিষ্ট্য কী?","a":"কোণগুলোর অন্তঃসমদ্বিখণ্ডকত্রয়ের ছেদবিন্দু।\nএটি তিনটি বাহু থেকে সমদূরবর্তী।","lv":"মধ্যম","ex":"8.5"},{"n":"b123","q":"একটি সমকোণী ত্রিভুজের সমকোণ সংলগ্ন বাহুদ্বয় 6 সেমি ও 8 সেমি। পরিকেন্দ্রের অবস্থান ও পরিব্যাসার্ধ নির্ণয় কর।","a":"পরিকেন্দ্র অতিভুজের মধ্যবিন্দু।\nঅতিভুজ = 10 সেমি ⇒ পরিব্যাসার্ধ = 5 সেমি","lv":"মধ্যম","ex":"8.5"},{"n":"b124","q":"6 সেমি বাহুবিশিষ্ট সমবাহু ত্রিভুজের পরিব্যাসার্ধ ও অন্তর্ব্যাসার্ধ নির্ণয় কর।","a":"R = a/√3 = 2√3 সেমি\nr = a/(2√3) = √3 সেমি","lv":"কঠিন","ex":"8.5"},{"n":"b125","q":"17 সেমি বাহুবিশিষ্ট বর্গক্ষেত্রের অন্তর্বৃত্তের ব্যাস কত?","a":"অন্তর্বৃত্তের ব্যাস = বর্গের বাহু = 17 সেমি","lv":"মধ্যম","ex":"8.5"},{"n":"b126","q":"2 সেমি বাহুবিশিষ্ট বর্গের পরিবৃত্তের ব্যাসার্ধ নির্ণয় কর।","a":"পরিবৃত্তের ব্যাস = কর্ণ = 2√2 সেমি ⇒ ব্যাসার্ধ √2 সেমি","lv":"মধ্যম","ex":"8.5"},{"n":"b127","q":"9 সেমি, 40 সেমি ও 41 সেমি বাহুবিশিষ্ট সমকোণী ত্রিভুজের অন্তর্ব্যাসার্ধ নির্ণয় কর।","a":"ক্ষেত্রফল = (1/2) × 9 × 40 = 180, s = 45\nr = ক্ষেত্রফল/s = 4 সেমি","lv":"কঠিন","ex":"8.5"},{"n":"b128","q":"5 সেমি, 12 সেমি ও 13 সেমি বাহুবিশিষ্ট ত্রিভুজের অন্তর্ব্যাসার্ধ ও পরিব্যাসার্ধ নির্ণয় কর।","a":"ক্ষেত্রফল = 30, s = 15 ⇒ r = 2 সেমি\nসমকোণী ⇒ R = 13/2 = 6.5 সেমি","lv":"কঠিন","ex":"8.5"},{"n":"b129","q":"13, 14 ও 15 সেমি বাহুবিশিষ্ট ত্রিভুজের অন্তর্ব্যাসার্ধ ও পরিব্যাসার্ধ নির্ণয় কর।","a":"s = 21, ক্ষেত্রফল = √(21 × 8 × 7 × 6) = 84 ⇒ r = 84/21 = 4 সেমি\nR = abc/(4 × ক্ষেত্রফল) = 2730/336 = 8.125 সেমি","lv":"কঠিন","ex":"8.5"},{"n":"b130","q":"স্থূলকোণী, সমকোণী ও সূক্ষ্মকোণী ত্রিভুজের পরিকেন্দ্র কোথায় অবস্থিত থাকে?","a":"স্থূলকোণী: ত্রিভুজের বাইরে; সমকোণী: অতিভুজের মধ্যবিন্দুতে; সূক্ষ্মকোণী: ত্রিভুজের ভেতরে।","lv":"কঠিন","ex":"8.5"},{"n":"b131","q":"একটি ত্রিভুজের পরিবৃত্ত আঁকার ধাপগুলো লেখ।","a":"1) যেকোনো দুই বাহুর লম্বদ্বিখণ্ডক আঁকি; এরা O তে ছেদ করে।\n2) O কে কেন্দ্র করে OA ব্যাসার্ধ নিয়ে বৃত্ত আঁকি। এটিই পরিবৃত্ত।","lv":"মধ্যম","ex":"8.5"},{"n":"b132","q":"একটি ত্রিভুজের অন্তর্বৃত্ত আঁকার ধাপগুলো লেখ।","a":"1) যেকোনো দুই কোণের সমদ্বিখণ্ডক আঁকি; এরা I তে ছেদ করে।\n2) I থেকে একটি বাহুর উপর লম্ব ID আঁকি। I কে কেন্দ্র করে ID ব্যাসার্ধে বৃত্ত আঁকি।","lv":"মধ্যম","ex":"8.5"},{"n":"b133","q":"বৃত্তের বহিঃস্থ বিন্দু থেকে বৃত্তে স্পর্শক আঁকার ধাপগুলো লেখ।","a":"1) কেন্দ্র O ও বহিঃস্থ বিন্দু P যোগ করি; OP এর মধ্যবিন্দু M নির্ণয় করি।\n2) M কে কেন্দ্র করে MO ব্যাসার্ধে বৃত্ত আঁকি, যা প্রদত্ত বৃত্তকে A ও B তে ছেদ করে।\n3) PA ও PB নির্ণেয় স্পর্শক।","lv":"কঠিন","ex":"8.5"},{"n":"b134","q":"বৃত্তের উপরের কোনো বিন্দুতে স্পর্শক আঁকার ধাপগুলো লেখ।","a":"1) কেন্দ্র O ও বৃত্তের বিন্দু P যোগ করি।\n2) P বিন্দুতে OP এর উপর লম্ব আঁকি। এই লম্বই P বিন্দুতে স্পর্শক।","lv":"মধ্যম","ex":"8.5"},{"n":"b135","q":"6 সেমি × 8 সেমি আয়তক্ষেত্রের পরিবৃত্তের ব্যাসার্ধ নির্ণয় কর।","a":"কর্ণ = 10 সেমি = পরিবৃত্তের ব্যাস ⇒ ব্যাসার্ধ 5 সেমি","lv":"মধ্যম","ex":"8.5"},{"n":"b136","q":"4 সেমি বাহুবিশিষ্ট সুষম ষড়ভুজের পরিবৃত্তের ব্যাসার্ধ কত?","a":"সুষম ষড়ভুজ কেন্দ্রে 6টি সমবাহু ত্রিভুজ তৈরি করে ⇒ ব্যাসার্ধ = বাহু = 4 সেমি","lv":"কঠিন","ex":"8.5"},{"n":"b137","q":"6 সেমি ব্যাসার্ধের বৃত্তে অন্তর্লিখিত সমবাহু ত্রিভুজের বাহুর দৈর্ঘ্য নির্ণয় কর।","a":"a = R√3 = 6√3 সেমি","lv":"কঠিন","ex":"8.5"},{"n":"b138","q":"7 সেমি ব্যাসার্ধের বৃত্তে অন্তর্লিখিত বর্গের বাহু ও ক্ষেত্রফল নির্ণয় কর।","a":"কর্ণ = 14 সেমি ⇒ বাহু = 7√2 সেমি\nক্ষেত্রফল = 98 বর্গসেমি","lv":"মধ্যম","ex":"8.5"},{"n":"b139","q":"12 সেমি বাহুবিশিষ্ট সমবাহু ত্রিভুজের অন্তর্বৃত্তের ব্যাসার্ধ নির্ণয় কর।","a":"r = a/(2√3) = 12/(2√3) = 2√3 সেমি","lv":"মধ্যম","ex":"8.5"},{"n":"b140","q":"10 সেমি, 10 সেমি ও 12 সেমি বাহুবিশিষ্ট সমদ্বিবাহু ত্রিভুজের অন্তর্ব্যাসার্ধ ও পরিব্যাসার্ধ নির্ণয় কর।","a":"উচ্চতা = 8, ক্ষেত্রফল = 48, s = 16 ⇒ r = 3 সেমি\nR = (10 × 10 × 12)/(4 × 48) = 6.25 সেমি","lv":"কঠিন","ex":"8.5"},{"n":"b141","q":"কোন ত্রিভুজের পরিকেন্দ্র, অন্তঃকেন্দ্র ও ভরকেন্দ্র একই বিন্দু?","a":"সমবাহু ত্রিভুজের।","lv":"মধ্যম","ex":"8.5"},{"n":"b142","q":"একটি সমকোণী ত্রিভুজের অতিভুজ 26 সেমি। এর পরিব্যাসার্ধ কত?","a":"পরিব্যাসার্ধ = অতিভুজ/2 = 13 সেমি","lv":"মধ্যম","ex":"8.5"},{"n":"b143","q":"△ABC এর অন্তর্বৃত্ত BC কে D বিন্দুতে স্পর্শ করে। AB = 10, AC = 8 এবং BC = 12 সেমি হলে BD ও CD নির্ণয় কর।","a":"s = 15; BD = s − AC = 7 সেমি, CD = s − AB = 5 সেমি","lv":"কঠিন","ex":"8.5"},{"n":"b144","q":"একই সরলরেখায় নয় এমন তিনটি বিন্দু দিয়ে বৃত্ত আঁকার ধাপ লেখ।","a":"বিন্দু তিনটি A, B, C হলে AB ও BC এর লম্বদ্বিখণ্ডক আঁকি; ছেদবিন্দু O।\nO কে কেন্দ্র করে OA ব্যাসার্ধে বৃত্ত আঁকি।","lv":"মধ্যম","ex":"8.5"},{"n":"b145","q":"3 সেমি, 4 সেমি ও 5 সেমি বাহুবিশিষ্ট ত্রিভুজের অন্তর্ব্যাসার্ধ নির্ণয় কর।","a":"ক্ষেত্রফল = 6, s = 6 ⇒ r = 1 সেমি","lv":"মধ্যম","ex":"8.5"},{"n":"b146","q":"সমবাহু ত্রিভুজের পরিব্যাসার্ধ ও অন্তর্ব্যাসার্ধের অনুপাত নির্ণয় কর।","a":"R = a/√3, r = a/(2√3) ⇒ R : r = 2 : 1","lv":"কঠিন","ex":"8.5"},{"n":"b147","q":"সমকোণ সংলগ্ন বাহু 4 সেমি করে এমন সমদ্বিবাহু সমকোণী ত্রিভুজের অন্তর্ব্যাসার্ধ নির্ণয় কর।","a":"অতিভুজ = 4√2 সেমি\nr = (4 + 4 − 4√2)/2 = 4 − 2√2 সেমি","lv":"কঠিন","ex":"8.5"},{"n":"b148","q":"5 সেমি ব্যাসার্ধের বৃত্তে অন্তর্লিখিত সুষম ষড়ভুজের পরিসীমা নির্ণয় কর।","a":"বাহু = ব্যাসার্ধ = 5 সেমি ⇒ পরিসীমা = 30 সেমি","lv":"মধ্যম","ex":"8.5"},{"n":"b149","q":"একটি রম্বসের কর্ণদ্বয় 6 সেমি ও 8 সেমি। রম্বসের চারটি বাহুকে স্পর্শ করে এমন বৃত্তের ব্যাসার্ধ নির্ণয় কর।","a":"বাহু = 5 সেমি, ক্ষেত্রফল = 24 বর্গসেমি\nক্ষেত্রফল = (1/2) × পরিসীমা × r ⇒ 24 = 10r ⇒ r = 2.4 সেমি","lv":"কঠিন","ex":"8.5"},{"n":"b150","q":"10 সেমি ব্যাসবিশিষ্ট বৃত্তে অন্তর্লিখিত বর্গের ক্ষেত্রফল নির্ণয় কর।","a":"বর্গের কর্ণ = ব্যাস = 10 সেমি\nক্ষেত্রফল = কর্ণ²/2 = 50 বর্গসেমি","lv":"মধ্যম","ex":"8.5"}],"9":[{"n":"b1","q":"θ সূক্ষ্মকোণ এবং sinθ = 3/5 হলে cosθ ও tanθ নির্ণয় কর।","a":"cosθ = √(1 − 9/25) = 4/5\ntanθ = (3/5)/(4/5) = 3/4","lv":"মধ্যম","ex":"9.1"},{"n":"b2","q":"tanθ = 5/12 হলে sinθ ও secθ নির্ণয় কর (θ সূক্ষ্মকোণ)।","a":"অতিভুজ = √(25 + 144) = 13\nsinθ = 5/13, secθ = 13/12","lv":"মধ্যম","ex":"9.1"},{"n":"b3","q":"θ সূক্ষ্মকোণ এবং cosθ = 24/25 হলে cosecθ নির্ণয় কর।","a":"sinθ = √(1 − 576/625) = 7/25 ⇒ cosecθ = 25/7","lv":"মধ্যম","ex":"9.1"},{"n":"b4","q":"secθ = 13/5 হলে (2sinθ − 3cosθ)/(4sinθ − 9cosθ) এর মান নির্ণয় কর (θ সূক্ষ্মকোণ)।","a":"cosθ = 5/13, sinθ = 12/13\nমান = (24 − 15)/(48 − 45) = 3","lv":"কঠিন","ex":"9.1"},{"n":"b5","q":"tanθ = 9/40 হলে (sinθ + cosθ)/(sinθ − cosθ) এর মান নির্ণয় কর।","a":"লব-হরকে cosθ দিয়ে ভাগ করে = (tanθ + 1)/(tanθ − 1) = (49/40)/(−31/40) = −49/31","lv":"কঠিন","ex":"9.1"},{"n":"b6","q":"প্রমাণ কর যে, (1 − sin²θ)sec²θ = 1","a":"বামপক্ষ = cos²θ × 1/cos²θ = 1","lv":"মধ্যম","ex":"9.1"},{"n":"b7","q":"প্রমাণ কর যে, tanθ + cotθ = secθ cosecθ","a":"বামপক্ষ = sinθ/cosθ + cosθ/sinθ = (sin²θ + cos²θ)/(sinθ cosθ) = 1/(sinθ cosθ) = secθ cosecθ","lv":"মধ্যম","ex":"9.1"},{"n":"b8","q":"প্রমাণ কর যে, (1 + tan²θ)cos²θ = 1","a":"বামপক্ষ = sec²θ × cos²θ = 1","lv":"মধ্যম","ex":"9.1"},{"n":"b9","q":"প্রমাণ কর যে, sinθ/(1 + cosθ) + (1 + cosθ)/sinθ = 2cosecθ","a":"বামপক্ষ = {sin²θ + (1 + cosθ)²}/{sinθ(1 + cosθ)} = (2 + 2cosθ)/{sinθ(1 + cosθ)} = 2/sinθ = 2cosecθ","lv":"কঠিন","ex":"9.1"},{"n":"b10","q":"প্রমাণ কর যে, (secθ − tanθ)(secθ + tanθ) = 1","a":"বামপক্ষ = sec²θ − tan²θ = 1","lv":"মধ্যম","ex":"9.1"},{"n":"b11","q":"প্রমাণ কর যে, 1/(1 + sinθ) + 1/(1 − sinθ) = 2sec²θ","a":"বামপক্ষ = (1 − sinθ + 1 + sinθ)/(1 − sin²θ) = 2/cos²θ = 2sec²θ","lv":"কঠিন","ex":"9.1"},{"n":"b12","q":"প্রমাণ কর যে, √{(1 − cosθ)/(1 + cosθ)} = cosecθ − cotθ","a":"লব-হরকে (1 − cosθ) দিয়ে গুণ করে = √{(1 − cosθ)²/sin²θ} = (1 − cosθ)/sinθ = cosecθ − cotθ","lv":"কঠিন","ex":"9.1"},{"n":"b13","q":"প্রমাণ কর যে, (sinθ + cosθ)² + (sinθ − cosθ)² = 2","a":"বামপক্ষ = 2(sin²θ + cos²θ) = 2","lv":"মধ্যম","ex":"9.1"},{"n":"b14","q":"প্রমাণ কর যে, sin⁴θ − cos⁴θ = sin²θ − cos²θ","a":"বামপক্ষ = (sin²θ + cos²θ)(sin²θ − cos²θ) = sin²θ − cos²θ","lv":"মধ্যম","ex":"9.1"},{"n":"b15","q":"প্রমাণ কর যে, cos⁴θ − sin⁴θ = 1 − 2sin²θ","a":"বামপক্ষ = (cos²θ − sin²θ)(cos²θ + sin²θ) = 1 − sin²θ − sin²θ = 1 − 2sin²θ","lv":"কঠিন","ex":"9.1"},{"n":"b16","q":"sinθ + cosθ = √2 হলে sinθ cosθ এর মান নির্ণয় কর।","a":"বর্গ করে 1 + 2sinθ cosθ = 2 ⇒ sinθ cosθ = 1/2","lv":"কঠিন","ex":"9.1"},{"n":"b17","q":"tanθ + cotθ = 2 হলে tan²θ + cot²θ এর মান নির্ণয় কর।","a":"বর্গ করে tan²θ + 2 + cot²θ = 4 ⇒ tan²θ + cot²θ = 2","lv":"কঠিন","ex":"9.1"},{"n":"b18","q":"cotθ = √3 হলে (cosec²θ − sec²θ)/(cosec²θ + sec²θ) এর মান নির্ণয় কর।","a":"cosec²θ = 1 + 3 = 4, sec²θ = 1 + 1/3 = 4/3\nমান = (8/3)/(16/3) = 1/2","lv":"কঠিন","ex":"9.1"},{"n":"b19","q":"5cosθ = 3 হলে (cosecθ − cotθ)/(cosecθ + cotθ) এর মান নির্ণয় কর।","a":"cosθ = 3/5, sinθ = 4/5 ⇒ cosecθ = 5/4, cotθ = 3/4\nমান = (2/4)/(8/4) = 1/4","lv":"কঠিন","ex":"9.1"},{"n":"b20","q":"secθ + tanθ = 5/2 হলে sinθ এর মান নির্ণয় কর।","a":"secθ − tanθ = 1/(secθ + tanθ) = 2/5\nsecθ = 29/20, tanθ = 21/20 ⇒ sinθ = tanθ/secθ = 21/29","lv":"কঠিন","ex":"9.1"},{"n":"b21","q":"প্রমাণ কর যে, tanθ/(secθ − 1) = (secθ + 1)/tanθ","a":"tan²θ = sec²θ − 1 = (secθ − 1)(secθ + 1)\nউভয় পক্ষকে tanθ(secθ − 1) দিয়ে ভাগ করে প্রমাণিত।","lv":"কঠিন","ex":"9.1"},{"n":"b22","q":"প্রমাণ কর যে, cosθ/(1 − tanθ) + sinθ/(1 − cotθ) = sinθ + cosθ","a":"= cos²θ/(cosθ − sinθ) + sin²θ/(sinθ − cosθ) = (cos²θ − sin²θ)/(cosθ − sinθ) = cosθ + sinθ","lv":"কঠিন","ex":"9.1"},{"n":"b23","q":"প্রমাণ কর যে, (1 + cotθ − cosecθ)(1 + tanθ + secθ) = 2","a":"= {(sinθ + cosθ − 1)/sinθ} × {(cosθ + sinθ + 1)/cosθ} = {(sinθ + cosθ)² − 1}/(sinθ cosθ) = 2sinθ cosθ/(sinθ cosθ) = 2","lv":"কঠিন","ex":"9.1"},{"n":"b24","q":"△ABC এ ∠B = 90°, AB = 8 সেমি এবং BC = 6 সেমি। sinA ও cosC নির্ণয় কর।","a":"AC = 10 সেমি\nsinA = BC/AC = 3/5, cosC = BC/AC = 3/5","lv":"মধ্যম","ex":"9.1"},{"n":"b25","q":"cosA = 4/5 হলে (1 − tan²A)/(1 + tan²A) এর মান নির্ণয় কর।","a":"tanA = 3/4 ⇒ মান = (1 − 9/16)/(1 + 9/16) = 7/25","lv":"কঠিন","ex":"9.1"},{"n":"b26","q":"প্রমাণ কর যে, sec²θ + cosec²θ = sec²θ cosec²θ","a":"বামপক্ষ = 1/cos²θ + 1/sin²θ = (sin²θ + cos²θ)/(sin²θ cos²θ) = sec²θ cosec²θ","lv":"কঠিন","ex":"9.1"},{"n":"b27","q":"প্রমাণ কর যে, (cosecθ − sinθ)(secθ − cosθ)(tanθ + cotθ) = 1","a":"= (cos²θ/sinθ)(sin²θ/cosθ) × 1/(sinθ cosθ) = 1","lv":"কঠিন","ex":"9.1"},{"n":"b28","q":"3sinθ = 2 হলে cosθ ও tanθ নির্ণয় কর (θ সূক্ষ্মকোণ)।","a":"sinθ = 2/3 ⇒ cosθ = √(1 − 4/9) = √5/3\ntanθ = 2/√5","lv":"মধ্যম","ex":"9.1"},{"n":"b29","q":"a cosθ = b হলে tanθ কে a ও b এর মাধ্যমে প্রকাশ কর (θ সূক্ষ্মকোণ)।","a":"cosθ = b/a ⇒ sinθ = √(a² − b²)/a\ntanθ = √(a² − b²)/b","lv":"কঠিন","ex":"9.1"},{"n":"b30","q":"প্রমাণ কর যে, (1 − sinθ)/(1 + sinθ) = (secθ − tanθ)²","a":"ডানপক্ষ = {(1 − sinθ)/cosθ}² = (1 − sinθ)²/(1 − sin²θ) = (1 − sinθ)/(1 + sinθ)","lv":"কঠিন","ex":"9.1"},{"n":"b31","q":"মান নির্ণয় কর: sin60° cos30° + cos60° sin30°","a":"= (√3/2)(√3/2) + (1/2)(1/2) = 3/4 + 1/4 = 1","lv":"মধ্যম","ex":"9.2"},{"n":"b32","q":"মান নির্ণয় কর: cos²30° − sin²30°","a":"= 3/4 − 1/4 = 1/2","lv":"মধ্যম","ex":"9.2"},{"n":"b33","q":"মান নির্ণয় কর: (1 − tan²30°)/(1 + tan²30°)","a":"= (1 − 1/3)/(1 + 1/3) = (2/3)/(4/3) = 1/2","lv":"মধ্যম","ex":"9.2"},{"n":"b34","q":"মান নির্ণয় কর: tan30° × tan60°","a":"= (1/√3) × √3 = 1","lv":"মধ্যম","ex":"9.2"},{"n":"b35","q":"A = 30° হলে যাচাই কর যে, sin3A = 3sinA − 4sin³A","a":"বামপক্ষ = sin90° = 1\nডানপক্ষ = 3/2 − 4 × 1/8 = 1 ∴ সমান।","lv":"কঠিন","ex":"9.2"},{"n":"b36","q":"মান নির্ণয় কর: 3tan²30° + 4sin²60° − 2cos²45°","a":"= 3 × 1/3 + 4 × 3/4 − 2 × 1/2 = 1 + 3 − 1 = 3","lv":"মধ্যম","ex":"9.2"},{"n":"b37","q":"θ = 30° হলে যাচাই কর যে, sin2θ = 2sinθ cosθ","a":"বামপক্ষ = sin60° = √3/2\nডানপক্ষ = 2 × 1/2 × √3/2 = √3/2 ∴ সমান।","lv":"মধ্যম","ex":"9.2"},{"n":"b38","q":"θ = 30° হলে যাচাই কর যে, cos2θ = 1 − 2sin²θ","a":"বামপক্ষ = cos60° = 1/2\nডানপক্ষ = 1 − 2 × 1/4 = 1/2 ∴ সমান।","lv":"মধ্যম","ex":"9.2"},{"n":"b39","q":"θ = 30° হলে যাচাই কর যে, tan2θ = 2tanθ/(1 − tan²θ)","a":"বামপক্ষ = tan60° = √3\nডানপক্ষ = (2/√3)/(2/3) = 3/√3 = √3 ∴ সমান।","lv":"কঠিন","ex":"9.2"},{"n":"b40","q":"সমাধান কর: 2cosθ = 1 (0° < θ < 90°)","a":"cosθ = 1/2 = cos60° ⇒ θ = 60°","lv":"মধ্যম","ex":"9.2"},{"n":"b41","q":"সমাধান কর: 2sinθ − √3 = 0 (0° < θ < 90°)","a":"sinθ = √3/2 = sin60° ⇒ θ = 60°","lv":"মধ্যম","ex":"9.2"},{"n":"b42","q":"সমাধান কর: √3 tanθ = 1 (0° < θ < 90°)","a":"tanθ = 1/√3 = tan30° ⇒ θ = 30°","lv":"মধ্যম","ex":"9.2"},{"n":"b43","q":"সমাধান কর: tanθ = cotθ (0° < θ < 90°)","a":"tan²θ = 1 ⇒ tanθ = 1 ⇒ θ = 45°","lv":"মধ্যম","ex":"9.2"},{"n":"b44","q":"cotθ = √3 হলে θ ও sinθ এর মান নির্ণয় কর (θ সূক্ষ্মকোণ)।","a":"cotθ = √3 = cot30° ⇒ θ = 30°, sinθ = 1/2","lv":"মধ্যম","ex":"9.2"},{"n":"b45","q":"সমাধান কর: 2sin²θ = 3cosθ (0° < θ < 90°)","a":"2 − 2cos²θ = 3cosθ ⇒ 2cos²θ + 3cosθ − 2 = 0 ⇒ (2cosθ − 1)(cosθ + 2) = 0\ncosθ = 1/2 ⇒ θ = 60°","lv":"কঠিন","ex":"9.2"},{"n":"b46","q":"সমাধান কর: tan²θ − (1 + √3)tanθ + √3 = 0 (0° < θ < 90°)","a":"(tanθ − 1)(tanθ − √3) = 0 ⇒ tanθ = 1 বা √3\nθ = 45° অথবা 60°","lv":"কঠিন","ex":"9.2"},{"n":"b47","q":"সমাধান কর: sinθ + cosθ = √2 (0° < θ < 90°)","a":"বর্গ করে 1 + 2sinθ cosθ = 2 ⇒ sinθ cosθ = 1/2 ⇒ (sinθ − cosθ)² = 0\nsinθ = cosθ ⇒ θ = 45°","lv":"কঠিন","ex":"9.2"},{"n":"b48","q":"সমাধান কর: cos²θ − sin²θ = 1/2 (0° < θ < 90°)","a":"1 − 2sin²θ = 1/2 ⇒ sin²θ = 1/4 ⇒ sinθ = 1/2 ⇒ θ = 30°","lv":"কঠিন","ex":"9.2"},{"n":"b49","q":"tan(A + B) = √3 এবং tan(A − B) = 1/√3 হলে A ও B নির্ণয় কর (A + B সূক্ষ্মকোণ)।","a":"A + B = 60°, A − B = 30° ⇒ A = 45°, B = 15°","lv":"কঠিন","ex":"9.2"},{"n":"b50","q":"sin(A + B) = 1 এবং cos(A − B) = √3/2 হলে A ও B নির্ণয় কর।","a":"A + B = 90°, A − B = 30° ⇒ A = 60°, B = 30°","lv":"কঠিন","ex":"9.2"},{"n":"b51","q":"মান নির্ণয় কর: (sin²60° + cos²45°)/tan²30°","a":"= (3/4 + 1/2)/(1/3) = (5/4) × 3 = 15/4","lv":"কঠিন","ex":"9.2"},{"n":"b52","q":"মান নির্ণয় কর: cot²30° − 2cos²60° − (3/4)sec²45° − 4sin²30°","a":"= 3 − 1/2 − 3/2 − 1 = 0","lv":"কঠিন","ex":"9.2"},{"n":"b53","q":"θ = 45° হলে sec²θ + cosec²θ এর মান নির্ণয় কর।","a":"= 2 + 2 = 4","lv":"মধ্যম","ex":"9.2"},{"n":"b54","q":"tan90° অসংজ্ঞায়িত কেন? ব্যাখ্যা কর।","a":"tan90° = sin90°/cos90° = 1/0, শূন্য দিয়ে ভাগ সংজ্ঞায়িত নয়।\nθ, 90° এর দিকে বাড়লে tanθ অসীমভাবে বাড়ে।","lv":"মধ্যম","ex":"9.2"},{"n":"b55","q":"△ABC এ ∠B = 90°, ∠A = 30° এবং AC = 20 সেমি। BC ও AB নির্ণয় কর।","a":"BC = AC sin30° = 10 সেমি\nAB = AC cos30° = 10√3 সেমি","lv":"মধ্যম","ex":"9.2"},{"n":"b56","q":"△ABC এ ∠C = 90°, ∠A = 60° এবং BC = 6√3 সেমি। AC ও AB নির্ণয় কর।","a":"tan60° = BC/AC ⇒ AC = 6√3/√3 = 6 সেমি\nAB = AC/cos60° = 12 সেমি","lv":"কঠিন","ex":"9.2"},{"n":"b57","q":"A সূক্ষ্মকোণ এবং sinA = cosA হলে A এর মান ও tanA নির্ণয় কর।","a":"tanA = sinA/cosA = 1 ⇒ A = 45°","lv":"মধ্যম","ex":"9.2"},{"n":"b58","q":"মান নির্ণয় কর: sin0° + cos90° + tan45°","a":"= 0 + 0 + 1 = 1","lv":"মধ্যম","ex":"9.2"},{"n":"b59","q":"দেখাও যে, (tan60° − tan30°)/(1 + tan60° tan30°) = tan30°","a":"বামপক্ষ = (√3 − 1/√3)/(1 + 1) = (2/√3)/2 = 1/√3 = tan30°","lv":"কঠিন","ex":"9.2"},{"n":"b60","q":"θ এর মান 0° থেকে 90° পর্যন্ত বাড়লে sinθ ও cosθ এর মান কীভাবে পরিবর্তিত হয়?","a":"sinθ এর মান 0 থেকে বেড়ে 1 হয়।\ncosθ এর মান 1 থেকে কমে 0 হয়।","lv":"মধ্যম","ex":"9.2"}]}};
